  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Německé muzeum', 'Technická památka v Německu — doly, železnice a stroje, na kterých stojí historie kraje.', 48.13, 11.58333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Deutsches%20Museum%20Portrait%204.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Deutsches%20Museum%20Portrait%204.jpg"}'::text[], 0, '{"en": {"name": "Deutsches Museum", "description": "Museum of science and technology in Munich, Germany. A technical monument in Germany — mines, railways and machines behind the region''s history."}, "de": {"name": "Deutsches Museum", "description": "Wissenschafts- und Technikmuseum in München, Deutschland. Ein technisches Denkmal in Deutschland — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Muzeum Niemieckie", "description": "Zabytek techniki w Niemczech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Deutsches Museum", "description": "Museum in München, Duitsland. Een technisch monument in Duitsland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Deutsches Museum", "description": "Un monumento técnico en Alemania: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Deutsches Museum", "description": "Musée en Allemagne à Munich. Un monument technique en Allemagne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Німецький музей", "description": "Технічна пам''ятка в Німеччині — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie v Mnichově', 'Katedrála v německém Mnichově. Památka v Německu — kus historie přímo u trasy.', 48.13858, 11.57362, 'http://commons.wikimedia.org/wiki/Special:FilePath/Frauenkirche%20Munich%20-%20View%20from%20Peterskirche%20Tower.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Frauenkirche%20Munich%20-%20View%20from%20Peterskirche%20Tower.jpg"}'::text[], 1, '{"en": {"name": "Frauenkirche", "description": "Church in Munich, Bavaria, Germany; cathedral of the archdiocese of Munich and Freising. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Frauenkirche, München", "description": "Kathedralkirche des katholischen Erzbistums München und Freising, Deutschland. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Marii Panny w Monachium", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Frauenkirche", "description": "München. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora de Múnich", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Munich", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Фрауенкірхе", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Královská rezidence Mnichov', 'Městský zámek a rezidence bavorských vévodů, kurfiřtů a králů. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.14105, 11.57871, 'http://commons.wikimedia.org/wiki/Special:FilePath/BAVIERA.%20M%C3%9ANICH.%20Residenz%20%28fachada%20occidental%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BAVIERA.%20M%C3%9ANICH.%20Residenz%20%28fachada%20occidental%29.jpg"}'::text[], 2, '{"en": {"name": "Munich Residence", "description": "Building in Munich, Upper Bavaria, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Residenz München", "description": "Größtes Innenstadtschloss Deutschlands. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Rezydencja w Monachium", "description": "Rezydencja królów Bawarii. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Munich Residenz", "description": "Stadsresidentie in classicistische stijl in de Duitse stad München. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Residencia de Múnich", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "résidence de Munich", "description": "Bâtiment de Munich, Haute-Bavière, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Мюнхенська Резиденція", "description": "Будівля у Верхній Баварії, Німеччина. Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Nymphenburg', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.15806, 11.50361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Nymphenburg%2C%20Weitwinkelansicht.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Nymphenburg%2C%20Weitwinkelansicht.jpg"}'::text[], 3, '{"en": {"name": "Nymphenburg Palace", "description": "Baroque palace in Munich, Bavaria, southern Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Nymphenburg", "description": "Schloss in München, Sommerresidenz. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Nymphenburg", "description": "Pałac w Monachium, Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "slot Nymphenburg", "description": "Bouwwerk in München. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Nymphenburg", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château Nymphenburg", "description": "Palais baroque à Munich, Bavière, sud de l''Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Німфенбург", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Schleißheim palace complex', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.24861, 11.56833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Schleissheim%20Palace.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Schleissheim%20Palace.jpg"}'::text[], 4, '{"en": {"name": "Schleißheim palace complex", "description": "Comprises three palaces in a grand baroque park in the village of Oberschleißheim near Munich, Bavaria, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schlossanlage Schleißheim", "description": "Schlosskomplex mit drei Schlössern in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Schleißheim", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Paleis van Schleißheim", "description": "Duits kastelencomplex. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Schleißheim", "description": "Complejo palaciego alemán. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Schleissheim", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Шляйсгайм", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Starnberské jezero', 'Jezero v Horním Bavorsku. Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 47.90389, 11.30722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Starnberg%20%28view%20from%20the%20south%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Starnberg%20%28view%20from%20the%20south%29.jpg"}'::text[], 5, '{"en": {"name": "Lake Starnberg", "description": "Lake in Bavaria, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Starnberger See", "description": "See in Bayern. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Starnberger See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Starnberger See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Starnberg", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Starnberg", "description": "5e plus grand lac d''Allemagne. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Штарнбергер-Зее", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Ammersee', 'Jezero v Bavorsku. Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 48.0, 11.11667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Ammersee%20%28view%20from%20the%20south%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Ammersee%20%28view%20from%20the%20south%29.jpg"}'::text[], 6, '{"en": {"name": "Ammersee", "description": "Lake in Upper Bavaria, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Ammersee", "description": "See in Oberbayern (Landkreise Landsberg am Lech und Weilheim-Schongau). Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Ammer", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Ammersee", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Ammer", "description": "Lago en la Alta Baviera, Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "lac Ammer", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Аммерзее", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
