    (v_route, 'Maritime, Fluvial and Harbor Museum of Rouen', 'Technická památka ve Francii — doly, železnice a stroje, na kterých stojí historie kraje.', 49.4447, 1.06074, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eingang%20zum%20Musee-maritime-de-rouen.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eingang%20zum%20Musee-maritime-de-rouen.jpg"}'::text[], 0, '{"en": {"name": "Maritime, Fluvial and Harbor Museum of Rouen", "description": "Museum in Rouen, France. A technical monument in France — mines, railways and machines behind the region''s history."}, "de": {"name": "Musée maritime, fluvial et portuaire de Rouen", "description": "Museum in Rouen, Frankreich, schildert die Geschichte des Hafens von Rouen. Ein technisches Denkmal in Frankreich — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Musée maritime fluvial et portuaire de Rouen", "description": "Zabytek techniki we Francji — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Musée maritime fluvial et portuaire de Rouen", "description": "Museum in Frankrijk. Een technisch monument in Frankrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo Marítimo, Fluvial y Portuario de Ruan", "description": "Museo francés. Un monumento técnico en Francia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "musée maritime fluvial et portuaire de Rouen", "description": "Musée français. Un monument technique en France — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Морський, річковий і портовий музей Руана", "description": "Музей у Франції. Технічна пам''ятка у Франції — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Katedrála Nanebevzetí Panny Marie v Rouenu', 'Katedrála ve Francii. Památka ve Francii — kus historie přímo u trasy.', 49.4402, 1.095, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Rouen.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Rouen.jpg"}'::text[], 1, '{"en": {"name": "Rouen Cathedral", "description": "Cathedral located in Seine-Maritime, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Kathedrale von Rouen", "description": "Kirchengebäude in Rouen, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Marii Panny w Rouen", "description": "Świątynia katolicka. Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Rouen", "description": "Kathedraal in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Ruán", "description": "Catedral situada en Sena Marítimo, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Rouen", "description": "Cathédrale située en Seine-Maritime, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Руанський собор", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika Notre-Dame de Bonsecours', 'Památka ve Francii — kus historie přímo u trasy.', 49.4216, 1.123, 'http://commons.wikimedia.org/wiki/Special:FilePath/NDdeBonsecours.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/NDdeBonsecours.JPG"}'::text[], 2, '{"en": {"name": "Basilique Notre-Dame de Bonsecours", "description": "Basilica located in Seine-Maritime, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Basilika Notre-Dame de Bonsecours", "description": "Kirchengebäude in Bonsecours, Département Seine-Maritime, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazilika Notre-Dame de Bonsecours", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika Notre-Dame de Bonsecours", "description": "Kerkgebouw in Bonsecours, Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Nuestra Señora de Bonsecours", "description": "Basílica situada en Sena Marítimo, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Notre-Dame de Bonsecours", "description": "Basilique située en Seine-Maritime, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika Notre-Dame de Bonsecours", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter Jumièges', 'Památka ve Francii — kus historie přímo u trasy.', 49.43194, 0.81917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Jumi%C3%A8ges.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Jumi%C3%A8ges.jpg"}'::text[], 3, '{"en": {"name": "Royal Saint-Peter''s abbey of Jumièges", "description": "Abbey located in Seine-Maritime, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Abtei Jumièges", "description": "Kloster in Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Jumièges", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Koninklijke Sint-Pietersabdij van Jumièges", "description": "Abdij in Jumièges, Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abadía Real de San Piedro de Jumièges", "description": "Abadía situada en Sena Marítimo, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Royale Saint-Pierre de Jumièges", "description": "Abbaye située en Seine-Maritime, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Jumièges", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'opatství Saint Wandrille', 'Klášter ve Francii. Památka ve Francii — kus historie přímo u trasy.', 49.52956, 0.76655, 'http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Saint-Wandrille%20de%20Fontenelle%202008%20PD%2002.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Saint-Wandrille%20de%20Fontenelle%202008%20PD%2002.JPG"}'::text[], 4, '{"en": {"name": "Royal Abbey of Saint Wandrille", "description": "Abbey located in Seine-Maritime, Normandy, France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Abtei Saint-Wandrille", "description": "Kloster in Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Saint-Wandrille", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Koninklijke abdij van Saint-Wandrille", "description": "Abdij in Saint-Wandrille-Rançon, Normandië, Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Saint-Wandrille", "description": "Abadía situada en Sena Marítimo, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye royale de Saint-Wandrille de Fontenelle", "description": "Abbaye située en Seine-Maritime, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "opatství Saint Wandrille", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Opatství Notre Dame du Bec', 'Památka ve Francii — kus historie přímo u trasy.', 49.22869, 0.72149, 'http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20du%20Bec%20-%20Fa%C3%A7ade%20sud%20vue%20du%20Bec.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20du%20Bec%20-%20Fa%C3%A7ade%20sud%20vue%20du%20Bec.jpg"}'::text[], 5, '{"en": {"name": "Bec Abbey", "description": "Benedictine monastic foundation in Normandy, France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Abtei Le Bec", "description": "Benediktinerabtei in der Normandie. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Notre Dame w Bec", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Bec", "description": "Klooster in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Bec", "description": "Abadía situada en Eure, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Notre-Dame du Bec", "description": "Abbaye située dans l''Eure, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Opatství Notre Dame du Bec", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Gaillard', 'Hrad ve Francii. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 49.23813, 1.40275, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20Gaillard%20%28Les%20Andelys%29%2C%20vu%20du%20ciel.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20Gaillard%20%28Les%20Andelys%29%2C%20vu%20du%20ciel.JPG"}'::text[], 6, '{"en": {"name": "Château Gaillard", "description": "French medieval castle in Les Andelys, Normandy. A castle in France — a historic stop worth the detour."}, "de": {"name": "Château Gaillard", "description": "Burgruine an der Seine bei Les Andelys in Frankreich. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Château Gaillard", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Gaillard", "description": "Kasteel in de Franse gemeente Les Andelys. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Gaillard", "description": "Castillo normando construido por Ricardo Corazón de León. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "Château-Gaillard", "description": "Château fort en Normandie. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Шато-Гайар", "description": "Замок у Франції. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb);
