    (v_route, 'Solný důl Wieliczka', 'Solný důl na jihu Polska. Technická památka v Polsku — doly, železnice a stroje, na kterých stojí historie kraje.', 49.98305, 20.05566, 'http://commons.wikimedia.org/wiki/Special:FilePath/%CE%91%CE%BB%CE%B1%CF%84%CF%89%CF%81%CF%85%CF%87%CE%B5%CE%AF%CE%B1%20%CE%92%CE%B9%CE%B5%CE%BB%CE%AF%CF%84%CF%83%CE%BA%CE%B1%205021.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%CE%91%CE%BB%CE%B1%CF%84%CF%89%CF%81%CF%85%CF%87%CE%B5%CE%AF%CE%B1%20%CE%92%CE%B9%CE%B5%CE%BB%CE%AF%CF%84%CF%83%CE%BA%CE%B1%205021.jpg"}'::text[], 0, '{"en": {"name": "Wieliczka Salt Mine", "description": "Salt mine (Wieliczka, Poland). A technical monument in Poland — mines, railways and machines behind the region''s history."}, "de": {"name": "Salzbergwerk Wieliczka", "description": "Salzbergwerk und Museum in Wieliczka bei Krakau, Polen. Ein technisches Denkmal in Polen — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Kopalnia soli Wieliczka", "description": "Polska kopalnia soli w Wieliczce koło Krakowa. Zabytek techniki w Polsce — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Wieliczka-zoutmijn", "description": "Zoutmijn in Polen. Een technisch monument in Polen — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Minas de sal de Wieliczka", "description": "Mina de sal y museo de minería en Wieliczka cerca de Cracovia, Polonia. Un monumento técnico en Polonia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "mines de sel de Wieliczka", "description": "Mines de sel en Pologne. Un monument technique en Pologne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Величка", "description": "Технічна пам''ятка у Польщі — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Corpus Christi Basilica', 'Památka v Polsku — kus historie přímo u trasy.', 50.04979, 19.94494, 'http://commons.wikimedia.org/wiki/Special:FilePath/Corpus%20Christi%20Basilica%2C%20Krak%C3%B3w.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Corpus%20Christi%20Basilica%2C%20Krak%C3%B3w.jpg"}'::text[], 1, '{"en": {"name": "Corpus Christi Basilica", "description": "Church building in Kraków, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Fronleichnamsbasilika", "description": "Kirche in Krakau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Bożego Ciała w Krakowie", "description": "Zabytkowa świątynia rzymskokatolicka w Polsce. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Corpus Christibasiliek", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica del Corpus Christi", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Corpus Christi Basilica", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Божого Тіла (Краків)", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála na Wawelu', 'Katedrála v Krakově. Památka v Polsku — kus historie přímo u trasy.', 50.05464, 19.93542, 'http://commons.wikimedia.org/wiki/Special:FilePath/292%20Krakow%20Katedra%20na%20Wawelu%2020070805.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/292%20Krakow%20Katedra%20na%20Wawelu%2020070805.jpg"}'::text[], 2, '{"en": {"name": "Wawel Cathedral", "description": "Cathedral in Kraków, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Wawel-Kathedrale", "description": "Kirchengebäude im Wawel-Schloss in Krakau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna św. Stanisława i św. Wacława w Krakowie", "description": "Świątynia katolicka w Polsce. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Wawelkathedraal", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Wawel", "description": "Templo católico de Cracovia (Polonia). Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale du Wawel", "description": "Édifice religieux situé en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святих Станіслава і Вацлава", "description": "Кафедральний собор у Кракові, Польща. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kostel Nanebevzetí Panny Marie v Krakově', 'Kostel v Krakově v Polsku. Památka v Polsku — kus historie přímo u trasy.', 50.06167, 19.93917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kosciol%20mariacki%20krakow.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kosciol%20mariacki%20krakow.jpg"}'::text[], 3, '{"en": {"name": "St. Mary''s Basilica in Kraków", "description": "Church (Kraków, Poland). A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Marienkirche", "description": "Kirchengebäude in Krakau, Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "kościół archiprezbiterialny pw. Wniebowzięcia Najświętszej Marii Panny w Krakowie", "description": "Zabytkowy kościół w Krakowie. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Mariakerk", "description": "Krakau. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa María", "description": "Iglesia de Santa María en Cracovia, Polonia. Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Sainte-Marie de Cracovie", "description": "Édifice religieux situé à Cracovie en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Архипресвітеріальний костел Внебовзяття Пресвятої Діви Марії", "description": "Костел у Кракові. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Floriánská brána', 'Brána v Krakově. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.06472, 19.94139, 'http://commons.wikimedia.org/wiki/Special:FilePath/20200516%20Brama%20Floria%C5%84ska%20w%20Krakowie%200911%209966.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20200516%20Brama%20Floria%C5%84ska%20w%20Krakowie%200911%209966.jpg"}'::text[], 4, '{"en": {"name": "St. Florian''s Gate", "description": "Gothic tower in Kraków, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Florianstor", "description": "Das letzte erhaltene Stadttor von Krakau im Zug der Floriansgasse. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Brama Floriańska w Krakowie", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Florianuspoort", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Puerta de San Florián", "description": "Puerta de la ciudad Cracovia unica preservada. Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "porte Florian", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Брама Флоріанська (Краків)", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Ojcowský národní park', 'Národní park, okres Kraków, Malopolské vojvodství, Polsko. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 50.20667, 19.82917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dolina%20Pr%C4%85dnika%2C%20widok%20z%20okolic%20%C5%BAr.%20Mi%C5%82o%C5%9Bci.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dolina%20Pr%C4%85dnika%2C%20widok%20z%20okolic%20%C5%BAr.%20Mi%C5%82o%C5%9Bci.jpg"}'::text[], 5, '{"en": {"name": "Ojców National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Ojców-Nationalpark", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Ojcowski Park Narodowy", "description": "Park narodowy w województwie małopolskim. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Ojców National Park", "description": "Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Ojców", "description": "Reserva en Cracovia, Polonia. Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national d''Ojców", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Ойцовський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Pieskowa Skała', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.24406, 19.78164, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pieskowa%20Skala%2023.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pieskowa%20Skala%2023.jpg"}'::text[], 6, '{"en": {"name": "Pieskowa Skała", "description": "Castle in Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Peskenstein", "description": "Schloss in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pieskowa Skała", "description": "Zamek we wsi Sołuszowa, Polska. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Pieskowa Skała", "description": "Bouwwerk in Sułoszowa, Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Pieskowa Skała", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Pieskowa Skała", "description": "Château en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Пєскова Скала", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb);
