    (v_route, 'Vědecké muzeum', 'Britské muzeum. Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 51.4975, -0.17472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Science%20Museum%2C%20Exhibition%20Road%20%28cropped%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Science%20Museum%2C%20Exhibition%20Road%20%28cropped%29.jpg"}'::text[], 0, '{"en": {"name": "Science Museum", "description": "Science museum in London, United Kingdom. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Science Museum", "description": "Wissenschaftsmuseum in London. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Muzeum Nauki w Londynie", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Science Museum", "description": "Museum in Londen. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo de Ciencias de Londres", "description": "Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Science Museum de Londres", "description": "Musée scientifique gratuit à Londres qui expose une collection de plus de 300 000 objets, instruments ou machines. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Музей науки (Лондон)", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Westminsterská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.49583, -0.13947, 'http://commons.wikimedia.org/wiki/Special:FilePath/Westminster%20Cathedral%20London%2C%204th%20May%202024%20-%2053708806889.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Westminster%20Cathedral%20London%2C%204th%20May%202024%20-%2053708806889.jpg"}'::text[], 1, '{"en": {"name": "Westminster Cathedral", "description": "Catholic cathedral in London, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Westminster Cathedral", "description": "Kirchengebäude in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Westminsterska", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Westminster", "description": "Bouwwerk in Londen. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Preciosísima Sangre de Cristo de Westminster", "description": "Iglesia en Londres. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Westminster", "description": "Cathédrale à Londres. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вестмінстерський собор", "description": "Церква в Лондоні (Англія). Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Westminsterské opatství', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.4994, -0.12737, 'http://commons.wikimedia.org/wiki/Special:FilePath/Westminster-Abbey.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Westminster-Abbey.JPG"}'::text[], 2, '{"en": {"name": "Westminster Abbey", "description": "Gothic abbey church in London, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Westminsterabtei", "description": "Krönungskirche der britischen Monarchie in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Westminsterskie", "description": "Świątynia anglikańska w Londynie. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Westminster Abbey", "description": "Kerkgebouw in Londen. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abadía de Westminster", "description": "Iglesia de la abadía en la ciudad de Westminster, Londres, Inglaterra. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Westminster", "description": "Abbaye à Londres. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вестмінстерське абатство", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Big Ben', 'Zvon v hodinové věži na severním konci Westminsterského paláce. Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.50067, -0.12449, 'http://commons.wikimedia.org/wiki/Special:FilePath/Big%20Ben%202001-06-27.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Big%20Ben%202001-06-27.jpg"}'::text[], 3, '{"en": {"name": "Big Ben", "description": "Tower of the Palace of Westminster, London containing the bell Big Ben. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Big Ben", "description": "Uhrturm am Palace of Westminster in London mit der Glocke Big Ben. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Big Ben", "description": "Wieża zegarowa w Londynie. Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Big Ben", "description": "Klok in City of Westminster, Verenigd Koninkrijk/Engeland. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Big Ben", "description": "Torre del Palacio de Westminster en Londres, Inglaterra. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "Big Ben", "description": "Tour horloge du Palais de Westminster à Londres. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Біг-Бен", "description": "Популярна туристична назва годинникової вежі Вестмінстерського палацу. Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Katedrála svatého Pavla', 'Katedrála v Londýně. Památka ve Velké Británii — kus historie přímo u trasy.', 51.51378, -0.09831, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20Pauls%20aerial%20%28cropped%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20Pauls%20aerial%20%28cropped%29.jpg"}'::text[], 4, '{"en": {"name": "St Paul''s Cathedral", "description": "Cathedral in the City of London, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St Paul’s Cathedral", "description": "Kathedrale in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Pawła w Londynie", "description": "Katedra w Londynie. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St Paul''s Cathedral", "description": "Kathedraal in Londen. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Pablo de Londres", "description": "Catedral en Londres, Inglaterra, Reino Unido. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Paul de Londres", "description": "Cathédrale à Londres. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "собор Святого Павла", "description": "Собор у Лондоні (Велика Британія). Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Tower', 'Londýnský Tower, palác a pevnost v Londýně. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.5082, -0.0762, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tower%20of%20London%20viewed%20from%20the%20River%20Thames.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tower%20of%20London%20viewed%20from%20the%20River%20Thames.jpg"}'::text[], 5, '{"en": {"name": "Tower of London", "description": "Castle in central London, United Kingdom. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Tower of London", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Tower of London", "description": "Zamek monarchów Anglii (Londyn, Wielka Brytania). Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Tower of London", "description": "Gebouw. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Torre de Londres", "description": "Castillo histórico situado en la ribera norte del río Támesis en el centro de Londres, Inglaterra. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "tour de Londres", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Тауер", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
