    (v_route, 'Cutty Sark', 'Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 51.48278, -0.00972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cutty%20Sark%20%2816719233476%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cutty%20Sark%20%2816719233476%29.jpg"}'::text[], 0, '{"en": {"name": "Cutty Sark", "description": "British clipper ship. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Cutty Sark", "description": "Segelschiff, heute Museumsschiff in London. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Cutty Sark", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Cutty Sark", "description": "Schip uit 1869. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Cutty Sark", "description": "Barco inglés. Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Cutty Sark", "description": "Clipper britannique. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Катті Сарк", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
