    (v_route, 'New Forest', 'Přírodní zajímavost ve Velké Británii — místo na protažení nohou uprostřed přírody.', 50.86306, -1.61806, 'http://commons.wikimedia.org/wiki/Special:FilePath/New%20Forest%20heath%20and%20horses.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/New%20Forest%20heath%20and%20horses.JPG"}'::text[], 2, '{"en": {"name": "New Forest", "description": "National park in southern England. A natural sight in the United Kingdom — a spot to stretch your legs amid nature."}, "de": {"name": "New Forest", "description": "Landschaft im Süden Englands. Eine Natursehenswürdigkeit in Großbritannien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy New Forest", "description": "Atrakcja przyrodnicza w Wielkiej Brytanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "New Forest", "description": "Bos in Hampshire, Verenigd Koninkrijk. Een natuurbezienswaardigheid in het Verenigd Koninkrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "New Forest", "description": "Un paraje natural en el Reino Unido: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "New Forest", "description": "Forêt d''Angleterre (Royaume-Uni). Un site naturel au Royaume-Uni — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Нью-Форест", "description": "Природна пам''ятка у Великій Британії — місце розім''яти ноги серед природи."}}'::jsonb),
