    (v_route, 'Winchesterská katedrála', 'Katedrála ve Velké Británii. Památka ve Velké Británii — kus historie přímo u trasy.', 51.06072, -1.31333, 'http://commons.wikimedia.org/wiki/Special:FilePath/WinCath30Je6-4836wiki.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/WinCath30Je6-4836wiki.jpg"}'::text[], 4, '{"en": {"name": "Winchester Cathedral", "description": "Cathedral in Winchester, Hampshire, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Winchester", "description": "Kathedrale in Großbritannien. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Winchester", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Winchester", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Winchester", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Winchester", "description": "Cathédrale anglaise dans le Hampshire. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вінчестерський собор", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
