    (v_route, 'Basílica de la Virgen de la Encina de Ponferrada', 'Památka ve Španělsku — kus historie přímo u trasy.', 42.54425, -6.59175, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ponferrada%20-%20Basilica%20de%20Nuestra%20Se%C3%B1ora%20de%20la%20Encina%2004.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ponferrada%20-%20Basilica%20de%20Nuestra%20Se%C3%B1ora%20de%20la%20Encina%2004.jpg"}'::text[], 3, '{"en": {"name": "Basílica de la Virgen de la Encina de Ponferrada", "description": "Church building in Ponferrada, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Basílica de la Encina", "description": "Kirchengebäude in Kastilien und León, Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Basílica de la Virgen de la Encina de Ponferrada", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Basílica de la Virgen de la Encina de Ponferrada", "description": "Kerkgebouw in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Basílica de La Encina", "description": "Iglesia en Ponferrada, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "Basílica de la Virgen de la Encina de Ponferrada", "description": "Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Basílica de la Virgen de la Encina de Ponferrada", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Castle of Carbedo', 'Vojenská historie ve Španělsku — opevnění, technika a příběhy, které stojí za zastávku.', 42.63529, -7.12707, 'http://commons.wikimedia.org/wiki/Special:FilePath/Carbedo.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Carbedo.jpg"}'::text[], 4, '{"en": {"name": "Castle of Carbedo", "description": "Cultural property in Folgoso de Caurel, Spain. Military history in Spain — fortifications, hardware and stories worth the stop."}, "de": {"name": "Castle of Carbedo", "description": "Denkmal in Spanien. Militärgeschichte in Spanien — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Castle of Carbedo", "description": "Historia wojskowa w Hiszpanii — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Castle of Carbedo", "description": "Militaire geschiedenis in Spanje — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Castillo de O Carbedo", "description": "Bien de interés cultural. Historia militar en España: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "Castle of Carbedo", "description": "Histoire militaire en Espagne — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Castle of Carbedo", "description": "Пам''ятка культурної спадщини в Іспанії. Військова історія в Іспанії — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
