    (v_route, 'Sanabria Lake', 'Vodní plocha ve Španělsku — příjemný cíl vyjížďky s výhledy na hladinu.', 42.1225, -6.71917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sanabria%20lake%20%28Zamora%2CSpain%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sanabria%20lake%20%28Zamora%2CSpain%29.jpg"}'::text[], 6, '{"en": {"name": "Sanabria Lake", "description": "Lake in Zamora Province, Castile and León, Spain. A body of water in Spain — a pleasant ride destination with waterside views."}, "de": {"name": "Lago de Sanabria", "description": "Ein Gewässer in Spanien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Sanabria", "description": "Jezioro w Hiszpanii (Kastylia i León). Akwen w Hiszpanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Sanabria Lake", "description": "Meer in Spanje. Een waterpartij in Spanje — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Sanabria", "description": "Cuerpo de agua en la provincia de Zamora, Castilla y León, España. Una masa de agua en España: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Sanabria", "description": "Lac espagnol. Un plan d''eau en Espagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Санабрія (озеро)", "description": "Водойма в Іспанії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
