    (v_route, 'Muzeum Vasa', 'Muzeum ve Stockholmu, ve Švédsku. Technická památka ve Švédsku — doly, železnice a stroje, na kterých stojí historie kraje.', 59.32807, 18.09139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vasa%20Museum%20building%20view%20from%20the%20sea%20%283%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vasa%20Museum%20building%20view%20from%20the%20sea%20%283%29.jpg"}'::text[], 0, '{"en": {"name": "Vasa Museum", "description": "Museum in Stockholm, Sweden. A technical monument in Sweden — mines, railways and machines behind the region''s history."}, "de": {"name": "Vasa-Museum", "description": "Museum in Djurgården, Stockholm, Schweden. Ein technisches Denkmal in Schweden — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Muzeum Vasa", "description": "Muzeum w Sztokholmie. Zabytek techniki w Szwecji — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Vasamuseum", "description": "Museum in Stockholm. Een technisch monument in Zweden — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo Vasa", "description": "Museo en Djurgården, Estocolmo, Suecia. Un monumento técnico en Suecia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "musée Vasa", "description": "Musée à Stockholm, Suède. Un monument technique en Suède — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Музей Ваза", "description": "Технічна пам''ятка у Швеції — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Velká synagoga', 'Památka ve Švédsku — kus historie přímo u trasy.', 59.33189, 18.07421, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stora%20Synagogan%2C%202012%20a%2008.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stora%20Synagogan%2C%202012%20a%2008.JPG"}'::text[], 1, '{"en": {"name": "Stockholm Synagogue", "description": "Synagogue in Stockholm, Sweden. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Große Synagoge Stockholm", "description": "Synagogenbau in Stockholm, Schweden. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Wielka Synagoga w Sztokholmie", "description": "Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Stockholm Synagogue", "description": "Synagoge in Stockholm, Zweden. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga de Estocolmo", "description": "Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Stockholm", "description": "Bâtiment de la commune de Stockholm, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Velká synagoga", "description": "Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Tre Kronor Castle', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.32583, 18.07139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slottet%20Tre%20Kronor%201661.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slottet%20Tre%20Kronor%201661.jpg"}'::text[], 2, '{"en": {"name": "Tre Kronor Castle", "description": "Stronghold in Stockholm, later rebuilt into a castle and royal residence. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Burg Tre Kronor", "description": "Burganlage, die Birger Jarl errichtete und später zu Schloss und Residenz umgebaut wurde. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Tre Kronor Castle", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Tre Kronor", "description": "Was de burcht die Birger Jarl bouwde en later herbouwde tot het kasteel en de koninklijke residentie. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Tre Kronor", "description": "Fue la fortaleza que construyó Birger Jarl y luego fue reconstruida en el castillo y la residencia real. Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "Tre Kronor", "description": "Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Три корони (палац)", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatého Mikuláše', 'Kostel ve Stockholmu. Památka ve Švédsku — kus historie přímo u trasy.', 59.32583, 18.07056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Storkyrkan%202025%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Storkyrkan%202025%2001.jpg"}'::text[], 3, '{"en": {"name": "Storkyrkan", "description": "Lutheran cathedral in Stockholm. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Sankt Nikolai kyrka", "description": "Kirchengebäude in Stockholm. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Mikołaja w Sztokholmie", "description": "Luterańska katedra w Sztokholmie. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Storkyrkan", "description": "Bouwwerk in Stockholm. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Nicolás de Estocolmo", "description": "Catedral de Estocolmo, Suecia. Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Storkyrkan", "description": "Cathédrale située à Stockholm, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Церква Святого Миколая", "description": "Кафедральний собор Стокгольма. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'German Church', 'Památka ve Švédsku — kus historie přímo u trasy.', 59.32417, 18.07167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tyska%20kyrkan%20stadsbild%202012.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tyska%20kyrkan%20stadsbild%202012.jpg"}'::text[], 4, '{"en": {"name": "German Church", "description": "Church building in Stockholm, Sweden. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Tyska kyrkan", "description": "Kirchengebäude in Stockholm. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół niemiecki w Sztokholmie", "description": "Kościół w Sztokholmie. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Tyska kyrkan", "description": "Bouwwerk in Stockholm. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia Alemana", "description": "Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église allemande", "description": "Bâtiment de la commune de Stockholm, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Німецька церква", "description": "Євангелічно-лютеранська церква у центрі Стокгольма. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Erika', 'Římskokatolická katedrála v Stockholmu. Památka ve Švédsku — kus historie přímo u trasy.', 59.31381, 18.0725, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stockholms%20katolska%20domkyrka%2003.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stockholms%20katolska%20domkyrka%2003.jpg"}'::text[], 5, '{"en": {"name": "St. Eric''s Cathedral, Stockholm", "description": "Roman Catholic cathedral in Stockholm, Sweden. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Domkirche St. Erich", "description": "Kathedrale in Schweden. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Eryka w Sztokholmie", "description": "Rzymskokatolicka katedra w Sztokholmie. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Domkerk Sint-Erik", "description": "Kathedraal in Zweden. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Erik", "description": "Catedral de la diócesis católica de Estocolmo. Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Éric de Stockholm", "description": "Édifice religieux située en Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Еріка (Стокгольм)", "description": "Католицька церква у Стокгольмі. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Tyresta National Park', 'Přírodní zajímavost ve Švédsku — místo na protažení nohou uprostřed přírody.', 59.18423, 18.2812, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sweden.%20Stockholm%20County.%20Tyresta%20National%20Park%20023.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sweden.%20Stockholm%20County.%20Tyresta%20National%20Park%20023.JPG"}'::text[], 6, '{"en": {"name": "Tyresta National Park", "description": "National park of Sweden. A natural sight in Sweden — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Tyresta", "description": "Nationalpark in Schweden. Eine Natursehenswürdigkeit in Schweden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Tyresta", "description": "Park narodowy w Szwecji. Atrakcja przyrodnicza w Szwecji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Tyresta", "description": "Natuurgebied in Zweden. Een natuurbezienswaardigheid in Zweden — een plek om de benen te strekken in de natuur."}, "es": {"name": "Tyresta", "description": "Parque nacional en Suecia. Un paraje natural en Suecia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Tyresta", "description": "Parc national de Suède. Un site naturel en Suède — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Tyresta National Park", "description": "Природна пам''ятка у Швеції — місце розім''яти ноги серед природи."}}'::jsonb);
