  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Rammelsberg', 'Technická památka v Německu — doly, železnice a stroje, na kterých stojí historie kraje.', 51.8875, 10.43167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rammelsberg.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rammelsberg.jpg"}'::text[], 0, '{"en": {"name": "Rammelsberg", "description": "Mine and mining museum in the Harz. A technical monument in Germany — mines, railways and machines behind the region''s history."}, "de": {"name": "Rammelsberg", "description": "Bergwerk und Bergbaumuseum im Harz. Ein technisches Denkmal in Deutschland — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Kopalnia Rammelsberg", "description": "Zabytek techniki w Niemczech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Rammelsbergmijnen", "description": "Berg in Duitsland. Een technisch monument in Duitsland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Minas de Rammelsberg", "description": "Un monumento técnico en Alemania: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "mines de Rammelsberg", "description": "Anciennes mines. Un monument technique en Allemagne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Раммельсберг", "description": "Технічна пам''ятка в Німеччині — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Císařská falc v Goslaru', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 51.9028, 10.4258, 'http://commons.wikimedia.org/wiki/Special:FilePath/Goslar%20Kaiserpfalz.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Goslar%20Kaiserpfalz.jpg"}'::text[], 1, '{"en": {"name": "Imperial Palace of Goslar", "description": "Palace of the Holy Roman Empire. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Kaiserpfalz Goslar", "description": "Historisches Bauwerk und UNESCO-Welterbe in Niedersachsen. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Palatium w Goslarze", "description": "Pałac Świętego Cesarstwa Rzymskiego. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Keizerpalts Goslar", "description": "Bouwwerk in Nedersaksen. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Imperial de Goslar", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "palais impérial de Goslar", "description": "Ensemble historique de bâtiments résidentiels, politiques et religieux. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Císařská falc v Goslaru", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Vodohospodářský systém Horního Harze', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 51.82, 10.34, 'http://commons.wikimedia.org/wiki/Special:FilePath/Teiche%20Buntenbock.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Teiche%20Buntenbock.jpg"}'::text[], 2, '{"en": {"name": "Upper Harz Water Regale", "description": "Part of a World Heritage site in Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Oberharzer Wasserregal", "description": "System zur Umleitung und Speicherung von Wasser für Wasserräder des Oberharzer Bergbaus. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vodohospodářský systém Horního Harze", "description": "Zbiornik retencyjny (Harz, Niemcy). Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Oberharz watermanagementsysteem", "description": "Stuwmeer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodohospodářský systém Horního Harze", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Vodohospodářský systém Horního Harze", "description": "Partie d''un site du patrimoine mondial en Allemagne. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vodohospodářský systém Horního Harze", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Národní park Harz', 'Přírodní zajímavost v Německu — místo na protažení nohou uprostřed přírody.', 51.7833, 10.5667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ilsenburg%2C%20Ilsetal%2C%20Ilsef%C3%A4lle%20--%202017%20--%200143.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ilsenburg%2C%20Ilsetal%2C%20Ilsef%C3%A4lle%20--%202017%20--%200143.jpg"}'::text[], 3, '{"en": {"name": "Harz National Park", "description": "National park of Germany. A natural sight in Germany — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Harz", "description": "Waldnationalpark in Deutschland. Eine Natursehenswürdigkeit in Deutschland — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Harzu", "description": "Atrakcja przyrodnicza w Niemczech — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Harz", "description": "Natuurgebied in Duitsland. Een natuurbezienswaardigheid in Duitsland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Harz", "description": "Área protegida de Alemania. Un paraje natural en Alemania: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national du Harz", "description": "Parc national d''Allemagne. Un site naturel en Allemagne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Гарц (національний парк)", "description": "Природна пам''ятка в Німеччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Wernigerode Castle', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 51.8303, 10.795, 'http://commons.wikimedia.org/wiki/Special:FilePath/00%203286%20Schloss%20Wernigerode%20%28Harz%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/00%203286%20Schloss%20Wernigerode%20%28Harz%29.jpg"}'::text[], 4, '{"en": {"name": "Wernigerode Castle", "description": "Castle in Saxony-Anhalt, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Wernigerode", "description": "Schloss in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Wernigerode Castle", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Wernigerode", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Wernigerode", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Wernigerode", "description": "Château situé au pied nord du massif de Harz, Saxe-Anhalt, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Вернігеродський замок", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter Walkenried', 'Památka v Německu — kus historie přímo u trasy.', 51.58306, 10.61917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Walkenried-Zisterzienserkloster%202011%20b%C3%B6rste.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Walkenried-Zisterzienserkloster%202011%20b%C3%B6rste.jpg"}'::text[], 5, '{"en": {"name": "Walkenried Abbey", "description": "Monastery. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Kloster Walkenried", "description": "Ehemalige Zisterzienserabtei in Deutschland, heute Museum und UNESCO-Welterbe. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Walkenried", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij Walkenried", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Klášter Walkenried", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Walkenried", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Walkenried", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'klášter Gandersheim', 'Německý klášter. Památka v Německu — kus historie přímo u trasy.', 51.8704, 10.0261, 'http://commons.wikimedia.org/wiki/Special:FilePath/00%207482%20Bad%20Gandersheim%20-%20Stift%20Gandersheim.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/00%207482%20Bad%20Gandersheim%20-%20Stift%20Gandersheim.jpg"}'::text[], 6, '{"en": {"name": "Gandersheim Abbey", "description": "Monastery. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Stift Gandersheim", "description": "Kloster in Bad Gandersheim. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Gandersheim", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Gandersheim", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abadía de Gandersheim", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Gandersheim", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "klášter Gandersheim", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb);
