    (v_route, 'Ytterby mine', 'Technická památka ve Švédsku — doly, železnice a stroje, na kterých stojí historie kraje.', 59.4265, 18.35353, 'http://commons.wikimedia.org/wiki/Special:FilePath/2019-03%20Ytterby%20Mine%20on%20Resar%C3%B6%20in%20Vaxholm%20Municipality%20Stockholm%20archipelago%2006.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2019-03%20Ytterby%20Mine%20on%20Resar%C3%B6%20in%20Vaxholm%20Municipality%20Stockholm%20archipelago%2006.jpg"}'::text[], 0, '{"en": {"name": "Ytterby mine", "description": "Mine on Resarö, Vaxholm municipality, Stockholm archipelago, Sweden. A technical monument in Sweden — mines, railways and machines behind the region''s history."}, "de": {"name": "Grube Ytterby", "description": "Bergwerk in der schwedischen Gemeinde Vaxholm. Ein technisches Denkmal in Schweden — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Ytterby", "description": "Zabytek techniki w Szwecji — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Ytterby", "description": "Mijn in Vaxholm, Zweden. Een technisch monument in Zweden — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Ytterby", "description": "Localidad de Suecia. Un monumento técnico en Suecia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Ytterby", "description": "Village en Suède. Un monument technique en Suède — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Іттербю", "description": "Технічна пам''ятка у Швеції — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Vaxholm Fortress', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.40306, 18.35972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms%20f%C3%A4stning%2C%20Vaxholms%20kastell%2C%20Vaxholm%2C%20Sverige%202009%206293.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vaxholms%20f%C3%A4stning%2C%20Vaxholms%20kastell%2C%20Vaxholm%2C%20Sverige%202009%206293.jpg"}'::text[], 1, '{"en": {"name": "Vaxholm Fortress", "description": "Swedish fortress. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Festung Vaxholm", "description": "Befestigungsanlage. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Vaxholm Fortress", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Vesting Vaxholm", "description": "Werd oorspronkelijk gebouwd door Gustaaf I van Zweden in 1544 om Stockholm te verdedigen tegen aanvallen vanaf zee. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Vaxholm Fortress", "description": "Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Vaxholm", "description": "Bâtiment de la commune de Vaxholm, en Suède. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Vaxholm Fortress", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Rydboholm Castle', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.44028, 18.18556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rydboholm%20maj%202010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rydboholm%20maj%202010.jpg"}'::text[], 2, '{"en": {"name": "Rydboholm Castle", "description": "Building in Österåker Municipality, Stockholm County, Sweden. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Schloss Rydboholm", "description": "Schloss in Schweden. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Rydboholm Castle", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Rydboholm Castle", "description": "Kasteel in Zweden. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Rydboholm", "description": "Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Rydboholm", "description": "Bâtiment de la commune de Österåker, en Suède. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Рюдбогольм (Швеція)", "description": "Будівля у Швеції. Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Royal National City Park', 'Přírodní zajímavost ve Švédsku — místo na protažení nohou uprostřed přírody.', 59.36167, 18.07361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Djurg%C3%A5rdsbrunnskanalen%20October%202013.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Djurg%C3%A5rdsbrunnskanalen%20October%202013.jpg"}'::text[], 3, '{"en": {"name": "Royal National City Park", "description": "Park in Stockholm, Sweden. A natural sight in Sweden — a spot to stretch your legs amid nature."}, "de": {"name": "Königlicher Nationalstadtpark", "description": "Nationalstadtpark in Schweden. Eine Natursehenswürdigkeit in Schweden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Ekoparken", "description": "Atrakcja przyrodnicza w Szwecji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Royal National City Park", "description": "Een natuurbezienswaardigheid in Zweden — een plek om de benen te strekken in de natuur."}, "es": {"name": "Royal National City Park", "description": "Un paraje natural en Suecia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national urbain royal", "description": "Aire protégée située à Stockholm, en Suède. Un site naturel en Suède — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Royal National City Park", "description": "Природна пам''ятка у Швеції — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Kaknästornet', 'Rozhledna ve Švédsku — výhled do kraje jako odměna za zastávku.', 59.335, 18.12639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kaknastower%20Stockholm%20view%20from%20Djurgarden.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kaknastower%20Stockholm%20view%20from%20Djurgarden.jpg"}'::text[], 4, '{"en": {"name": "Kaknästornet", "description": "TV- and radio-tower in Stockholm, Sweden. A lookout tower in Sweden — sweeping views as a reward for stopping."}, "de": {"name": "Kaknästurm", "description": "Aussichts- und Richtfunkturm in Stockholm. Ein Aussichtsturm in Schweden — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża Kaknäs", "description": "Wieża widokowa w Szwecji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Kaknästornet", "description": "Bouwwerk in Stockholm. Een uitkijktoren in Zweden — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre Kaknäs", "description": "Torre de comunicaciones en Estocolmo. Un mirador en Suecia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Kaknästornet", "description": "Une tour panoramique en Suède — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Kaknästornet", "description": "Оглядова вежа у Швеції — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Drevviken', 'Vodní plocha ve Švédsku — příjemný cíl vyjížďky s výhledy na hladinu.', 59.23333, 18.175, 'http://commons.wikimedia.org/wiki/Special:FilePath/Drevviken%202007.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Drevviken%202007.jpg"}'::text[], 5, '{"en": {"name": "Drevviken", "description": "Lake in southern Stockholm, Sweden. A body of water in Sweden — a pleasant ride destination with waterside views."}, "de": {"name": "Drevviken", "description": "See in Schweden. Ein Gewässer in Schweden — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Drevviken", "description": "Akwen w Szwecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Drevviken", "description": "Meer in Zweden. Een waterpartij in Zweden — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Drevviken", "description": "Una masa de agua en Suecia: un destino agradable con vistas al agua."}, "fr": {"name": "Drevviken", "description": "Lac suédois. Un plan d''eau en Suède — une belle destination avec vue sur l''eau."}, "uk": {"name": "Древвікен", "description": "Озеро у Швеції. Водойма у Швеції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Ängsö National Park', 'Přírodní zajímavost ve Švédsku — místo na protažení nohou uprostřed přírody.', 59.62361, 18.76389, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C3%84ngs%C3%B6%20brygga.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C3%84ngs%C3%B6%20brygga.jpg"}'::text[], 6, '{"en": {"name": "Ängsö National Park", "description": "National park in Sweden. A natural sight in Sweden — a spot to stretch your legs amid nature."}, "de": {"name": "Ängsö-Nationalpark", "description": "Nationalpark auf einer Insel im Stockholmer Schärengarten in Schweden. Eine Natursehenswürdigkeit in Schweden — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Ängsö", "description": "Park narodowy w Szwecji. Atrakcja przyrodnicza w Szwecji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal park Ängsö", "description": "Eiland van Zweden. Een natuurbezienswaardigheid in Zweden — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Ängsö", "description": "Parque nacional en Suecia. Un paraje natural en Suecia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national d''Ängsö", "description": "Parc national en Suède. Un site naturel en Suède — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Ängsö National Park", "description": "Природна пам''ятка у Швеції — місце розім''яти ноги серед природи."}}'::jsonb);
