  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Uhelný důl Zollverein', 'Technická památka v Německu — doly, železnice a stroje, na kterých stojí historie kraje.', 51.4865, 7.04408, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zeche%20Zollverein%20abends.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zeche%20Zollverein%20abends.jpg"}'::text[], 0, '{"en": {"name": "Zollverein Coal Mine Industrial Complex", "description": "Large former industrial site in the city of Essen, North Rhine-Westphalia, Germany. A technical monument in Germany — mines, railways and machines behind the region''s history."}, "de": {"name": "Zeche Zollverein", "description": "Von 1851 bis 1986 aktives Steinkohlebergwerk in Essen, heute Welterbe der UNESCO. Ein technisches Denkmal in Deutschland — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Kompleks przemysłowy kopalni i koksowni Zollverein", "description": "Zabytek techniki w Niemczech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Zeche Zollverein", "description": "Kolenmijn in Essen, Duitsland. Een technisch monument in Duitsland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Complejo industrial de la mina de carbón de Zollverein", "description": "Un monumento técnico en Alemania: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Complexe industriel de la mine de charbon de Zollverein", "description": "Opéré de 1847 à 1986 la mine de charbon à Essen. Un monument technique en Allemagne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Шахта «Цольферайн»", "description": "Недіюча кам''яновугільна шахта. Технічна пам''ятка в Німеччині — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Old Synagogue', 'Památka v Německu — kus historie přímo u trasy.', 51.4564, 7.01667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Alte%20Synagoge%20Essen%202014.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Alte%20Synagoge%20Essen%202014.jpg"}'::text[], 1, '{"en": {"name": "Old Synagogue", "description": "Former synagogue in Essen, Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Alte Synagoge", "description": "Ehemalige Synagoge und Ausstellungsgebäude in Essen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Stara Synagoga w Essen", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Oude Synagoge", "description": "Gebouw in Essen, Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Antigua Sinagoga (Essen)", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "ancienne synagogue d''Essen", "description": "Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Old Synagogue", "description": "Будівля в Німеччині. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Essenský chrám', 'Katedrála. Památka v Německu — kus historie přímo u trasy.', 51.456, 7.014, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dom-Essen-mit-Burgplatz-und-Rathaus-2016.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dom-Essen-mit-Burgplatz-und-Rathaus-2016.jpg"}'::text[], 2, '{"en": {"name": "Essen Minster", "description": "Cathedral. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Essener Münster", "description": "Bischofskirche des Bistums Essen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Essen", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Essen", "description": "Kerkgebouw in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Essen", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale d’Essen", "description": "Église allemande. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Essenský chrám", "description": "Церква в Німеччині. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'klášter Essen', 'Památka v Německu — kus historie přímo u trasy.', 51.45583, 7.01361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Essen%202011%2066-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Essen%202011%2066-2.jpg"}'::text[], 3, '{"en": {"name": "Essen Abbey", "description": "Monastery. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Kanonissenstift Essen", "description": "Frauenstift. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "klášter Essen", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sticht Essen", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Essen", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye d''Essen", "description": "Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "klášter Essen", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Werden Abbey', 'Památka v Německu — kus historie přímo u trasy.', 51.38806, 7.00472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Essen%20Kloster%20Werden%20Innenhof%202%202005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Essen%20Kloster%20Werden%20Innenhof%202%202005.jpg"}'::text[], 4, '{"en": {"name": "Werden Abbey", "description": "Former Benedictine abbey in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Reichsabtei Werden an der Ruhr", "description": "Ehemalige Reichsabtei der Benediktiner, heute im Stadtgebiet von Essen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo w Werden", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Werden", "description": "Abdij in Essen, Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Werden", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Werden", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Werden Abbey", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Benrath Palace', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 51.16103, 6.87057, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Benrath%20Jan2012.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Benrath%20Jan2012.jpg"}'::text[], 5, '{"en": {"name": "Benrath Palace", "description": "Baroque German Palace. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Benrath", "description": "Schloss in Düsseldorf, Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Benrath", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schloss Benrath", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Benrath", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Benrath", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Бенрат", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Burg Castle', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 51.13761, 7.15278, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss-burg-20040223-135s.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss-burg-20040223-135s.jpg"}'::text[], 6, '{"en": {"name": "Burg Castle", "description": "Castle in Solingen, NRW, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Burg", "description": "Schloss in Solingen, NRW, Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Burg Castle", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot Burg", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Burg Castle", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château des comtes de Berg", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Бург", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb);
