    (v_route, 'Mary Rose', 'Anglická karaka. Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 50.79972, -1.10667, 'http://commons.wikimedia.org/wiki/Special:FilePath/MaryRose-conservation1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/MaryRose-conservation1.jpg"}'::text[], 0, '{"en": {"name": "Mary Rose", "description": "1511 carrack warship. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Mary Rose", "description": "Englisches Kriegsschiff. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Mary Rose", "description": "Angielski okręt wojenny typu karaka z XVI wieku. Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Mary Rose", "description": "Museum in het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Mary Rose", "description": "Barco de guerra insignia del monarca británico Enrique VIII. Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Mary Rose", "description": "Navire de guerre. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "\"Mary Rose\"", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Emirates Spinnaker Tower', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 50.7956, -1.10857, 'http://commons.wikimedia.org/wiki/Special:FilePath/Portsmouth%2C%20Spinnaker%20Tower%20-%20geograph.org.uk%20-%20499108.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Portsmouth%2C%20Spinnaker%20Tower%20-%20geograph.org.uk%20-%20499108.jpg"}'::text[], 1, '{"en": {"name": "Spinnaker Tower", "description": "Sightseeing tower in Portsmouth, Hampshire, England. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Spinnaker Tower", "description": "170 m hoher Aussichtsturm in Portsmouth, England. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Spinnaker Tower", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Spinnaker Tower", "description": "Uitkijktoren in het Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Spinnaker Tower", "description": "Torre en Inglaterra. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "Spinnaker Tower", "description": "Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Emirates Spinnaker Tower", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Portsmouth Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 50.79047, -1.10431, 'http://commons.wikimedia.org/wiki/Special:FilePath/PortsmouthCathedral%20WestEnd.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/PortsmouthCathedral%20WestEnd.JPG"}'::text[], 2, '{"en": {"name": "Portsmouth Cathedral", "description": "Cathedral. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Portsmouth", "description": "Anglikanische Kathedrale in der englischen Stadt Portsmouth. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Portsmouth", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Portsmouth", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santo Tomás", "description": "Portsmouth. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Portsmouth", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Portsmouth Cathedral", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Portchester Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 50.8375, -1.115, 'http://commons.wikimedia.org/wiki/Special:FilePath/Portchester%20castle%2004.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Portchester%20castle%2004.jpg"}'::text[], 3, '{"en": {"name": "Portchester Castle", "description": "Medieval castle in Portchester, Hampshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Portchester Castle", "description": "Mittelalterliche Burg in Portchester, östlich von Fareham in der englischen Grafschaft Hampshire. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Portchester Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Portchester Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Portchester", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Portchester", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Portchester Castle", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
