    (v_route, 'HMS Belfast', 'Britský lehký křižník třídy Town. Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 51.50667, -0.08139, 'http://commons.wikimedia.org/wiki/Special:FilePath/HMS%20Belfast%20%28C35%29%20%289899954683%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/HMS%20Belfast%20%28C35%29%20%289899954683%29.jpg"}'::text[], 0, '{"en": {"name": "HMS Belfast", "description": "1938 Edinburgh-class light cruiser. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "HMS Belfast", "description": "Leichter Kreuzer der Royal Navy. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "HMS Belfast", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "HMS Belfast", "description": "Museum in Southwark, het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "HMS Belfast", "description": "Crucero de la clase Town. Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "HMS Belfast", "description": "Navire de guerre. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "HMS Belfast", "description": "Уламки судна біля шотландського узбережжя. Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'White Tower', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.5081, -0.07598, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tower%20of%20London%20White%20Tower.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tower%20of%20London%20White%20Tower.jpg"}'::text[], 1, '{"en": {"name": "White Tower", "description": "Central tower, the old keep, at the Tower of London. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "White Tower", "description": "Zentraler Hauptturm des Towers of London. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "White Tower", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "White Tower", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Torre Blanca (Londres)", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "tour Blanche", "description": "Donjon de la tour de Londres. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "White Tower", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'St George''s Cathedral, Southwark', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.49788, -0.1079, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20George%27s%20Cathedral%20%282022%29%20-%20London%2C%20UK.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20George%27s%20Cathedral%20%282022%29%20-%20London%2C%20UK.jpg"}'::text[], 2, '{"en": {"name": "St George''s Cathedral, Southwark", "description": "Roman Catholic cathedral in London, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St.-Georgs-Kathedrale", "description": "Kirchengebäude in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jerzego w Londynie", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St George''s Cathedral, Southwark", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Jorge, Southwark", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-George de Southwark", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St George''s Cathedral, Southwark", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Churchillovo muzeum a Cabinet War Rooms', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.50222, -0.1293, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cabinet%20war%20rooms.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cabinet%20war%20rooms.jpg"}'::text[], 3, '{"en": {"name": "Churchill War Rooms", "description": "Museum in London. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Cabinet War Rooms", "description": "Ehemals geheime Kommandozentrale der britischen Kriegsführung im Zweiten Weltkrieg in London. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Churchillovo muzeum a Cabinet War Rooms", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Churchill Museum and Cabinet War Rooms", "description": "Bouwwerk in Londen. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Churchill War Rooms", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "Churchill War Rooms", "description": "Musée londonien. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Churchillovo muzeum a Cabinet War Rooms", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Věž British Telecom', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.5215, -0.1389, 'http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg"}'::text[], 4, '{"en": {"name": "BT Tower", "description": "Communications tower located in Fitzrovia, London, England, UK. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "BT Tower", "description": "Londoner Fernsehturm. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "BT Tower", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "BT Tower", "description": "Communicatietoren in Camden, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre BT", "description": "Torre de telecomunicaciones en Reino Unido. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "BT Tower", "description": "Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Věž British Telecom", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Serpentine', 'Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 51.50528, -0.16944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Serpentine%20Lake.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Serpentine%20Lake.jpg"}'::text[], 5, '{"en": {"name": "Serpentine", "description": "Lake in Hyde Park, London, United Kingdom. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "The Serpentine", "description": "See in Hyde Park, London. Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Serpentine", "description": "Jezioro w Hyde Parku w Londynie. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Serpentine", "description": "Meer in Hyde Park, Londen. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Serpentine", "description": "Lago en Hyde Park, Londres. Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "Serpentine", "description": "Lac dans Hyde Park à Londres. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Серпентин", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'ArcelorMittal Orbit', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.53833, -0.01333, 'http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg"}'::text[], 6, '{"en": {"name": "ArcelorMittal Orbit", "description": "Sculpture and observation tower in the Olympic Park in Stratford, London. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "ArcelorMittal Orbit", "description": "Skulptur von Anish Kapoor und Cecil Balmond im Olympic Park in Stratford, London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "ArcelorMittal Orbit", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "ArcelorMittal Orbit", "description": "Bouwwerk in Londen. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "ArcelorMittal Orbit", "description": "Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour Orbit", "description": "Œuvre de Anish Kapoor et Cecil Balmond. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "ArcelorMittal Orbit", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
