    (v_route, 'Majdanpek', 'Technická památka v Srbsku — doly, železnice a stroje, na kterých stojí historie kraje.', 44.41667, 21.93333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Majdanpek%20panorama.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Majdanpek%20panorama.jpg"}'::text[], 0, '{"en": {"name": "Majdanpek", "description": "Town in Serbia. A technical monument in Serbia — mines, railways and machines behind the region''s history."}, "de": {"name": "Majdanpek", "description": "Kleinstadt in Serbien. Ein technisches Denkmal in Serbien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Majdanpek", "description": "Miasto w Serbii. Zabytek techniki w Serbii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Majdanpek", "description": "Gemeente in Servië. Een technisch monument in Servië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Majdanpek", "description": "Un monumento técnico en Serbia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Majdanpek", "description": "Ville de Serbie. Un monument technique en Serbie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Майданпек", "description": "Місто в Сербії. Технічна пам''ятка в Сербії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Rajko''s Cave', 'Přírodní zajímavost v Srbsku — místo na protažení nohou uprostřed přírody.', 44.4414, 21.9532, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rajkova%20pecina.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rajkova%20pecina.JPG"}'::text[], 1, '{"en": {"name": "Rajko''s Cave", "description": "Cave in Serbia. A natural sight in Serbia — a spot to stretch your legs amid nature."}, "de": {"name": "Rajko''s Cave", "description": "Eine Natursehenswürdigkeit in Serbien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rajko''s Cave", "description": "Jaskinia turystyczna (Majdanpek, Serbia). Atrakcja przyrodnicza w Serbii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Rajkova pećina", "description": "Een natuurbezienswaardigheid in Servië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Rajko", "description": "Cueva de Serbia. Un paraje natural en Serbia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Rajko''s Cave", "description": "Un site naturel en Serbie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Райкова", "description": "Природна пам''ятка в Сербії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Tuman monastery', 'Památka v Srbsku — kus historie přímo u trasy.', 44.59139, 21.64417, 'http://commons.wikimedia.org/wiki/Special:FilePath/ManastirTuman.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ManastirTuman.jpg"}'::text[], 2, '{"en": {"name": "Tuman monastery", "description": "14th-century Orthodox monastery in eastern Serbia. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Tuman monastery", "description": "Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Tuman monastery", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Manastir Tuman", "description": "Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Tuman monastery", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Tuman", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Монастир Тумане", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Golubac', 'Pevnost v Srbsku. Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 44.66119, 21.67848, 'http://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20Fortress%20%28%D0%B3%D1%80%D0%B0%D0%B4%20%D0%93%D0%BE%D0%BB%D1%83%D0%B1%D0%B0%D1%86%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20Fortress%20%28%D0%B3%D1%80%D0%B0%D0%B4%20%D0%93%D0%BE%D0%BB%D1%83%D0%B1%D0%B0%D1%86%29.jpg"}'::text[], 3, '{"en": {"name": "Golubac", "description": "Medieval fortified town. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Festung Golubac", "description": "Festung in Serbien. Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Golubac", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Golubački Grad", "description": "Cultureel erfgoed van bijzondere betekenis in Servië in Golubac, Servië. Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Fortaleza de Golubac", "description": "La fortaleza en la Serbia. Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Golubac", "description": "Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Golubac", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Vitovnica Monastery', 'Památka v Srbsku — kus historie přímo u trasy.', 44.37861, 21.54417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Vitovnica2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Vitovnica2.jpg"}'::text[], 4, '{"en": {"name": "Vitovnica Monastery", "description": "Monastery. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Kloster Vitovnica", "description": "Kloster in Serbien. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Monaster Vitovnica", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Vitovnica Monastery", "description": "Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Vitovnica Monastery", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Vitovnica", "description": "Monastère orthodoxe en Serbie. Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Vitovnica Monastery", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bor Lake', 'Vodní plocha v Srbsku — příjemný cíl vyjížďky s výhledy na hladinu.', 44.0929, 22.0126, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bor%20lake.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bor%20lake.jpg"}'::text[], 5, '{"en": {"name": "Bor Lake", "description": "Lake in Serbia. A body of water in Serbia — a pleasant ride destination with waterside views."}, "de": {"name": "Bor Lake", "description": "Ein Gewässer in Serbien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Bor Lake", "description": "Jezioro w Serbii. Akwen w Serbii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Bor Lake", "description": "Meer in Servië. Een waterpartij in Servië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Bor Lake", "description": "Una masa de agua en Serbia: un destino agradable con vistas al agua."}, "fr": {"name": "Bor Lake", "description": "Un plan d''eau en Serbie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Bor Lake", "description": "Водойма в Сербії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
