    (v_route, 'Krzemionki', 'Je to archeologická památková rezervace, chránící soubor neolitických pazourkových dolů, nacházející se mezi vesnicemi Sudół a Magonie v ostrověckém okresu ve Svatokřížském vojvodství v Polsku. Technická památka v Polsku — doly, železnice a stroje, na kterých stojí historie kraje.', 50.97278, 21.49417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Krzemionki%2020150519%206519.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Krzemionki%2020150519%206519.jpg"}'::text[], 0, '{"en": {"name": "Krzemionki", "description": "Neolithic and Bronze Age flint mine. A technical monument in Poland — mines, railways and machines behind the region''s history."}, "de": {"name": "Krzemionki", "description": "Prähistorische Feuersteinbergwerke. Ein technisches Denkmal in Polen — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Krzemionki", "description": "Rezerwat archeologiczny w Polsce. Zabytek techniki w Polsce — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Krzemionki", "description": "Een technisch monument in Polen — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Krzemionki", "description": "Un monumento técnico en Polonia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Krzemionki", "description": "Un monument technique en Pologne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Неолітичний рудник кременю в Кшемьонках", "description": "Технічна пам''ятка у Польщі — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Krzyżtopór', 'Hrad v Polsku. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.71389, 21.31056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Krzy%C5%BCtop%C3%B3r%202013.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Krzy%C5%BCtop%C3%B3r%202013.jpg"}'::text[], 1, '{"en": {"name": "Krzyżtopór", "description": "Castle in Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Schloss Krzyżtopór", "description": "Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Krzyżtopór", "description": "Ruiny zamku w miejscowości Ujazd, Polska. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Krzyżtopór", "description": "Kasteel in Ujazd, Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Krzyżtopór", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Krzyżtopór", "description": "Château en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Крижтопор", "description": "Замок в Польщі. Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Svatokřížský národní park', 'Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 50.87639, 20.97778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lysa%20Gora%20goloborze%203914%2020080703.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lysa%20Gora%20goloborze%203914%2020080703.jpg"}'::text[], 2, '{"en": {"name": "Świętokrzyski National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Heiligkreuz", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Świętokrzyski Park Narodowy", "description": "Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Świętokrzyski", "description": "Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Świętokrzyski", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Świętokrzyski", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Свентокшиський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Klášter Wąchock', 'Polské cisterciácké opatství. Památka v Polsku — kus historie přímo u trasy.', 51.07518, 21.0159, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wachock%20noca%20Katarzyna%20Gritzmann.Wjpg.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wachock%20noca%20Katarzyna%20Gritzmann.Wjpg.jpg"}'::text[], 3, '{"en": {"name": "Wąchock Abbey", "description": "Abbey. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kloster Wąchock", "description": "Zisterzienser-Abtei in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Cystersów w Wąchocku", "description": "Zabytkowy klasztor. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Cisterciënzerabdij van Wąchock", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Klášter Wąchock", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Wąchock", "description": "Édifice religieux polonais. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Вонхоцьке абатство", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kostel svatého Jakuba', 'Kostel v Sandoměři. Památka v Polsku — kus historie přímo u trasy.', 50.67711, 21.74444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sandomierz%20%C5%9Bw.%20Jakub.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sandomierz%20%C5%9Bw.%20Jakub.JPG"}'::text[], 4, '{"en": {"name": "Dominican Church and Convent of St. James in Sandomierz", "description": "Church building in Sandomierz, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Sankt-Jakobs-Kirche", "description": "Kloster in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Jakuba w Sandomierzu", "description": "Kościół rzymskokatolicki w Sandomierzu. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Jakobskerk", "description": "Sandomierz. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia de Santiago", "description": "Templo románico en Sandomierz, Polonia. Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église et couvent des dominicains de Sandomierz", "description": "Église polonaise. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Домініканський монастир і церква святого Якова", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Sandomierz Castle', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.67594, 21.74719, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sandomierz%20zamek.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sandomierz%20zamek.jpg"}'::text[], 5, '{"en": {"name": "Sandomierz Castle", "description": "Historic structure in Sandomierz, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Burg Sandomierz", "description": "Burg in der Woiwodschaft Heiligkreuz, Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Sandomierzu", "description": "Zamek w Polsce. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Sandomierz", "description": "Bouwwerk in Sandomierz, Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Sandomierz Castle", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Sandomierz Castle", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Сандомирський замок", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála Narození Panny Marie v Sandoměři', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 50.67658, 21.74946, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sandomierz%20Katedra1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sandomierz%20Katedra1.jpg"}'::text[], 6, '{"en": {"name": "Sandomierz Cathedral", "description": "Also known as the Cathedral Basilica of the Nativity of the Blessed Virgin Mary, Sandomierz. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kathedrale von Sandomierz", "description": "Kathedrale in der Woiwodschaft Heiligkreuz, Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Katedralna Narodzenia Najświętszej Maryi Panny w Sandomierzu", "description": "Świątynia katolicka w Polsce, zabytek. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Katedrála Narození Panny Marie v Sandoměři", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Basílica de la Natividad de la Santísima Virgen María", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de la Nativité-de-la-Vierge-Marie", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Латинський собор (Сандомир)", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb);
