    (v_route, 'SS Great Britain', 'Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 51.4492, -2.6084, 'http://commons.wikimedia.org/wiki/Special:FilePath/SS%20Great%20Britain%20%286726649319%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/SS%20Great%20Britain%20%286726649319%29.jpg"}'::text[], 0, '{"en": {"name": "SS Great Britain", "description": "1843 passenger steamship and museum in Bristol, United Kingdom. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Great Britain", "description": "Eisenschiff mit Propellerantrieb. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "SS Great Britain", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Great Britain", "description": "Werk van Isambard Kingdom Brunel. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "SS Great Britain", "description": "Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Great Britain", "description": "Navire musée britannique. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "SS Great Britain", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Bristolská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.45167, -2.60056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bristol.cathedral.west.front.arp.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bristol.cathedral.west.front.arp.jpg"}'::text[], 1, '{"en": {"name": "Bristol Cathedral", "description": "Cathedral. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Bristol Cathedral", "description": "Gebäude in England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Bristolu", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Bristol", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Brístol", "description": "Templo anglicano del Reino Unido. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de la Sainte-et-Indivisible-Trinité de Bristol", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Бристольський собор", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Wellská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.2104, -2.6437, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wells%20Cathedral%20West%20Front%20Exterior%2C%20UK%20-%20Diliff.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wells%20Cathedral%20West%20Front%20Exterior%2C%20UK%20-%20Diliff.jpg"}'::text[], 2, '{"en": {"name": "Wells Cathedral", "description": "Anglican cathedral in Wells, Somerset, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Wells", "description": "Kathedrale in Wells, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Wells", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Wells", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Wells", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-André de Wells", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Wellská katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Glastonburské opatství', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.14671, -2.71501, 'http://commons.wikimedia.org/wiki/Special:FilePath/Glastonbury%20Abbey-02-2004-gje.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Glastonbury%20Abbey-02-2004-gje.jpg"}'::text[], 3, '{"en": {"name": "Glastonbury Abbey", "description": "Former Benedictine abbey at Somerset, England, United Kingdom. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Glastonbury Abbey", "description": "Eine ehemalige Abtei der Benediktiner bei Glastonbury. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Glastonbury", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Glastonbury Abbey", "description": "Abdij in Glastonbury, Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Glastonbury", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Glastonbury", "description": "Abbaye britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Glastonburské opatství", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Cardiffský hrad', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.48231, -3.18111, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cardiff%20Castle%20-%20panoramio%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cardiff%20Castle%20-%20panoramio%20%281%29.jpg"}'::text[], 4, '{"en": {"name": "Cardiff Castle", "description": "Castle in Cardiff, Wales. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Cardiff Castle", "description": "Mittelalterliche Burg in Cardiff. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Cardiff", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Cardiff Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Cardiff", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Cardiff", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Cardiffský hrad", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter Tintern', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.6971, -2.67722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tintern%20Abbey%20and%20Courtyard.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tintern%20Abbey%20and%20Courtyard.jpg"}'::text[], 5, '{"en": {"name": "Tintern Abbey", "description": "Grade I listed ruined abbey in Tintern, Monmouthshire, Wales. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Tintern Abbey", "description": "Klosterruine in Wales. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Tintern", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "abdij van Tintern", "description": "Abdij in Tintern, Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Tinterne", "description": "Abadía en ruinas en Gales. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Tinterne", "description": "Édifice religieux britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Tintern", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Malmesburské opatství', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.5847, -2.09838, 'http://commons.wikimedia.org/wiki/Special:FilePath/1269316%20I%20ABBEY%20CHURCH%20OF%20ST%20MARY%20AND%20ST%20ALDHELM%2C%20seen%20from%20S%20Malmesbury%2020250905%200015.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/1269316%20I%20ABBEY%20CHURCH%20OF%20ST%20MARY%20AND%20ST%20ALDHELM%2C%20seen%20from%20S%20Malmesbury%2020250905%200015.jpg"}'::text[], 6, '{"en": {"name": "Malmesbury Abbey", "description": "Abbey and parish church in Malmesbury, Wiltshire, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Malmesburské opatství", "description": "Pfarrkirche im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Malmesbury", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Malmesbury", "description": "Abdij in Malmesbury, Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Malmesbury", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Malmesbury", "description": "Abbaye britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Malmesburské opatství", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb);
