    (v_route, 'Viking Ship Museum', 'Technická památka v Norsku — doly, železnice a stroje, na kterých stojí historie kraje.', 59.90475, 10.68444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oseberg%20longship.png', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oseberg%20longship.png"}'::text[], 0, '{"en": {"name": "Viking Ship Museum", "description": "Museum in Oslo. A technical monument in Norway — mines, railways and machines behind the region''s history."}, "de": {"name": "Vikingskipshuset", "description": "Wikingerschiffmuseum in Oslo. Ein technisches Denkmal in Norwegen — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Muzeum Łodzi Wikingów w Oslo", "description": "Zabytek techniki w Norwegii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Vikingskipshuset", "description": "Museum in Oslo. Een technisch monument in Noorwegen — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo de barcos vikingos de Oslo", "description": "Un monumento técnico en Noruega: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "musée des navires vikings d''Oslo", "description": "Musée en Norvège. Un monument technique en Norvège — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Музей кораблів вікінгів", "description": "Музей морської історії в Осло, Норвегія. Технічна пам''ятка в Норвегії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Akershus', 'Hrad či zámek v Norsku — historická zastávka, která stojí za odbočku.', 59.90661, 10.73625, 'http://commons.wikimedia.org/wiki/Special:FilePath/OSLO-NO-02%2005%20ubt.jpeg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/OSLO-NO-02%2005%20ubt.jpeg"}'::text[], 1, '{"en": {"name": "Akershus Fortress", "description": "Former medieval castle in Oslo, Norway. A castle in Norway — a historic stop worth the detour."}, "de": {"name": "Festung Akershus", "description": "Burg und Museum in Norwegen. Eine Burg bzw. ein Schloss in Norwegen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Akershus", "description": "Zamek w Norwegii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Akershus", "description": "Vesting. Een kasteel in Noorwegen — een historische stop die de omweg waard is."}, "es": {"name": "Fortaleza de Akershus", "description": "Un castillo en Noruega: una parada histórica que merece el desvío."}, "fr": {"name": "citadelle d''Akershus", "description": "Citadelle à Oslo, de la fin du XIIIe siècle, durant le règne du roi Håkon V de Norvège. Un château en Norvège — une halte historique qui vaut le détour."}, "uk": {"name": "Фортеця Акерсхус", "description": "Замок в Норвегії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála v Oslu', 'Kostel v Norsku. Památka v Norsku — kus historie přímo u trasy.', 59.91232, 10.74696, 'http://commons.wikimedia.org/wiki/Special:FilePath/00%207720%20Oslo%20-%20Domkirche.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/00%207720%20Oslo%20-%20Domkirche.jpg"}'::text[], 2, '{"en": {"name": "Oslo Cathedral", "description": "Cathedral in Oslo, Norway. A heritage sight in Norway — a piece of history right on your route."}, "de": {"name": "Osloer Dom", "description": "Kirchengebäude in Oslo. Ein Denkmal in Norwegen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Oslo", "description": "Zabytek w Norwegii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Oslo", "description": "Bouwwerk in Oslo. Een monument in Noorwegen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral del Salvador de Oslo", "description": "Templo luterano de Oslo (Noruega). Un monumento en Noruega: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale d''Oslo", "description": "Église norvégienne. Un monument en Norvège — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Осло", "description": "Церква у Норвегії. Пам''ятка в Норвегії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Olafa', 'Památka v Norsku — kus historie přímo u trasy.', 59.91816, 10.74413, 'http://commons.wikimedia.org/wiki/Special:FilePath/StOlavsOsloFeb2009.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/StOlavsOsloFeb2009.jpg"}'::text[], 3, '{"en": {"name": "St. Olav''s Cathedral", "description": "Cathedral in Oslo, Norway. A heritage sight in Norway — a piece of history right on your route."}, "de": {"name": "St. Olav", "description": "Kirchengebäude in Oslo. Ein Denkmal in Norwegen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Olafa w Oslo", "description": "Kościół w Norwegii. Zabytek w Norwegii — kawałek historii tuż przy trasie."}, "nl": {"name": "Domkerk Sint-Olaf", "description": "Kathedraal in Noorwegen. Een monument in Noorwegen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Olaf de Oslo", "description": "Templo católico de Oslo (Noruega). Un monumento en Noruega: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Olaf d''Oslo", "description": "Un monument en Norvège — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Олафа", "description": "Пам''ятка в Норвегії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Øyeren', 'Vodní plocha v Norsku — příjemný cíl vyjížďky s výhledy na hladinu.', 59.85722, 11.16333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oyern1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oyern1.jpg"}'::text[], 4, '{"en": {"name": "Øyeren", "description": "Lake in Rælingen, Eastern Norway, Norway. A body of water in Norway — a pleasant ride destination with waterside views."}, "de": {"name": "Øyeren", "description": "See in Norwegen. Ein Gewässer in Norwegen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Øyeren", "description": "Jezioro w Norwegii. Akwen w Norwegii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Øyeren", "description": "Meer in Noorwegen. Een waterpartij in Noorwegen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Øyeren", "description": "Una masa de agua en Noruega: un destino agradable con vistas al agua."}, "fr": {"name": "Øyeren", "description": "Lac en Norvège. Un plan d''eau en Norvège — une belle destination avec vue sur l''eau."}, "uk": {"name": "Еєрен", "description": "Озеро в Норвегії. Водойма в Норвегії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Oscarsborg Fortress', 'Hrad či zámek v Norsku — historická zastávka, která stojí za odbočku.', 59.67361, 10.60667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oscarsborg%20fortress%2C%20from%20southwest.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oscarsborg%20fortress%2C%20from%20southwest.jpg"}'::text[], 5, '{"en": {"name": "Oscarsborg Fortress", "description": "Coastal fortress in the Oslofjord, Norway. A castle in Norway — a historic stop worth the detour."}, "de": {"name": "Oscarsborg", "description": "Festung im Oslofjord, hat 1940 den Kreuzer Blücher versenkt. Eine Burg bzw. ein Schloss in Norwegen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Oscarsborg", "description": "Twierdza w Norwegii. Zamek w Norwegii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Fort Oscarsborg", "description": "Militair museum in Noorwegen. Een kasteel in Noorwegen — een historische stop die de omweg waard is."}, "es": {"name": "Oscarsborg Fortress", "description": "Un castillo en Noruega: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse d''Oscarsborg", "description": "Un château en Norvège — une halte historique qui vaut le détour."}, "uk": {"name": "Фортеця Оскарборг", "description": "Замок в Норвегії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Tyrifjorden', 'Jezero v norském kraji Buskerud. Vodní plocha v Norsku — příjemný cíl vyjížďky s výhledy na hladinu.', 60.03333, 10.13333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Holsfjorden%2C%20Hole.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Holsfjorden%2C%20Hole.jpg"}'::text[], 6, '{"en": {"name": "Tyrifjorden", "description": "Lake in Norway. A body of water in Norway — a pleasant ride destination with waterside views."}, "de": {"name": "Tyrifjord", "description": "See in Norwegen. Ein Gewässer in Norwegen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Tyrifjorden", "description": "Akwen w Norwegii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Tyrifjord", "description": "Meer in Noorwegen. Een waterpartij in Noorwegen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Tyrifjorden", "description": "Lago de Noruega. Una masa de agua en Noruega: un destino agradable con vistas al agua."}, "fr": {"name": "Tyrifjord", "description": "Lac en Norvège. Un plan d''eau en Norvège — une belle destination avec vue sur l''eau."}, "uk": {"name": "Тюріфйорд", "description": "Водойма в Норвегії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
