    (v_route, 'Osservatorio Astrofisico', 'Technická památka v Itálii — doly, železnice a stroje, na kterých stojí historie kraje.', 45.8663, 11.52608, 'http://commons.wikimedia.org/wiki/Special:FilePath/Children%20building%20an%20E-ELT%20mirror.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Children%20building%20an%20E-ELT%20mirror.jpg"}'::text[], 0, '{"en": {"name": "Asiago Astrophysical Observatory", "description": "Italian astronomical observatory. A technical monument in Italy — mines, railways and machines behind the region''s history."}, "de": {"name": "Osservatorio Astrofisico di Asiago", "description": "Sternwarte in Italien. Ein technisches Denkmal in Italien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Osservatorio Astrofisico", "description": "Zabytek techniki we Włoszech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Asagio Astrofysisch Observatorium", "description": "Observatorium in Italië. Een technisch monument in Italië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Observatorio Astrofísico de Asiago", "description": "Observatorio astronómico italiano. Un monumento técnico en Italia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "observatoire d''Asiago", "description": "Observatoire astronomique en Italie. Un monument technique en Italie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Обсерваторія Азіаґо", "description": "Населений пункт в Італії. Технічна пам''ятка в Італії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Lago di Levico', 'Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 46.01368, 11.27821, 'http://commons.wikimedia.org/wiki/Special:FilePath/Levico%20und%20der%20Levicosee.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Levico%20und%20der%20Levicosee.JPG"}'::text[], 1, '{"en": {"name": "Lago di Levico", "description": "Lake in Levico Terme, Trentino-South Tyrol, Italy. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Lago di Levico", "description": "See im Trentino, Italien. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lago di Levico", "description": "Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lago di Levico", "description": "Meer in Italië. Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Levico", "description": "Lago en Italia. Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Levico", "description": "Lac italien. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Lago di Levico", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Lago di Caldonazzo', 'Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 46.01853, 11.24244, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20caldonazzo.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20caldonazzo.jpg"}'::text[], 2, '{"en": {"name": "Lago di Caldonazzo", "description": "Lake in Trentino-South Tyrol, Italy. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Gallnötschsee", "description": "See im Trentino, Italien. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lago di Caldonazzo", "description": "Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Caldonazzo", "description": "Meer in Italië. Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago di Caldonazzo", "description": "Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Caldonazzo", "description": "Lac italien. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Lago di Caldonazzo", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Castello del Buonconsiglio', 'Hrad v Itálii. Hrad či zámek v Itálii — historická zastávka, která stojí za odbočku.', 46.07157, 11.12704, 'http://commons.wikimedia.org/wiki/Special:FilePath/20110727%20Trento%20Buonconsiglio%20Castle%206609.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20110727%20Trento%20Buonconsiglio%20Castle%206609.jpg"}'::text[], 3, '{"en": {"name": "Buonconsiglio Castle", "description": "Castle in Trento, Italy. A castle in Italy — a historic stop worth the detour."}, "de": {"name": "Castello del Buonconsiglio", "description": "Bischofsresidenz und Museum in Trient, Italien. Eine Burg bzw. ein Schloss in Italien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castello del Buonconsiglio", "description": "Zamek we Włoszech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Buonconsiglio Castle", "description": "Een kasteel in Italië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo del Buonconsiglio", "description": "Museo italiano, Trento. Un castillo en Italia: una parada histórica que merece el desvío."}, "fr": {"name": "château du Bon-Conseil", "description": "Musée italien, Trente. Un château en Italie — une halte historique qui vaut le détour."}, "uk": {"name": "Castello del Buonconsiglio", "description": "Замок в Італії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatého Vigila v Tridentu', 'Katedrála v Itálii. Památka v Itálii — kus historie přímo u trasy.', 46.0669, 11.1215, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trento%2C%20cattedrale%20di%20San%20Vigilio%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trento%2C%20cattedrale%20di%20San%20Vigilio%202.jpg"}'::text[], 4, '{"en": {"name": "Trento Cathedral", "description": "Cathedral in Trento, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Dom von Trient", "description": "Kathedrale. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Wigiliusza w Trydencie", "description": "Rzymskokatolicka katedra we Włoszech. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Trento Cathedral", "description": "Kathedraal in Trente, Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Vigilio", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Dôme de Trente", "description": "Édifice religieux situé en Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Трента", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála ve Vicenze', 'Církevní budova ve Vicenze, Itálie. Památka v Itálii — kus historie přímo u trasy.', 45.5462, 11.5435, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20%28Vicenza%29%20-%20Sud%20esposizione.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20%28Vicenza%29%20-%20Sud%20esposizione.jpg"}'::text[], 5, '{"en": {"name": "Vicenza Cathedral", "description": "Cathedral in Vicenza, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Dom von Vicenza", "description": "Kathedrale in Italien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedrála ve Vicenze", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Vicenza Cathedral", "description": "Kathedraal in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Vicenza", "description": "Catedral de Italia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Vicence", "description": "Édifice religieux italien. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála ve Vicenze", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Monte Berico', 'Památka v Itálii — kus historie přímo u trasy.', 45.53509, 11.5455, 'http://commons.wikimedia.org/wiki/Special:FilePath/Veneto%20Vicenza2%20Madonna%20Monte%20Berico%20tango7174.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Veneto%20Vicenza2%20Madonna%20Monte%20Berico%20tango7174.jpg"}'::text[], 6, '{"en": {"name": "Monte Berico", "description": "Roman Catholic and minor basilica in Vicenza, northern Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Basilika Santa Maria di Monte Berico", "description": "Kirchengebäude in Vicenza, Italien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sanktuarium Matki Bożej z Monte Berico", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Monte Berico", "description": "Kerkgebouw in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monte Berico", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Sanctuaire de Notre-Dame du Mont Berico", "description": "Église italienne. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Monte Berico", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb);
