    (v_route, 'železniční trať Tywyn - Nant Gwernol', 'Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 52.58367, -4.08875, 'http://commons.wikimedia.org/wiki/Special:FilePath/Edward%20Thomas%20at%20Tywyn%20Wharf%20-%202005-04-29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Edward%20Thomas%20at%20Tywyn%20Wharf%20-%202005-04-29.jpg"}'::text[], 0, '{"en": {"name": "Talyllyn Railway", "description": "Narrow gauge railway in north Wales. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Talyllyn Railway", "description": "Schmalspurbahn in Wales. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "železniční trať Tywyn - Nant Gwernol", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Talyllyn spoorlijn", "description": "Spoorlijn in Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Ferrocarril Talyllyn", "description": "Ferrocarril de vía estrecha conservado en Gales. Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "chemin de fer de Talyllyn", "description": "Ligne de chemin de fer britannnique. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "železniční trať Tywyn - Nant Gwernol", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Dolgoch Falls', 'Přírodní zajímavost ve Velké Británii — místo na protažení nohou uprostřed přírody.', 52.6195, -3.9915, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dolgoch%20Falls%20-%202007-09-01.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dolgoch%20Falls%20-%202007-09-01.jpg"}'::text[], 1, '{"en": {"name": "Dolgoch Falls", "description": "Waterfall in Gwynedd, Wales, UK. A natural sight in the United Kingdom — a spot to stretch your legs amid nature."}, "de": {"name": "Dolgoch Falls", "description": "Wasserfall im Vereinigten Königreich. Eine Natursehenswürdigkeit in Großbritannien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Dolgoch Falls", "description": "Atrakcja przyrodnicza w Wielkiej Brytanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Dolgoch Falls", "description": "Een natuurbezienswaardigheid in het Verenigd Koninkrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Dolgoch", "description": "Cascada. Un paraje natural en el Reino Unido: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Dolgoch Falls", "description": "Un site naturel au Royaume-Uni — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Dolgoch Falls", "description": "Природна пам''ятка у Великій Британії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Aberystwyth Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 52.41328, -4.0895, 'http://commons.wikimedia.org/wiki/Special:FilePath/Arfordir%20Aberystwyth%2C%20Ceredigion%20-%20Aberystwyth%20SAC%20Special%20Areas%20of%20Conservation%2C%20West%20Wales%20Marine%2043.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Arfordir%20Aberystwyth%2C%20Ceredigion%20-%20Aberystwyth%20SAC%20Special%20Areas%20of%20Conservation%2C%20West%20Wales%20Marine%2043.jpg"}'::text[], 2, '{"en": {"name": "Aberystwyth Castle", "description": "Grade I listed castle in Ceredigion, Wales. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Aberystwyth Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Aberystwyth", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Aberystwyth Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Aberystwyth Castle", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Aberystwyth", "description": "Château gallois. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Aberystwyth Castle", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
