    (v_route, 'Neolitické pazourkové doly ve Spiennes', 'Technická památka v Belgii — doly, železnice a stroje, na kterých stojí historie kraje.', 50.41999, 3.98258, 'http://commons.wikimedia.org/wiki/Special:FilePath/Spiennes%20-%20Mini%C3%A8res%20n%C3%A9olithiques%20de%20silex%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Spiennes%20-%20Mini%C3%A8res%20n%C3%A9olithiques%20de%20silex%20%282%29.jpg"}'::text[], 0, '{"en": {"name": "Neolithic flint mines of Spiennes", "description": "Mine. A technical monument in Belgium — mines, railways and machines behind the region''s history."}, "de": {"name": "Jungsteinzeitliche Feuersteinbergwerke bei Spiennes", "description": "Bergwerk in Belgien. Ein technisches Denkmal in Belgien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Neolitické pazourkové doly ve Spiennes", "description": "Zabytek techniki w Belgii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Neolithische vuursteenmijnen in Spiennes", "description": "Mijn in Bergen, België. Een technisch monument in België — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Minas neolíticas de sílex de Spiennes", "description": "Un monumento técnico en Bélgica: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "minières néolithiques de silex de Spiennes", "description": "Site archéologique de Mons, Belgique. Un monument technique en Belgique — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Неолітичні кремнієві копальні в районі Спьєнн", "description": "Технічна пам''ятка у Бельгії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Grand Large', 'Vodní plocha v Belgii — příjemný cíl vyjížďky s výhledy na hladinu.', 50.47139, 3.93611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mons%20Grand%20Large%202006%20044.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mons%20Grand%20Large%202006%20044.jpg"}'::text[], 1, '{"en": {"name": "Grand Large", "description": "Lake in Belgium. A body of water in Belgium — a pleasant ride destination with waterside views."}, "de": {"name": "Grand Large", "description": "See in Belgien. Ein Gewässer in Belgien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Grand Large", "description": "Akwen w Belgii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Grand Large", "description": "Meer in Bergen, België. Een waterpartij in België — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Grand Large", "description": "Lago de Bélgica. Una masa de agua en Bélgica: un destino agradable con vistas al agua."}, "fr": {"name": "Grand Large", "description": "Plan d''eau artificiel à Mons en Belgique. Un plan d''eau en Belgique — une belle destination avec vue sur l''eau."}, "uk": {"name": "Grand Large", "description": "Водойма у Бельгії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Château de Belœil', 'Zámek v belgickém Belœil (Hainaut, Valonsko) slouží od r. 1394 jako sídlo šlechtické rodiny „de Ligne“. Leží uprostřed barokní zahrady navržené v roce 1664. Zámek i zahrady jsou veřejně dostupné v jarním a letním období. Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.55097, 3.73017, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Beloeil%20-%20Belgium.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Beloeil%20-%20Belgium.jpg"}'::text[], 2, '{"en": {"name": "Château de Belœil", "description": "Château in Wallonia, Belgium. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Schloss Belœil", "description": "Schloss in der Wallonie, Belgien. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Château de Belœil", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Belœil", "description": "Kasteel in Wallonië. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Château de Belœil", "description": "Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "château de Belœil", "description": "Château en Wallonie. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Château de Belœil", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Castle of Seneffe', 'Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.52533, 4.27025, 'http://commons.wikimedia.org/wiki/Special:FilePath/Le%20ch%C3%A2teau%20et%20son%20fronton%20%2822756451779%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Le%20ch%C3%A2teau%20et%20son%20fronton%20%2822756451779%29.jpg"}'::text[], 3, '{"en": {"name": "Castle of Seneffe", "description": "Castle in Wallonia. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Château de Seneffe", "description": "Schloss in der Wallonie. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castle of Seneffe", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Seneffe", "description": "Kasteel in Seneffe, Wallonië. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Castle of Seneffe", "description": "Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "château de Seneffe", "description": "Château en Wallonie. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Сенефський замок", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter Aulne', 'Památka v Belgii — kus historie přímo u trasy.', 50.36662, 4.33118, 'http://commons.wikimedia.org/wiki/Special:FilePath/Facade%20of%20the%20Aulne%20Abbey%20during%20golden%20hour%20%28DSC%200123%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Facade%20of%20the%20Aulne%20Abbey%20during%20golden%20hour%20%28DSC%200123%29.jpg"}'::text[], 4, '{"en": {"name": "Aulne Abbey", "description": "Cistercian monastery in Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Abtei Aulne", "description": "Abgegangenes Bauwerk in Belgien. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klášter Aulne", "description": "Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Aulne", "description": "Abdij in Thuin, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Aulne", "description": "Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye d''Aulne", "description": "Abbaye en ruine de Belgique. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Aulne", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Soleilmont Abbey', 'Památka v Belgii — kus historie přímo u trasy.', 50.4452, 4.50545, 'http://commons.wikimedia.org/wiki/Special:FilePath/Soleilmont%3B%20Abbaye%20%28nouveaux%20batiments%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Soleilmont%3B%20Abbaye%20%28nouveaux%20batiments%29.JPG"}'::text[], 5, '{"en": {"name": "Soleilmont Abbey", "description": "Church building in Gilly, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Trappistinnenabtei Soleilmont", "description": "Kirchengebäude in Belgien. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Soleilmont Abbey", "description": "Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Onze-Lieve-Vrouwabdijkerk", "description": "Kerkgebouw in Gilly, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Soleilmont", "description": "Abadía de monjas trapenses en Bélgica. Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Notre-Dame de Soleilmont", "description": "Édifice religieux belge. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Soleilmont Abbey", "description": "Церква в Бельгії. Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Eau d''Heure lakes', 'Vodní plocha v Belgii — příjemný cíl vyjížďky s výhledy na hladinu.', 50.18861, 4.38556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Barrages%20de%20l%27Eau%20d%27Heure%3B%20Lac%20de%20l%27Eau%20d%27heure%20vu%20du%20barrage%20de%20Falemprise.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Barrages%20de%20l%27Eau%20d%27Heure%3B%20Lac%20de%20l%27Eau%20d%27heure%20vu%20du%20barrage%20de%20Falemprise.jpg"}'::text[], 6, '{"en": {"name": "Eau d''Heure lakes", "description": "Lake. A body of water in Belgium — a pleasant ride destination with waterside views."}, "de": {"name": "Eau d''Heure lakes", "description": "Stausee in Belgien. Ein Gewässer in Belgien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Eau d''Heure lakes", "description": "Akwen w Belgii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meren van de Eau d''Heure", "description": "Meer in België. Een waterpartij in België — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lacs de l''Eau d''Heure", "description": "Una masa de agua en Bélgica: un destino agradable con vistas al agua."}, "fr": {"name": "lacs de l''Eau d''Heure", "description": "Lacs en Belgique. Un plan d''eau en Belgique — une belle destination avec vue sur l''eau."}, "uk": {"name": "О-Дор", "description": "Озеро. Водойма у Бельгії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
