    (v_route, 'HMY Britannia', 'Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 55.98213, -3.1773, 'http://commons.wikimedia.org/wiki/Special:FilePath/HMY%20Britannia.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/HMY%20Britannia.jpg"}'::text[], 0, '{"en": {"name": "HMY Britannia", "description": "1953 royal yacht. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "HMY Britannia", "description": "Museumsschiff, 83. Königliche Yacht von Großbritannien. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "HMY Britannia", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "HMY Britannia", "description": "Schip in Edinburgh, het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "HMY Britannia", "description": "Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Britannia", "description": "Navire musée britannique. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "HMY Britannia", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Holyroodské opatství', 'Památka ve Velké Británii — kus historie přímo u trasy.', 55.95316, -3.17157, 'http://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh%20-%20Holyrood%20Abbey%2C%20precinct%20and%20associated%20remains%20-%2020140427120646.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh%20-%20Holyrood%20Abbey%2C%20precinct%20and%20associated%20remains%20-%2020140427120646.jpg"}'::text[], 1, '{"en": {"name": "Holyrood Abbey", "description": "Monastery ruins in Holyrood, City of Edinburgh, Scotland, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Holyrood Abbey", "description": "Ruine im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Holyrood", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Holyrood Abbey", "description": "Voormalig bouwwerk in Schotland, Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Holyrood", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "Holyrood Abbey", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Голірудське абатство", "description": "Напівзруйнований монастир в Едінбурзі, Шотландія. Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Jiljí', 'Katedrála skotské církve v Edinburghu ve Skotsku ve Spojeném království. Památka ve Velké Británii — kus historie přímo u trasy.', 55.94944, -3.19083, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20Giles%27%20Cathedral%20-%20aerial%20-%202025-04-19%2004.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20Giles%27%20Cathedral%20-%20aerial%20-%202025-04-19%2004.jpg"}'::text[], 2, '{"en": {"name": "St Giles'' Cathedral", "description": "Church of Scotland cathedral in Edinburgh, Scotland, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St Giles’ Cathedral", "description": "Kirchengebäude in Edinburgh. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Idziego w Edynburgu", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St Giles'' Cathedral", "description": "Bouwwerk in Edinburgh. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Saint Giles", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Gilles d''Édimbourg", "description": "Église à Édimbourg, Écosse (Royaume-Uni). Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Jiljí", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Edinburský hrad', 'Hrad ve Velké Británii. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 55.9487, -3.20073, 'http://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh%20Castle%20from%20the%20Grassmarket.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh%20Castle%20from%20the%20Grassmarket.jpg"}'::text[], 3, '{"en": {"name": "Edinburgh Castle", "description": "Castle in Edinburgh, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Edinburgh Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Edynburgu", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Edinburgh Castle", "description": "Bouwwerk in Edinburgh. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Edimburgo", "description": "Antigua fortaleza en Edimburgo, Escocia. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Édimbourg", "description": "Château en Écosse. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Единбурзький замок", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Dunfermline Palace', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.0695, -3.46461, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dunfermline%20Palace%20south%20wall%20and%20Gatehouse.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dunfermline%20Palace%20south%20wall%20and%20Gatehouse.JPG"}'::text[], 4, '{"en": {"name": "Dunfermline Palace", "description": "Ruined former royal palace in Scotland. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Dunfermline Palace", "description": "Schlossruine in Schottland. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Dunfermline", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Dunfermline Palace", "description": "Voormalig bouwwerk in Schotland, Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Dunfermline", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Dunfermline", "description": "Ancien palais royal écossais. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Данфермлінський палац", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Palác Linlithgow', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 55.9785, -3.60097, 'http://commons.wikimedia.org/wiki/Special:FilePath/Linlithgow%20Palace%20NW%2003.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Linlithgow%20Palace%20NW%2003.jpg"}'::text[], 5, '{"en": {"name": "Linlithgow Palace", "description": "Ruined palace in West Lothian, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Linlithgow Palace", "description": "Schlossruine in Schottland. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Linlithgow", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Linlithgow Palace", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Linlithgow", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Linlithgow", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Лінлітґоу", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Falklandský palác', 'Palác ve Skotsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.2548, -3.20609, 'http://commons.wikimedia.org/wiki/Special:FilePath/Falkland%20Palace.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Falkland%20Palace.jpg"}'::text[], 6, '{"en": {"name": "Falkland Palace", "description": "Castle in Fife, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Falkland Palace", "description": "Schloss in Schottland. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Falkland", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Falkland Palace", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Falkland", "description": "Castillo en Fife, Escocia (Reino Unido). Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Falkland", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Фолклендський палац", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb);
