    (v_route, 'Ludgate', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.51397, -0.10231, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ludgate%20Hollar.PNG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ludgate%20Hollar.PNG"}'::text[], 1, '{"en": {"name": "Ludgate", "description": "Ancient and ceremonial gate of the London Wall within the City of London. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Ludgate", "description": "Stadttor des mittelalterlichen London. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Ludgate", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Ludgate", "description": "Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Ludgate", "description": "Puerta de la Muralla de Londres de la City de Londres. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "Ludgate", "description": "Porte historique de la Cité de Londres. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Ludgate", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bevis Marks Synagogue', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.5145, -0.07905, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bevis%20Marks%20Synagogue%20-%20geograph.org.uk%20-%201229874.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bevis%20Marks%20Synagogue%20-%20geograph.org.uk%20-%201229874.jpg"}'::text[], 2, '{"en": {"name": "Bevis Marks Synagogue", "description": "Synagogue in the City of London. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Bevis-Marks-Synagoge", "description": "Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bevis Marks Synagogue", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Bevis Marks Synagogue", "description": "Synagoge in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga de Bevis Marks", "description": "Templo judío en Londres. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Bevis Marks", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bevis Marks Synagogue", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Barking Abbey', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.5359, 0.07544, 'http://commons.wikimedia.org/wiki/Special:FilePath/Barking%20abbey%20curfew%20tower%20london.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Barking%20abbey%20curfew%20tower%20london.jpg"}'::text[], 3, '{"en": {"name": "Barking Abbey", "description": "Building in London, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Barking Abbey", "description": "Kloster im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Barking Abbey", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Barking Abbey", "description": "Klooster in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abadía de Barking", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Barking", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Barking Abbey", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Brentwood Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.6194, 0.3063, 'http://commons.wikimedia.org/wiki/Special:FilePath/Brentwood%20Cathedral-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Brentwood%20Cathedral-2.jpg"}'::text[], 4, '{"en": {"name": "Brentwood Cathedral", "description": "Roman Catholic cathedral in Brentwood, Essex, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Brentwood", "description": "Gebäude in England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Brentwood", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Brentwood Cathedral", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santa María y Santa Helena", "description": "Catedral de Brentwood, Reino Unido. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Marie-et-Sainte-Hélène de Brentwood", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Brentwood Cathedral", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'WWT London Wetland Centre', 'Přírodní zajímavost ve Velké Británii — místo na protažení nohou uprostřed přírody.', 51.4786, -0.2344, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wetland%20Centre%20Lagoon.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wetland%20Centre%20Lagoon.jpg"}'::text[], 5, '{"en": {"name": "WWT London Wetland Centre", "description": "Wetland reserve in the Barnes area of the London Borough of Richmond upon Thames. A natural sight in the United Kingdom — a spot to stretch your legs amid nature."}, "de": {"name": "WWT London Wetland Centre", "description": "Eine Natursehenswürdigkeit in Großbritannien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "London Wetland Centre", "description": "Rezerwat przyrody. Atrakcja przyrodnicza w Wielkiej Brytanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "WWT London Wetland Centre", "description": "Natuurreservaat in het Verenigd Koninkrijk. Een natuurbezienswaardigheid in het Verenigd Koninkrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "WWT London Wetland Centre", "description": "Un paraje natural en el Reino Unido: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "WWT London Wetland Centre", "description": "Un site naturel au Royaume-Uni — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "WWT London Wetland Centre", "description": "Природна пам''ятка у Великій Британії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Watkin''s Tower', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.55556, -0.27944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Watkin%20tower%20first%20stage.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Watkin%20tower%20first%20stage.jpg"}'::text[], 6, '{"en": {"name": "Watkin''s Tower", "description": "Partially completed iron lattice tower in London, England. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Watkins Tower", "description": "Unvollendetes Turmbauvorhaben in London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Watkin’s Tower", "description": "Konstrukcja kratowa z kutego żelaza (nieukończona wieża; Londyn, Wielka Brytania; 1894–1907). Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Watkin''s Tower", "description": "Folly in Londen, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de Watkin", "description": "Torre de celosía de hierro parcialmente terminada en Londres, Inglaterra. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de Watkin", "description": "Tour inachevée de Londres. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Watkin''s Tower", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
