    (v_route, 'Erzberg mine', 'Hora v Rakousku. Technická památka v Rakousku — doly, železnice a stroje, na kterých stojí historie kraje.', 47.525, 14.91167, 'http://commons.wikimedia.org/wiki/Special:FilePath/18-08-08-Erzberg%20RRK6017.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/18-08-08-Erzberg%20RRK6017.jpg"}'::text[], 0, '{"en": {"name": "Erzberg mine", "description": "Mountain in Styria. A technical monument in Austria — mines, railways and machines behind the region''s history."}, "de": {"name": "Erzberg", "description": "Berg in der Steiermark, Eisenerzer Alpen. Ein technisches Denkmal in Österreich — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Erzberg mine", "description": "Zabytek techniki w Austrii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Erzberg mine", "description": "Berg in Oostenrijk. Een technisch monument in Oostenrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Erzberg mine", "description": "Un monumento técnico en Austria: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Erzberg mine", "description": "Montagne autrichienne. Un monument technique en Autriche — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Ерцберг", "description": "Технічна пам''ятка в Австрії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Grüner See', 'Vodní plocha v Rakousku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.54167, 15.05583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%BCnerSeeAgainstMe%C3%9Fnerin.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gr%C3%BCnerSeeAgainstMe%C3%9Fnerin.jpg"}'::text[], 1, '{"en": {"name": "Grüner See", "description": "Lake in the Hochschwab Group in Styria. A body of water in Austria — a pleasant ride destination with waterside views."}, "de": {"name": "Grüner See", "description": "See in der Hochschwabgruppe in der Steiermark. Ein Gewässer in Österreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Grüner See", "description": "Jezioro w Austrii. Akwen w Austrii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Grüner See", "description": "Meer in Oostenrijk. Een waterpartij in Oostenrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Grüner See", "description": "Lago de Austria. Una masa de agua en Austria: un destino agradable con vistas al agua."}, "fr": {"name": "Grüner See", "description": "Lac de Styrie en Autriche. Un plan d''eau en Autriche — une belle destination avec vue sur l''eau."}, "uk": {"name": "Грюнер-Зее", "description": "Водойма в Австрії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Národní park Gesäuse', 'Národní park ve Štýrsku, Rakousko. Přírodní zajímavost v Rakousku — místo na protažení nohou uprostřed přírody.', 47.5922, 14.6489, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Ges%C3%A4use%20National%20Park%20%28view%20from%20the%20west%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Ges%C3%A4use%20National%20Park%20%28view%20from%20the%20west%29.jpg"}'::text[], 2, '{"en": {"name": "Gesäuse National Park", "description": "National park of Austria. A natural sight in Austria — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Gesäuse", "description": "Nationalpark in Österreich. Eine Natursehenswürdigkeit in Österreich — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Gesäuse", "description": "Park narodowy w Austrii. Atrakcja przyrodnicza w Austrii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Gesäuse", "description": "Nationaal park in Oostenrijk. Een natuurbezienswaardigheid in Oostenrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Gesäuse", "description": "Área protegida de Austria (6496). Un paraje natural en Austria: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Gesäuse", "description": "Parc national d''Autriche. Un site naturel en Autriche — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Гезойзе", "description": "Національний парк в Австрії. Природна пам''ятка в Австрії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Opatství Admont', 'Benediktinský klášter v Rakousku. Památka v Rakousku — kus historie přímo u trasy.', 47.57502, 14.46216, 'http://commons.wikimedia.org/wiki/Special:FilePath/Admont%20-%20Benediktinerstift.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Admont%20-%20Benediktinerstift.JPG"}'::text[], 3, '{"en": {"name": "Admont Abbey", "description": "Abbey in Styria, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stift Admont", "description": "Benediktinerstift in Admont, Ennstal, Steiermark. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opatství Admont", "description": "Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Admont", "description": "Kunstmuseum in Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Admont", "description": "Abadía y museo en Austria. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye d''Admont", "description": "Monastère bénédictin autrichien. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Адмонтське абатство", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Ingeringsee', 'Vodní plocha v Rakousku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.34418, 14.65944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ingeringsee.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ingeringsee.jpg"}'::text[], 4, '{"en": {"name": "Ingeringsee", "description": "Lake in the Seckau Tauern in Styria. A body of water in Austria — a pleasant ride destination with waterside views."}, "de": {"name": "Ingeringsee", "description": "See in den Seckauer Tauern in der Steiermark. Ein Gewässer in Österreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Ingeringsee", "description": "Jezioro w Austrii, w Styrii. Akwen w Austrii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Ingeringsee", "description": "Meer in Oostenrijk. Een waterpartij in Oostenrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Ingeringsee", "description": "Una masa de agua en Austria: un destino agradable con vistas al agua."}, "fr": {"name": "Ingeringsee", "description": "Lac autrichien. Un plan d''eau en Autriche — une belle destination avec vue sur l''eau."}, "uk": {"name": "Ingeringsee", "description": "Озеро. Водойма в Австрії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Goldlacke', 'Horské jezero. Vodní plocha v Rakousku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.3381, 14.752, 'http://commons.wikimedia.org/wiki/Special:FilePath/Goldlacke.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Goldlacke.jpg"}'::text[], 5, '{"en": {"name": "Goldlacke", "description": "Lake in the Seckauer Tauern in Styria, Austria. A body of water in Austria — a pleasant ride destination with waterside views."}, "de": {"name": "Goldlacke", "description": "Bergsee in den Seckauer Tauern in der Steiermark. Ein Gewässer in Österreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Goldlacke", "description": "Jezioro w Austrii, w Styrii. Akwen w Austrii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Goldlacke", "description": "Meer in Oostenrijk. Een waterpartij in Oostenrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Goldlacke", "description": "Una masa de agua en Austria: un destino agradable con vistas al agua."}, "fr": {"name": "Goldlacke", "description": "Lac autrichien. Un plan d''eau en Autriche — une belle destination avec vue sur l''eau."}, "uk": {"name": "Goldlacke", "description": "Водойма в Австрії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Sekavský klášter', 'Klášter ve Štýrsku. Památka v Rakousku — kus historie přímo u trasy.', 47.27422, 14.78746, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C3%84u%C3%9Ferer%20Klosterhof%20Benediktinerabtei%20Seckau.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C3%84u%C3%9Ferer%20Klosterhof%20Benediktinerabtei%20Seckau.JPG"}'::text[], 6, '{"en": {"name": "Seckau Abbey", "description": "Abbey. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stift Seckau", "description": "Kloster der Benediktiner in Seckau, Steiermark, Österreich. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo w Seckau", "description": "Muzeum w Austrii. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Seckau", "description": "Abdij in Stiermarken, Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral y Abadía de la Asunción de María", "description": "Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Seckau", "description": "Musée en Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Sekavský klášter", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb);
