    (v_route, 'HMS Warrior', 'Britská pancéřová loď třídy Warrior. Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 50.79833, -1.10889, 'http://commons.wikimedia.org/wiki/Special:FilePath/HMS%20warriorjune20092.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/HMS%20warriorjune20092.jpg"}'::text[], 0, '{"en": {"name": "HMS Warrior", "description": "1860 Warrior-class ironclad. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "HMS Warrior", "description": "Panzerschiff mit eisernem Rumpf, heute Museumsschiff in Portsmouth. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "HMS Warrior", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "HMS Warrior", "description": "Museum in het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "HMS Warrior", "description": "Acorazado de 1861. Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "HMS Warrior", "description": "Navire de guerre à coque en fer. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Warrior (1860)", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Cathedral of St John the Evangelist', 'Památka ve Velké Británii — kus historie přímo u trasy.', 50.80035, -1.09429, 'http://commons.wikimedia.org/wiki/Special:FilePath/PortsmouthRCCathedral.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/PortsmouthRCCathedral.jpg"}'::text[], 1, '{"en": {"name": "Cathedral of St John the Evangelist", "description": "Roman Catholic cathedral in Portsmouth, England. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Portsmouth", "description": "Römisch-katholische Kathedrale der Diözese von Portsmouth. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jana Ewangelisty w Portsmouth", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Cathedral of St John the Evangelist", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan Evangelista", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean-l''Évangéliste de Portsmouth", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Іоанна Євангеліста", "description": "Римо-католицький собор у Портсмуті, Англія. Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Southsea Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 50.778, -1.08888, 'http://commons.wikimedia.org/wiki/Special:FilePath/Southsea%20castle%20from%20the%20east.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Southsea%20castle%20from%20the%20east.JPG"}'::text[], 2, '{"en": {"name": "Southsea Castle", "description": "Castle in Portsmouth, Hampshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Southsea Castle", "description": "Ehemalige Küstenbefestigung im Süden der englischen Stadt Portsmouth. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Southsea Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Southsea Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Southsea Castle", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Southsea", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Southsea Castle", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
