    (v_route, 'Salina Turda', 'Technická památka v Rumunsku — doly, železnice a stroje, na kterých stojí historie kraje.', 46.5877, 23.7874, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rudolfmijn%20Salina%20Turda.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rudolfmijn%20Salina%20Turda.jpg"}'::text[], 0, '{"en": {"name": "Salina Turda", "description": "Salt mine of Romania. A technical monument in Romania — mines, railways and machines behind the region''s history."}, "de": {"name": "Salzbergwerk Turda", "description": "Ein technisches Denkmal in Rumänien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Kopalnia soli Turda", "description": "Zabytkowa kopalnia soli w Rumunii. Zabytek techniki w Rumunii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Salina Turda", "description": "Mijn in Roemenië. Een technisch monument in Roemenië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Salina Turda", "description": "Un monumento técnico en Rumanía: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Salina Turda", "description": "Un monument technique en Roumanie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Соляна копальня у місті Турда", "description": "Об''єкт культурної спадщини в Румунії. Технічна пам''ятка в Румунії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
