    (v_route, 'Cité du Train', 'Technická památka ve Francii — doly, železnice a stroje, na kterých stojí historie kraje.', 47.75056, 7.29389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cite%20du%20train.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cite%20du%20train.JPG"}'::text[], 0, '{"en": {"name": "Cité du train", "description": "National railway museum of France, in Mulhouse. A technical monument in France — mines, railways and machines behind the region''s history."}, "de": {"name": "Eisenbahnmuseum Mulhouse", "description": "Französisches Eisenbahnmuseum. Ein technisches Denkmal in Frankreich — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Cité du train", "description": "Zabytek techniki we Francji — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Cité du train", "description": "Museum in Frankrijk. Een technisch monument in Frankrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Cité du train", "description": "Museo Nacional del Ferrocarril de Francia, en Mulhouse. Un monumento técnico en Francia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Cité du train", "description": "Musée à Mulhouse, dans le Haut-Rhin, en France. Un monument technique en France — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Cité du Train", "description": "Технічна пам''ятка у Франції — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Abbaye Notre-Dame d''Oelenberg', 'Památka ve Francii — kus historie přímo u trasy.', 47.74603, 7.21337, 'http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye-oelenberg-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Abbaye-oelenberg-1.jpg"}'::text[], 1, '{"en": {"name": "Abbaye Notre-Dame d''Oelenberg", "description": "Abbey located in Haut-Rhin, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Abtei Oelenberg", "description": "Kloster in Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Abbaye Notre-Dame d''Oelenberg", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Abtei Oelenberg", "description": "Abdij in Reiningue, Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Oelenberg", "description": "Abadía situada en Alto Rin, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Notre-Dame d''Oelenberg", "description": "Abbaye située dans le Haut-Rhin, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Abbaye Notre-Dame d''Oelenberg", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
