    (v_route, 'Schiessrothried', 'Vodní plocha ve Francii — příjemný cíl vyjížďky s výhledy na hladinu.', 48.02972, 7.02528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schiessrothried.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schiessrothried.jpg"}'::text[], 3, '{"en": {"name": "Schiessrothried", "description": "Body of water. A body of water in France — a pleasant ride destination with waterside views."}, "de": {"name": "Schiessrothried-See", "description": "Stausee in den Vogesen. Ein Gewässer in Frankreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Schiessrothried", "description": "Akwen we Francji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Schiessrothried", "description": "Meer in Frankrijk. Een waterpartij in Frankrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Schiessrothried", "description": "Una masa de agua en Francia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Schiessrothried", "description": "Lac du versant alsacien des Vosges. Un plan d''eau en France — une belle destination avec vue sur l''eau."}, "uk": {"name": "Schiessrothried", "description": "Водний об''єкт. Водойма у Франції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Neuf-Brisach', 'Obec v départementu Haut-Rhin v kraji (région) Grand Est. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.01806, 7.52833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Neuf-Brisach%20%28view%20from%20the%20southwest%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Neuf-Brisach%20%28view%20from%20the%20southwest%29.jpg"}'::text[], 4, '{"en": {"name": "Neuf-Brisach", "description": "Commune in Haut-Rhin, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Neuf-Brisach", "description": "Französische Gemeinde im Elsass. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Neuf-Brisach", "description": "Gmina w Alzacji. Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Neuf-Brisach", "description": "Gemeente in Haut-Rhin, Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Neuf-Brisach", "description": "Comuna francesa. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "Neuf-Brisach", "description": "Commune française du département du Haut-Rhin. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Неф-Бризак", "description": "Муніципалітет у департаменті Верхній Рейн, Франція. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Fort de Roppe', 'Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 47.68015, 6.89963, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fort%20de%20Roppe%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fort%20de%20Roppe%20%282%29.jpg"}'::text[], 5, '{"en": {"name": "Fort de Roppe", "description": "Also known as Fort Ney, Belfort, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Fort de Roppe", "description": "Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Fort de Roppe", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Fort de Roppe", "description": "Fort in de regio Belfort, Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Fort de Roppe", "description": "Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "fort de Roppe", "description": "Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Форт Роппе", "description": "Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Belfort Cathedral', 'Památka ve Francii — kus historie přímo u trasy.', 47.63862, 6.86362, 'http://commons.wikimedia.org/wiki/Special:FilePath/2014-09-02%2016-24-37%20cathedrale-st-christ-belfort.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2014-09-02%2016-24-37%20cathedrale-st-christ-belfort.jpg"}'::text[], 6, '{"en": {"name": "Belfort Cathedral", "description": "Cathedral located in Territoire de Belfort, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Kathedrale von Belfort", "description": "Kirchengebäude in Belfort, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Belfort Cathedral", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal Saint-Christophe", "description": "Kathedraal in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Basílica de San Cristóbal", "description": "Catedral situada en Territorio de Belfort, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Christophe de Belfort", "description": "Cathédrale située dans le Territoire de Belfort, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Belfort Cathedral", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb);
