    (v_route, 'RRS Discovery', 'Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 56.45694, -2.96667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Discoveryboat.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Discoveryboat.jpg"}'::text[], 0, '{"en": {"name": "RRS Discovery", "description": "1901 survey vessel. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "RRS Discovery", "description": "Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "RRS Discovery", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "RRS Discovery", "description": "Museum in Dundee, het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "RRS Discovery", "description": "Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "RRS Discovery", "description": "Navire musée britannique. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "RRS Discovery", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'St Andrews Cathedral, Saint Andrews', 'Památka ve Velké Británii — kus historie přímo u trasy.', 56.34003, -2.78775, 'http://commons.wikimedia.org/wiki/Special:FilePath/St.Andrews%20Abbey%20Scotland.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St.Andrews%20Abbey%20Scotland.jpg"}'::text[], 1, '{"en": {"name": "St Andrews Cathedral, Saint Andrews", "description": "Ruined cathedral in Saint Andrews, Scotland. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St Andrews Cathedral", "description": "Kathedrale im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w St Andrews", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St Andrews Cathedral", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de St. Andrews", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Saint Andrews", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Andrews Cathedral, Saint Andrews", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'May', 'Ostrov v zálivu Firth of Forth ve Skotsku. Přírodní zajímavost ve Velké Británii — místo na protažení nohou uprostřed přírody.', 56.18761, -2.55667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Isle%20of%20May%20Stevenson%20Lighthouse.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Isle%20of%20May%20Stevenson%20Lighthouse.jpg"}'::text[], 2, '{"en": {"name": "Isle of May", "description": "Island in the north of the outer Firth of Forth. A natural sight in the United Kingdom — a spot to stretch your legs amid nature."}, "de": {"name": "Isle of May", "description": "Insel im Vereinigten Königreich. Eine Natursehenswürdigkeit in Großbritannien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Isle of May", "description": "Atrakcja przyrodnicza w Wielkiej Brytanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Isle of May", "description": "Eiland van het Verenigd Koninkrijk. Een natuurbezienswaardigheid in het Verenigd Koninkrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "May", "description": "Un paraje natural en el Reino Unido: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "May", "description": "Île britannique. Un site naturel au Royaume-Uni — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "May", "description": "Острів. Природна пам''ятка у Великій Британії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Loch Leven', 'Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 56.19444, -3.375, 'http://commons.wikimedia.org/wiki/Special:FilePath/Loch%20Leven%20Kinross.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Loch%20Leven%20Kinross.jpg"}'::text[], 3, '{"en": {"name": "Loch Leven", "description": "Lake at Kinross, Perth and Kinross, Scotland, UK, outflows to River Leven. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "Loch Leven", "description": "Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Loch Leven", "description": "Jezioro w Szkocji. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Loch Leven", "description": "Perth and Kinross. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Leven", "description": "Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "loch Leven", "description": "Lac au Royaume-Uni. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Лох-Левен", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Loch Leven Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.2008, -3.39179, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lochleven%20Castle%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lochleven%20Castle%2001.jpg"}'::text[], 4, '{"en": {"name": "Loch Leven Castle", "description": "Medieval castle, now ruined, in Loch Leven, Perth and Kinross, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Loch Leven Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Loch Leven Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Lochleven Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Lochleven", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Loch Leven", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Лохлевен", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Scone Palace', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.42261, -3.43814, 'http://commons.wikimedia.org/wiki/Special:FilePath/Scone%20Palace.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Scone%20Palace.jpg"}'::text[], 5, '{"en": {"name": "Scone Palace", "description": "Castle owned by the Earl of Mansfield in Perth and Kinross, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Scone Palace", "description": "Schloss im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Scone Palace", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Scone Palace", "description": "Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Scone", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Scone", "description": "Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Scone Palace", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Glamis', 'Hrad ve skotské správní oblasti Angus. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.6203, -3.0024, 'http://commons.wikimedia.org/wiki/Special:FilePath/Angus%20-%20Glamis%20Castle%20-%202025-09-26%2001-18-20%20001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Angus%20-%20Glamis%20Castle%20-%202025-09-26%2001-18-20%20001.JPG"}'::text[], 6, '{"en": {"name": "Glamis Castle", "description": "Castle in Angus, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Glamis Castle", "description": "Schloss im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Glamis", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Glamis Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Glamis", "description": "Castillo en Glamis, Angus. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Glamis", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Глеміс", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb);
