    (v_route, 'Riverside Museum', 'Muzeum dopravy v Glasgow ve Skotsku. Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 55.86511, -4.30639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Riverside%20Museum%20Glasgow%20EC2018.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Riverside%20Museum%20Glasgow%20EC2018.jpg"}'::text[], 0, '{"en": {"name": "Riverside Museum", "description": "Transport museum in Glasgow, Scotland, United Kingdom. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Riverside Museum", "description": "Verkehrsmuseum in Glasgow, Schottland. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Riverside Museum", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Riverside Museum", "description": "Museum in Glasgow, Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Riverside Museum", "description": "Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Riverside Museum", "description": "Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Riverside Museum", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Katedrála svatého Munga', 'Památka ve Velké Británii — kus historie přímo u trasy.', 55.8631, -4.2346, 'http://commons.wikimedia.org/wiki/Special:FilePath/2018%2007%2019%20Schottland%20%2833%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2018%2007%2019%20Schottland%20%2833%29.jpg"}'::text[], 1, '{"en": {"name": "Glasgow Cathedral", "description": "Church in Glasgow, Scotland, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St. Mungo’s Cathedral", "description": "Kathedrale im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Glasgow", "description": "Zabytkowy kościół w Szkocji. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Glasgow", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Glasgow", "description": "Iglesia en Glasgow, Escocia. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Mungo de Glasgow", "description": "Cathédrale à Glasgow. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Munga", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Antoninův val', 'Obranné opevnění ve Skotsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 55.967, -4.067, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bar%20Hill.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bar%20Hill.jpg"}'::text[], 2, '{"en": {"name": "Antonine Wall", "description": "Defensive fortification in Roman Britain. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Antoninuswall", "description": "Römische Grenzbefestigung. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Wał Antonina", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Muur van Antoninus", "description": "Romeinse limes in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Muro de Antonino", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "mur d''Antonin", "description": "Fortification romaine en Écosse. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Стіна Антонія", "description": "Фортифікаційна споруда Римської імперії в Північній Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Stirling', 'Středověký hrad ve Skotsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.12389, -3.94778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stirlingcastle.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stirlingcastle.jpg"}'::text[], 3, '{"en": {"name": "Stirling Castle", "description": "Castle in Stirling, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Stirling Castle", "description": "Schloss in Schottland. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Stirling", "description": "Zabytek architektury w Szkocji. Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Stirling Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Stirling", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Stirling", "description": "Château écossais. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Стерлінг", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Doune Castle', 'Hrad ve Skotsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 56.18516, -4.05025, 'http://commons.wikimedia.org/wiki/Special:FilePath/Scotland-2016-Aerial-Doune%20Castle%20%28and%20Castle%20keeper%27s%20cottage%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Scotland-2016-Aerial-Doune%20Castle%20%28and%20Castle%20keeper%27s%20cottage%29.jpg"}'::text[], 4, '{"en": {"name": "Doune Castle", "description": "Castle in Stirling, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Doune Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Doune Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Doune Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Doune", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Doune", "description": "Château médiéval situé en Écosse. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Дун", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Loch Lomond', 'Jezero ve Skotsku. Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 56.1482, -4.6515, 'http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20loch%20lomond.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20loch%20lomond.JPG"}'::text[], 5, '{"en": {"name": "Loch Lomond", "description": "Freshwater lake in Scotland, UK. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "Loch Lomond", "description": "See in Schottland. Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Loch Lomond", "description": "Jezioro w Szkocji. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Loch Lomond", "description": "Meer in het Verenigd Koninkrijk. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Loch Lomond", "description": "Lago del oeste de Escocia. Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "loch Lomond", "description": "Lac écossais. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Лох-Ломонд", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Dumbarton Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 55.936, -4.5628, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dumbarton%20Castle%2020090607%20south%20entrance.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dumbarton%20Castle%2020090607%20south%20entrance.jpg"}'::text[], 6, '{"en": {"name": "Dumbarton Castle", "description": "Castle in West Dunbartonshire, Scotland, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Dumbarton Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Dumbarton Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Dumbarton Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Dumbarton", "description": "Fortaleza más antigua de Gran Bretaña. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Dumbarton", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Дамбартон", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb);
