    (v_route, 'Šarganská osmička', 'Technická památka v Srbsku — doly, železnice a stroje, na kterých stojí historie kraje.', 43.8, 19.52194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sarganska%20osmica%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sarganska%20osmica%202.jpg"}'::text[], 0, '{"en": {"name": "Šargan Eight", "description": "Narrow gauge heritage railway in Serbia. A technical monument in Serbia — mines, railways and machines behind the region''s history."}, "de": {"name": "Šarganska osmica", "description": "Schmalspurbahn mit touristischem Museumsbetrieb auf dem Balkan. Ein technisches Denkmal in Serbien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Ósemka Szargańska", "description": "Zabytek techniki w Serbii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Šarganska osmica", "description": "Een technisch monument in Servië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Šarganská osmička", "description": "Un monumento técnico en Serbia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Huit de Šargan", "description": "Un monument technique en Serbie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Шарганська вісімка", "description": "Вузькоколійна залізниця. Технічна пам''ятка в Сербії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Zaovinské jezero', 'Vodní plocha v Srbsku — příjemný cíl vyjížďky s výhledy na hladinu.', 43.87, 19.4, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jezero%20Zaovine1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jezero%20Zaovine1.jpg"}'::text[], 1, '{"en": {"name": "Zaovine Lake", "description": "Body of water. A body of water in Serbia — a pleasant ride destination with waterside views."}, "de": {"name": "Zaovinské jezero", "description": "Ein Gewässer in Serbien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zaovinské jezero", "description": "Akwen w Serbii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Zaovinsko jezero", "description": "Meer in Servië. Een waterpartij in Servië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Zaovinské jezero", "description": "Una masa de agua en Serbia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Zaovine", "description": "Un plan d''eau en Serbie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Zaovinské jezero", "description": "Водний об''єкт. Водойма в Сербії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Národní park Tara', 'Národní park v Srbsku. Přírodní zajímavost v Srbsku — místo na protažení nohou uprostřed přírody.', 43.9067, 19.305, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tarski%20pejza%C5%BE%2C%20jezero%20Spaji%C4%87i%2C%20Nacionalni%20park%20Tara.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tarski%20pejza%C5%BE%2C%20jezero%20Spaji%C4%87i%2C%20Nacionalni%20park%20Tara.jpg"}'::text[], 2, '{"en": {"name": "Tara National Park", "description": "National park in Serbia. A natural sight in Serbia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Tara", "description": "Nationalpark in Serbien. Eine Natursehenswürdigkeit in Serbien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Tara", "description": "Atrakcja przyrodnicza w Serbii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Tara", "description": "Berg in Servië. Een natuurbezienswaardigheid in Servië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Tara", "description": "Un paraje natural en Serbia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Tara", "description": "Massif montagneux à l''ouest de la Serbie. Un site naturel en Serbie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Národní park Tara", "description": "Природна пам''ятка в Сербії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Rača monastery', 'Památka v Srbsku — kus historie přímo u trasy.', 43.93083, 19.54083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Ra%C4%8Da1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Ra%C4%8Da1.jpg"}'::text[], 3, '{"en": {"name": "Rača monastery", "description": "Monastery. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Rača monastery", "description": "Kloster in Serbien. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Monaster Rača", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Manastir Rača", "description": "Klooster in Servië. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Rača", "description": "Monasterio ortodoxo serbio. Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Rača", "description": "Monastère orthodoxe serbe. Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Rača monastery", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Stari Grad', 'Pevnost u Užice. Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 43.852, 19.829, 'http://commons.wikimedia.org/wiki/Special:FilePath/Srednjevekovni%20grad%20U%C5%BEice%20-%20pogled%20sa%20Zabu%C4%8Dja.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Srednjevekovni%20grad%20U%C5%BEice%20-%20pogled%20sa%20Zabu%C4%8Dja.jpg"}'::text[], 4, '{"en": {"name": "Stari Grad", "description": "Old fortress in Užice. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Festung Užice", "description": "Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Stari Grad", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Uzjički Grad", "description": "Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Stari Grad", "description": "Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse d''Užice", "description": "Monument culturel serbe. Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Stari Grad", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Potpeće cave', 'Přírodní zajímavost v Srbsku — místo na protažení nohou uprostřed přírody.', 43.7839, 19.9372, 'http://commons.wikimedia.org/wiki/Special:FilePath/Potpe%C4%87e%20cave%2C%20Serbia%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Potpe%C4%87e%20cave%2C%20Serbia%2001.jpg"}'::text[], 5, '{"en": {"name": "Potpeće cave", "description": "Spring cave with a large entrance portal with a characteristic appearance. A natural sight in Serbia — a spot to stretch your legs amid nature."}, "de": {"name": "Potpeće cave", "description": "Höhle in Serbien. Eine Natursehenswürdigkeit in Serbien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Potpeće cave", "description": "Jaskinia turystyczna (Serbia, Serbia). Atrakcja przyrodnicza w Serbii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Drežnička Gradina", "description": "Berg in Servië. Een natuurbezienswaardigheid in Servië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Potpeće cave", "description": "Un paraje natural en Serbia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Potpeće cave", "description": "Un site naturel en Serbie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Potpeće cave", "description": "Природна пам''ятка в Сербії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Stopića Cave', 'Přírodní zajímavost v Srbsku — místo na protažení nohou uprostřed přírody.', 43.70222, 19.855, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stopica%20cave2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stopica%20cave2.jpg"}'::text[], 6, '{"en": {"name": "Stopića Cave", "description": "Cave in Serbia. A natural sight in Serbia — a spot to stretch your legs amid nature."}, "de": {"name": "Stopića Cave", "description": "Eine Natursehenswürdigkeit in Serbien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Stopića Cave", "description": "Atrakcja przyrodnicza w Serbii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Stopića pećina", "description": "Een natuurbezienswaardigheid in Servië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Stopića", "description": "Cueva de Serbia. Un paraje natural en Serbia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Stopića Cave", "description": "Un site naturel en Serbie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Стопича", "description": "Природна пам''ятка в Сербії — місце розім''яти ноги серед природи."}}'::jsonb);
