    (v_route, 'Trepča', 'Technická památka v Srbsku — doly, železnice a stroje, na kterých stojí historie kraje.', 42.62, 21.428, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mineralet%20e%20Trep%C3%A7%C3%ABs%20Milot%20Krasniqi2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mineralet%20e%20Trep%C3%A7%C3%ABs%20Milot%20Krasniqi2.jpg"}'::text[], 0, '{"en": {"name": "Trepča Mines", "description": "Mine. A technical monument in Serbia — mines, railways and machines behind the region''s history."}, "de": {"name": "Trepca", "description": "Ehemaliges Industriekombinat und Flüchtlingslager im Kosovo. Ein technisches Denkmal in Serbien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Trepça", "description": "Zabytek techniki w Serbii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Trepča", "description": "Mijn in Kosovo. Een technisch monument in Servië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Trepča", "description": "Antiguo complejo industrial en Kosovska Mitrovica, Kosovo. Un monumento técnico en Serbia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "mine Trepča", "description": "Un monument technique en Serbie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Трепча", "description": "Великий промисловий комплекс в Косово. Технічна пам''ятка в Сербії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Prilepac', 'Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 42.54014, 21.52116, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tabla%20u%20Prilepcu.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tabla%20u%20Prilepcu.jpg"}'::text[], 1, '{"en": {"name": "Prilepac", "description": "Serbian fortress. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Prilepac", "description": "Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Prilepac", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Prilepac", "description": "Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Prilepac", "description": "Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "Prilepac", "description": "Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Prilepac", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Ubožac Monastery', 'Památka v Srbsku — kus historie přímo u trasy.', 42.5868, 21.5937, 'http://commons.wikimedia.org/wiki/Special:FilePath/Manastiri%20R%C3%ABgjavc%20-%20Mo%C3%A7ar%C3%AB%2C%20Kamenic%C3%AB%20%28perpara%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Manastiri%20R%C3%ABgjavc%20-%20Mo%C3%A7ar%C3%AB%2C%20Kamenic%C3%AB%20%28perpara%29.JPG"}'::text[], 2, '{"en": {"name": "Ubožac Monastery", "description": "Orthodox Monastery. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Ubožac Monastery", "description": "Kloster in Serbien. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Ubožac Monastery", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Manastir Ubozjac", "description": "Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Ubožac Monastery", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère d''Ubožac", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Ubožac Monastery", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Holy Trinity Church, Vranje', 'Památka v Srbsku — kus historie přímo u trasy.', 42.55178, 21.90008, 'http://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B0%D0%B1%D0%BE%D1%80%D0%BD%D0%B0%20%D1%86%D1%80%D0%BA%D0%B2%D0%B0%20%D1%83%20%D0%92%D1%80%D0%B0%D1%9A%D1%83.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B0%D0%B1%D0%BE%D1%80%D0%BD%D0%B0%20%D1%86%D1%80%D0%BA%D0%B2%D0%B0%20%D1%83%20%D0%92%D1%80%D0%B0%D1%9A%D1%83.JPG"}'::text[], 3, '{"en": {"name": "Holy Trinity Church, Vranje", "description": "A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Holy Trinity Church, Vranje", "description": "Kirche in Serbien. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Holy Trinity Church, Vranje", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Holy Trinity Church, Vranje", "description": "Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Holy Trinity Church, Vranje", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de la Sainte-Trinité de Vranje", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Holy Trinity Church, Vranje", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Batlavské jezero', 'Vodní plocha v Srbsku — příjemný cíl vyjížďky s výhledy na hladinu.', 42.82111, 21.30778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Four%20colors%20-%20Lake%20Batllava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Four%20colors%20-%20Lake%20Batllava.jpg"}'::text[], 4, '{"en": {"name": "Batllava Lake", "description": "Lake. A body of water in Serbia — a pleasant ride destination with waterside views."}, "de": {"name": "Batllava-See", "description": "Stausee in Podujeva, Kosovo. Ein Gewässer in Serbien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Batllavë", "description": "Jezioro w Serbii. Akwen w Serbii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Batlavsko jezero", "description": "Meer in Servië. Een waterpartij in Servië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Batlavské jezero", "description": "Una masa de agua en Serbia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Batlava", "description": "Un plan d''eau en Serbie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Batlavské jezero", "description": "Озеро. Водойма в Сербії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Chrám Krista Spasitele', 'Kostel v Prištině. Památka v Srbsku — kus historie přímo u trasy.', 42.6585, 21.1636, 'http://commons.wikimedia.org/wiki/Special:FilePath/Serbian%20Ortodox%20Christ%20the%20Savior%20Cathedral%20-%20Outside%20-%20Pristina%202012%20-%202%20%28cropped%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Serbian%20Ortodox%20Christ%20the%20Savior%20Cathedral%20-%20Outside%20-%20Pristina%202012%20-%202%20%28cropped%29.JPG"}'::text[], 5, '{"en": {"name": "Christ the Saviour Cathedral", "description": "Unfinished Serbian Orthodox Christian church in Pristina, Kosovo. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Christ-Erlöser-Kirche", "description": "Unvollendete serbisch-orthodoxe Kathedrale in Pristina, Kosovo. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sobór Chrystusa Zbawiciela w Prisztinie", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Chrám Krista Spasitele", "description": "Kathedraal in Pristina, Kosovo. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia de Cristo Salvador", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Chrám Krista Spasitele", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Chrám Krista Spasitele", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter Gračanica', 'Památka v Srbsku — kus historie přímo u trasy.', 42.59833, 21.19333, 'http://commons.wikimedia.org/wiki/Special:FilePath/%D0%9C%D0%B0%D0%BD%D0%B0%D1%81%D1%82%D0%B8%D1%80%20%D0%93%D1%80%D0%B0%D1%87%D0%B0%D0%BD%D0%B8%D1%86%D0%B0%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%D0%9C%D0%B0%D0%BD%D0%B0%D1%81%D1%82%D0%B8%D1%80%20%D0%93%D1%80%D0%B0%D1%87%D0%B0%D0%BD%D0%B8%D1%86%D0%B0%202.jpg"}'::text[], 6, '{"en": {"name": "Gračanica monastery", "description": "Cultural heritage monument of Kosovo. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Kloster Gračanica", "description": "Mittelalterliches serbisch-orthodoxes Kloster im Kosovo. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Monaster Gračanica", "description": "Świątynia prawosławna. Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster Gračanica", "description": "Klooster in Servië. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Gračanica", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Gračanica", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Монастир Грачаніца", "description": "Пам''ятка культурної спадщини в Косові. Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb);
