  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Viking Ship Museum', 'Technická památka v Dánsku — doly, železnice a stroje, na kterých stojí historie kraje.', 55.65014, 12.07894, 'http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Viking%20Ship%20Museum%20from%20Roskilde%20Fjord.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Viking%20Ship%20Museum%20from%20Roskilde%20Fjord.jpg"}'::text[], 0, '{"en": {"name": "Viking Ship Museum", "description": "Maritime history museum, archaeological museum in Roskilde, Denmark. A technical monument in Denmark — mines, railways and machines behind the region''s history."}, "de": {"name": "Wikingerschiffsmuseum Roskilde", "description": "Museum zur Archäologie und Schifffahrtsgeschichte in Roskilde, Dänemark. Ein technisches Denkmal in Dänemark — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Muzeum Łodzi Wikingów w Roskilde", "description": "Muzeum morskie w Danii. Zabytek techniki w Danii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Vikingschipmuseum", "description": "Museum in Denemarken. Een technisch monument in Denemarken — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo de barcos vikingos de Roskilde", "description": "Museo de historia marítima y arqueológica de Roskilde. Un monumento técnico en Dinamarca: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "musée des navires vikings de Roskilde", "description": "Musée danois. Un monument technique au Danemark — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Музей кораблів вікінгів (Роскілле)", "description": "Технічна пам''ятка в Данії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Katedrála v Roskilde', 'Památka v Dánsku — kus historie přímo u trasy.', 55.64267, 12.08031, 'http://commons.wikimedia.org/wiki/Special:FilePath/Roskilde%20Cathedral%20aerial%20crop.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Roskilde%20Cathedral%20aerial%20crop.jpg"}'::text[], 1, '{"en": {"name": "Roskilde Cathedral", "description": "Cathedral in Denmark (Church of Denmark). A heritage sight in Denmark — a piece of history right on your route."}, "de": {"name": "Dom zu Roskilde", "description": "Kirchengebäude in Dänemark. Ein Denkmal in Dänemark — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "katedra w Roskilde", "description": "Katedra w Danii. Zabytek w Danii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Roskilde", "description": "Kathedraal in Denemarken. Een monument in Denemarken — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Roskilde", "description": "Un monumento en Dinamarca: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Roskilde", "description": "Bâtiment de Danemark. Un monument au Danemark — un morceau d''histoire au bord de la route."}, "uk": {"name": "Роскілльський собор", "description": "Кафедральний собор в Роскіллє, Данія. Пам''ятка в Данії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kostel Panny Marie', 'Kodaňská katedrála a Národní katedrála Dánska. Památka v Dánsku — kus historie přímo u trasy.', 55.67933, 12.5725, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rundet%C3%A5rn%20view%202%20new%20version.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rundet%C3%A5rn%20view%202%20new%20version.jpg"}'::text[], 2, '{"en": {"name": "Church of Our Lady", "description": "Cathedral of Copenhagen and the National Cathedral of Denmark. A heritage sight in Denmark — a piece of history right on your route."}, "de": {"name": "Frauenkirche", "description": "Kirchengebäude in Kopenhagen. Ein Denkmal in Dänemark — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Marii Panny w Kopenhadze", "description": "Zabytek w Danii — kawałek historii tuż przy trasie."}, "nl": {"name": "Onze-Lieve-Vrouwekerk", "description": "Kerkgebouw in Kopenhagen, Denemarken. Een monument in Denemarken — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora de Copenhague", "description": "Un monumento en Dinamarca: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Copenhague", "description": "Église de la commune de Copenhague, Danemark. Un monument au Danemark — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kostel Panny Marie", "description": "Пам''ятка в Данії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Rundetaarn', 'Věž ze 17. století v centu Kodaně. Rozhledna v Dánsku — výhled do kraje jako odměna za zastávku.', 55.68137, 12.57579, 'http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20-%20Rundet%C3%A5rn%20-%202013.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20-%20Rundet%C3%A5rn%20-%202013.jpg"}'::text[], 3, '{"en": {"name": "Rundetaarn", "description": "17th-century tower located in central Copenhagen, Denmark. A lookout tower in Denmark — sweeping views as a reward for stopping."}, "de": {"name": "Rundetaarn", "description": "Museum in Dänemark. Ein Aussichtsturm in Dänemark — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Rundetaarn", "description": "Wieża widokowa w Danii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Rundetaarn", "description": "Bouwwerk in Kopenhagen. Een uitkijktoren in Denemarken — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rundetårn", "description": "Torre del siglo XVII en Dinamarca. Un mirador en Dinamarca: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rundetårn", "description": "Tour du XVIIe siècle située dans le centre de Copenhague, au Danemark. Une tour panoramique au Danemark — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Кругла вежа", "description": "Оглядова вежа в Данії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Kastellet', 'Hrad či zámek v Dánsku — historická zastávka, která stojí za odbočku.', 55.69161, 12.59357, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kastellet%20aerial.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kastellet%20aerial.jpg"}'::text[], 4, '{"en": {"name": "Kastellet", "description": "Star fort in Copenhagen. A castle in Denmark — a historic stop worth the detour."}, "de": {"name": "Kastell von Kopenhagen", "description": "Zitadelle in Dänemark. Eine Burg bzw. ein Schloss in Dänemark — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Kastellet", "description": "Fort gwiaździsty w Kopenhadze. Zamek w Danii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kastellet", "description": "Vestingwerk in Kopenhagen. Een kasteel in Denemarken — een historische stop die de omweg waard is."}, "es": {"name": "Kastellet", "description": "Fuerte  en Copenhague. Un castillo en Dinamarca: una parada histórica que merece el desvío."}, "fr": {"name": "Kastellet", "description": "Bâtiment de la commune de Copenhague, au Danemark. Un château au Danemark — une halte historique qui vaut le détour."}, "uk": {"name": "Kastellet", "description": "Замок в Данії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Frederiksborg', 'Hrad či zámek v Dánsku — historická zastávka, která stojí za odbočku.', 55.935, 12.30083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Frederiksborg%20Slot%20i%20sol.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Frederiksborg%20Slot%20i%20sol.jpg"}'::text[], 5, '{"en": {"name": "Frederiksborg Palace", "description": "Castle in Hillerød, Denmark. A castle in Denmark — a historic stop worth the detour."}, "de": {"name": "Schloss Frederiksborg", "description": "Schloss in Dänemark. Eine Burg bzw. ein Schloss in Dänemark — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Frederiksborg", "description": "Zamek w Danii. Zamek w Danii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot Frederiksborg", "description": "Museum in Denemarken. Een kasteel in Denemarken — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Frederiksborg", "description": "Palacio de Hillerød, Dinamarca. Un castillo en Dinamarca: una parada histórica que merece el desvío."}, "fr": {"name": "château de Frederiksborg", "description": "Bâtiment de municipalité de Hillerød, Danemark. Un château au Danemark — une halte historique qui vaut le détour."}, "uk": {"name": "Фредеріксборг", "description": "Замок в Данії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Arresø', 'Vodní plocha v Dánsku — příjemný cíl vyjížďky s výhledy na hladinu.', 55.97472, 12.10417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Arres%C3%B8%2C%20north%20Zealand.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Arres%C3%B8%2C%20north%20Zealand.jpg"}'::text[], 6, '{"en": {"name": "Arresø", "description": "Lake in Halsnæs Municipality, Capital Region of Denmark, Denmark. A body of water in Denmark — a pleasant ride destination with waterside views."}, "de": {"name": "Arresø", "description": "Ein Gewässer in Dänemark — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Arresø", "description": "Jezioro w Danii. Akwen w Danii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Arresø", "description": "Meer in Denemarken. Een waterpartij in Denemarken — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Arresø", "description": "Una masa de agua en Dinamarca: un destino agradable con vistas al agua."}, "fr": {"name": "Arresø", "description": "Lac danois. Un plan d''eau au Danemark — une belle destination avec vue sur l''eau."}, "uk": {"name": "Арресьо", "description": "Водойма в Данії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
