    (v_route, 'ORP Błyskawica', 'Polský torpédoborec třídy Grom. Technická památka v Polsku — doly, železnice a stroje, na kterých stojí historie kraje.', 54.51955, 18.55121, 'http://commons.wikimedia.org/wiki/Special:FilePath/Blyskawica%20l%20d.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Blyskawica%20l%20d.jpg"}'::text[], 0, '{"en": {"name": "ORP Błyskawica", "description": "1936 Grom-class destroyer. A technical monument in Poland — mines, railways and machines behind the region''s history."}, "de": {"name": "ORP Błyskawica", "description": "Polnischer Zerstörer der Grom-Klasse. Ein technisches Denkmal in Polen — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "ORP Błyskawica", "description": "Polski niszczyciel z okresu II wojny światowej, obecnie okręt muzeum. Zabytek techniki w Polsce — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "ORP Błyskawica", "description": "Poolse torpedobootjager (1937–1976). Een technisch monument in Polen — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "ORP Błyskawica", "description": "Destructor de 1937 de la Armada de la República de Polonia. Un monumento técnico en Polonia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "ORP Błyskawica", "description": "Un monument technique en Pologne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "ORP Błyskawica", "description": "Ескадрений міноносець «Блискавка». Технічна пам''ятка у Польщі — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Maják v Sopotech', 'Maják a rozhledna, Sopoty, Polsko. Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 54.44531, 18.57039, 'http://commons.wikimedia.org/wiki/Special:FilePath/Latarnia%20morska%20w%20Sopocie%202012%2011%2007.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Latarnia%20morska%20w%20Sopocie%202012%2011%2007.jpg"}'::text[], 1, '{"en": {"name": "Lighthouse in Sopot", "description": "Lighthouse in Poland. A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Maják v Sopotech", "description": "Leuchtturm in Polen. Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Latarnia Morska Sopot", "description": "Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Maják v Sopotech", "description": "Vuurtoren in Polen. Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Maják v Sopotech", "description": "Faro situado en Polonia. Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "phare de Sopot", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Maják v Sopotech", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 54.41111, 18.55778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oliwa%20kathedraal.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oliwa%20kathedraal.jpg"}'::text[], 2, '{"en": {"name": "Oliwa Cathedral", "description": "Cathedral. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Dom zu Oliva", "description": "Kirchengebäude in Danzig. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna Trójcy Świętej w Gdańsku-Oliwie", "description": "Rzymskokatolicki kościół archikatedralny. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Oliwa", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Oliwa", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Gdańsk-Oliwa", "description": "Église polonaise. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святої Трійці, Пресвятої Богородиці та святого Бернара", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Abbot''s Palace (Oliwa)', 'Památka v Polsku — kus historie přímo u trasy.', 54.41083, 18.56028, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gdansk%20Cystersow11.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gdansk%20Cystersow11.jpg"}'::text[], 3, '{"en": {"name": "Abbot''s Palace (Oliwa)", "description": "Building. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Äbtepalast zu Oliva", "description": "Schloss in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Pałac Opatów w Oliwie", "description": "Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Abtpaleis Oliwa", "description": "Gebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Abbot''s Palace (Oliwa)", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "palais des Abbés d''Oliwa", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Abbot''s Palace (Oliwa)", "description": "Будівля. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Wisłoujście Fortress', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 54.39476, 18.68086, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gdansk%20Wis%C5%82ouj%C5%9Bcie%20Fortress%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gdansk%20Wis%C5%82ouj%C5%9Bcie%20Fortress%201.jpg"}'::text[], 4, '{"en": {"name": "Wisłoujście Fortress", "description": "Lighthouse in Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Festung Weichselmünde", "description": "Festung und Leuchtturm in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Wisłoujście", "description": "Zabytek w Gdańsku. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Wisłoujście Fortress", "description": "Vesting in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Wisłoujście Fortress", "description": "Faro situado en Polonia. Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Wisłoujście", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Фортеця Віслоуйсьце", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Green Gate', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 54.34794, 18.65573, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gda%C5%84sk%2C%20Brama%20Zielona%20%28WLZ14%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gda%C5%84sk%2C%20Brama%20Zielona%20%28WLZ14%29.JPG"}'::text[], 5, '{"en": {"name": "Green Gate", "description": "Old watergate in Gdańsk, Poland; one of the city''s most notable tourist attractions. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Grünes Tor", "description": "Gebäude in Danzig in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Brama Zielona", "description": "Najstarsza brama wodna w Gdańsku. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Groene Poort", "description": "Stadspoort in Gdańsk, Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Green Gate", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "porte Verte", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Green Gate", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'High Gate in Gdańsk', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 54.34992, 18.64652, 'http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20Alta%2C%20Gdansk%2C%20Polonia%2C%202013-05-20%2C%20DD%2004.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20Alta%2C%20Gdansk%2C%20Polonia%2C%202013-05-20%2C%20DD%2004.jpg"}'::text[], 6, '{"en": {"name": "High Gate in Gdańsk", "description": "City gate of Gdańsk, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Hohes Tor (Danzig)", "description": "Stadttor in Danzig. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Brama Wyżynna w Gdańsku", "description": "Renesansowa brama miejska w Gdańsku. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hoge Poort", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "High Gate in Gdańsk", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "porte Haute", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "High Gate in Gdańsk", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb);
