    (v_route, 'Gliwice Radio Tower', 'Technická památka v Polsku — doly, železnice a stroje, na kterých stojí historie kraje.', 50.31336, 18.68878, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gliwice%20Radiostacja%20DSC%209386.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gliwice%20Radiostacja%20DSC%209386.jpg"}'::text[], 0, '{"en": {"name": "Gliwice Radio Tower", "description": "Transmission station in the Szobiszowice district of Gliwice, Upper Silesia, Poland. A technical monument in Poland — mines, railways and machines behind the region''s history."}, "de": {"name": "Sender Gleiwitz", "description": "Ehemaliger Rundfunksender. Ein technisches Denkmal in Polen — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Radiostacja gliwicka", "description": "Zespół radiostacji w Gliwicach. Zabytek techniki w Polsce — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Gliwice radiotoren", "description": "Stalen vakwerktoren in Gliwice, Polen. Een technisch monument in Polen — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Torre de radio de Gliwice", "description": "Un monumento técnico en Polonia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "tour hertzienne de Gliwice", "description": "Tour de transmission en bois, en Pologne. Un monument technique en Pologne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Gliwice Radio Tower", "description": "Технічна пам''ятка у Польщі — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
