    (v_route, 'Katedrála svatých Petra a Pavla v Hlivicích', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 50.29127, 18.66551, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gliwice%2C%20katedra%20%C5%9Awi%C4%99tych%20Aposto%C5%82%C3%B3w%20Piotra%20i%20Paw%C5%82a%20w%20Gliwicach%2C%20KsP.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gliwice%2C%20katedra%20%C5%9Awi%C4%99tych%20Aposto%C5%82%C3%B3w%20Piotra%20i%20Paw%C5%82a%20w%20Gliwicach%2C%20KsP.jpg"}'::text[], 2, '{"en": {"name": "Gliwice Cathedral", "description": "Cathedrale in Gliwice. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kathedrale St. Peter und Paul", "description": "Kirchengebäude in Gliwice. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "katedra Świętych Apostołów Piotra i Pawła w Gliwicach", "description": "Świątynia katolicka. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Katedrála svatých Petra a Pavla v Hlivicích", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Pedro y San Pablo", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Katedrála svatých Petra a Pavla v Hlivicích", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatých Petra a Pavla v Hlivicích", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
