    (v_route, 'SS Nomadic', 'Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 54.60637, -5.91115, 'http://commons.wikimedia.org/wiki/Special:FilePath/IMO%205516111%20SS%20Nomadic%2C%201911%2020180914%20113426%20%2846770595105%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/IMO%205516111%20SS%20Nomadic%2C%201911%2020180914%20113426%20%2846770595105%29.jpg"}'::text[], 0, '{"en": {"name": "SS Nomadic", "description": "1911 ship''s tender. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "Nomadic", "description": "Britisches Schiff. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "SS Nomadic", "description": "Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "SS Nomadic", "description": "Schip in het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "SS Nomadic", "description": "Transbordador del RMS Titanic y del RMS Olympic y único buque de la White Star Line conservado en la actualidad. Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Nomadic", "description": "Navire musée britannique. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "SS Nomadic", "description": "Великобританське судно. Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'St Anne''s Cathedral, Belfast', 'Památka ve Velké Británii — kus historie přímo u trasy.', 54.6027, -5.92884, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20St.%20Anne%20Belfast.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20St.%20Anne%20Belfast.jpg"}'::text[], 1, '{"en": {"name": "St Anne''s Cathedral, Belfast", "description": "Church building in Belfast, County Antrim, Northern Ireland. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St Anne''s Cathedral, Belfast", "description": "Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Anny w Belfaście", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St Anne''s Cathedral, Belfast", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santa Ana", "description": "Catedral anglicana en Belfast, Irlanda del Norte. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Anne de Belfast", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Anne''s Cathedral, Belfast", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'St Peter''s Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 54.599, -5.94448, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20petersbelfast-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20petersbelfast-2.jpg"}'::text[], 2, '{"en": {"name": "St Peter''s Cathedral", "description": "Roman Catholic cathedral church for the Diocese of Down and Connor in Northern Ireland. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale St. Peter", "description": "Kirchengebäude in Belfast. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Piotra w Belfaście", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St Peter''s Cathedral", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Pedro (Belfast)", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Pierre de Belfast", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Peter''s Cathedral", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Belfastský zámek', 'Zámek v Severním Irsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 54.6427, -5.94232, 'http://commons.wikimedia.org/wiki/Special:FilePath/Belfast%20Castle%2C%20Antrim%20Road%20Belfast.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Belfast%20Castle%2C%20Antrim%20Road%20Belfast.jpg"}'::text[], 3, '{"en": {"name": "Belfast Castle", "description": "Mansion in Cavehill country Park, Belfast, Northern Ireland. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Belfast Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Belfaście", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Belfast Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Belfast", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "Belfastský zámek", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Белфаст", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Hrad Carrickfergus', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 54.7133, -5.80645, 'http://commons.wikimedia.org/wiki/Special:FilePath/Carrickfergus%20Castle%2C%20reflections%20at%20sunset%20-%20geograph.org.uk%20-%201098306.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Carrickfergus%20Castle%2C%20reflections%20at%20sunset%20-%20geograph.org.uk%20-%201098306.jpg"}'::text[], 4, '{"en": {"name": "Carrickfergus Castle", "description": "Irish castle. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Carrickfergus Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Hrad Carrickfergus", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Carrickfergus Castle", "description": "Kasteel in Carrickfergus, Noord-Ierland. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Carrickfergus", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Carrickfergus", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Каррікфергус", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'zámek Hillsborough', 'Zámek v Severním Irsku. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 54.4612, -6.08609, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hillsborough%20Castle.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hillsborough%20Castle.jpg"}'::text[], 5, '{"en": {"name": "Hillsborough Castle", "description": "Castle in Royal Hillsborough, County Down, Northern Ireland. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Hillsborough Castle", "description": "Georgianisches Herrenhaus, königliche Residenz und Amtssitz. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Hillsborough", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hillsborough Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Hillsborough", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Hillsborough", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Гіллсборо", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Lough Neagh', 'Jezero na severu Irska. Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 54.61833, -6.39528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ducks%20on%20Lough%20Neagh%20-%20geograph.org.uk%20-%20267285.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ducks%20on%20Lough%20Neagh%20-%20geograph.org.uk%20-%20267285.jpg"}'::text[], 6, '{"en": {"name": "Lough Neagh", "description": "Large lake in Northern Ireland. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "Lough Neagh", "description": "Größter See der Britischen Inseln. Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lough Neagh", "description": "Duże jezioro w Irlandii Północnej. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lough Neagh", "description": "Meer in het Verenigd Koninkrijk. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Neagh", "description": "Lago de Irlanda del Norte (Reino Unido). Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "Lough Neagh", "description": "Lac britannique. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Лох-Ней", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
