  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Dampfbahn Furka-Bergstrecke', 'Technická památka ve Švýcarsku — doly, železnice a stroje, na kterých stojí historie kraje.', 46.56139, 8.36194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Furka-Bergstrecke%20Steinstafel%202006.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Furka-Bergstrecke%20Steinstafel%202006.JPG"}'::text[], 0, '{"en": {"name": "Furka Cogwheel Steam Railway", "description": "Railway line in Switzerland. A technical monument in Switzerland — mines, railways and machines behind the region''s history."}, "de": {"name": "Dampfbahn Furka-Bergstrecke", "description": "Bahnstrecke in der Schweiz, die ihre Bedeutung durch den Furka-Basistunnel verlor und seitdem als Museumsbahn betrieben wird. Ein technisches Denkmal in der Schweiz — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Dampfbahn Furka-Bergstrecke", "description": "Szwajcarska muzealna zębata kolej wąskotorowa. Zabytek techniki w Szwajcarii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Dampfbahn Furka-Bergstrecke", "description": "Spoorlijn in Zwitserland. Een technisch monument in Zwitserland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Dampfbahn Furka-Bergstrecke", "description": "Un monumento técnico en Suiza: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "ligne sommitale de la Furka", "description": "Ligne de chemin de fer suisse. Un monument technique en Suisse — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Парова зубчаста залізниця Фурка", "description": "Технічна пам''ятка у Швейцарії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Reichenbašské vodopády', 'Soubor několika vodopádů na říčce Reichenbach. Přírodní zajímavost ve Švýcarsku — místo na protažení nohou uprostřed přírody.', 46.71361, 8.18306, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schattenhalb%20Reichenbachfall%207-05-2024%2010-56-28.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schattenhalb%20Reichenbachfall%207-05-2024%2010-56-28.jpg"}'::text[], 1, '{"en": {"name": "Reichenbach Falls", "description": "Waterfall in Switzerland that is famous for featuring in the fictitious life of Sherlock Holmes. A natural sight in Switzerland — a spot to stretch your legs amid nature."}, "de": {"name": "Reichenbachfall", "description": "Wasserfall in der Schweiz. Eine Natursehenswürdigkeit in der Schweiz — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Wodospad Reichenbach", "description": "Atrakcja przyrodnicza w Szwajcarii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Reichenbachwaterval", "description": "Een natuurbezienswaardigheid in Zwitserland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cataratas de Reichenbach", "description": "Serie de cascadas en los Alpes suizos. Un paraje natural en Suiza: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "chutes du Reichenbach", "description": "Chutes d''eau suisses. Un site naturel en Suisse — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Райхенбахський водоспад", "description": "Природна пам''ятка у Швейцарії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Sarnersee', 'Jezero v kantonu Obwalden ve Švýcarsku. Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.8625, 8.20861, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Sarnen%20%28view%20from%20the%20southwest%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Sarnen%20%28view%20from%20the%20southwest%29.jpg"}'::text[], 2, '{"en": {"name": "Lake Sarnen", "description": "Lake in at Sarnen, canton of Obwalden, Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Sarnersee", "description": "See in der Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Sarnersee", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Sarnermeer", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Sarnen", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Sarnen", "description": "Lac en Suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Зарнензе", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Brienzské jezero', 'Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.71667, 7.95, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Brienz%20%28view%20from%20the%20southwest%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Brienz%20%28view%20from%20the%20southwest%29.jpg"}'::text[], 3, '{"en": {"name": "Lake Brienz", "description": "Lake in the Berne Canton, Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Brienzersee", "description": "See im Berner Oberland zwischen Interlaken und Brienz, Kanton Bern, Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Brienz", "description": "Jezioro w Szwajcarii. Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Brienz", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Brienz", "description": "Lago en el cantón de Berna, Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Brienz", "description": "Lac de Suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Брієнцьке озеро", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Staubbach Falls', 'Přírodní zajímavost ve Švýcarsku — místo na protažení nohou uprostřed přírody.', 46.58965, 7.90551, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lauterbrunnen%20Staubbach.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lauterbrunnen%20Staubbach.jpg"}'::text[], 4, '{"en": {"name": "Staubbach Falls", "description": "Waterfall in Switzerland. A natural sight in Switzerland — a spot to stretch your legs amid nature."}, "de": {"name": "Staubbachfall", "description": "Wasserfall in der Schweiz. Eine Natursehenswürdigkeit in der Schweiz — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Staubbachfall", "description": "Atrakcja przyrodnicza w Szwajcarii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Staubbachwaterval", "description": "Een natuurbezienswaardigheid in Zwitserland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Staubbachfall", "description": "Un paraje natural en Suiza: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "chute du Staubbach", "description": "Chute d''eau en Suisse. Un site naturel en Suisse — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Водоспад Штауббах", "description": "Водоспад у Швейцарії. Природна пам''ятка у Швейцарії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Trümmelbach Falls', 'Přírodní zajímavost ve Švýcarsku — místo na protažení nohou uprostřed přírody.', 46.56907, 7.91498, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tr%C3%BCmmelbachf%C3%A4lle%20im%20Lauterbrunnental%2029.07.2009%2009-43-56.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tr%C3%BCmmelbachf%C3%A4lle%20im%20Lauterbrunnental%2029.07.2009%2009-43-56.JPG"}'::text[], 5, '{"en": {"name": "Trümmelbach Falls", "description": "Waterfalls in Switzerland. A natural sight in Switzerland — a spot to stretch your legs amid nature."}, "de": {"name": "Trümmelbachfälle", "description": "Wasserfall in der Schweiz. Eine Natursehenswürdigkeit in der Schweiz — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Trümmelbach", "description": "Atrakcja przyrodnicza w Szwajcarii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Trümmelbachwaterval", "description": "Een natuurbezienswaardigheid in Zwitserland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Trummelbach", "description": "Cascadas suizas. Un paraje natural en Suiza: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Trümmelbachfälle", "description": "Un site naturel en Suisse — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Водоспад Трюммельбах", "description": "Водоспад у Швейцарії. Природна пам''ятка у Швейцарії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Tomasee', 'Jezero ve Švýcarsku. Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.6325, 8.67222, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lai%20da%20Tuma%2CTumalake%20on%202%2C345%20metres.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lai%20da%20Tuma%2CTumalake%20on%202%2C345%20metres.JPG"}'::text[], 6, '{"en": {"name": "Tomasee", "description": "Lake in Graubünden, Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Tomasee", "description": "See im schweizerischen Kanton Graubünden. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Tomasee", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Tomasee", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Tomasee", "description": "Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Toma", "description": "Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Tomasee", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
