    (v_route, 'Aleksinački Rudnik', 'Technická památka v Srbsku — doly, železnice a stroje, na kterých stojí historie kraje.', 43.55472, 21.68806, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aleksinacki%20Rudnik.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aleksinacki%20Rudnik.jpg"}'::text[], 0, '{"en": {"name": "Aleksinački Rudnik", "description": "Town in Nišava District, Serbia. A technical monument in Serbia — mines, railways and machines behind the region''s history."}, "de": {"name": "Aleksinački Rudnik", "description": "Siedlung in Serbien. Ein technisches Denkmal in Serbien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Aleksinački Rudnik", "description": "Zabytek techniki w Serbii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Aleksinački Rudnik", "description": "Nederzetting in Servië. Een technisch monument in Servië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Aleksinački Rudnik", "description": "Un monumento técnico en Serbia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Aleksinački Rudnik", "description": "Ville de Serbie. Un monument technique en Serbie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Aleksinački Rudnik", "description": "Населений пункт у Сербії. Технічна пам''ятка в Сербії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Bovansko Jezero', 'Vodní plocha v Srbsku — příjemný cíl vyjížďky s výhledy na hladinu.', 43.645, 21.70858, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bovan%20Lake.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bovan%20Lake.JPG"}'::text[], 1, '{"en": {"name": "Bovansko Jezero", "description": "Reservoir. A body of water in Serbia — a pleasant ride destination with waterside views."}, "de": {"name": "Bovansko Jezero", "description": "Stausee in Serbien. Ein Gewässer in Serbien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Bovansko Jezero", "description": "Akwen w Serbii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Bovansko jezero", "description": "Stuwmeer in Servië. Een waterpartij in Servië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Bovansko Jezero", "description": "Una masa de agua en Serbia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Bovan", "description": "Un plan d''eau en Serbie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Bovansko Jezero", "description": "Водойма в Сербії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Soko Grad', 'Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 43.63139, 21.87806, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sokograd.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sokograd.jpg"}'::text[], 2, '{"en": {"name": "Soko Grad", "description": "Medieval city and fortress near Sokobanja, Serbia. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Sokograd", "description": "Burg in Serbien. Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Soko Grad", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Soko Grad", "description": "Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Soko Grad", "description": "Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Soko Grad", "description": "Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Soko Grad", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Cerje cave', 'Přírodní zajímavost v Srbsku — místo na protažení nohou uprostřed přírody.', 43.42958, 21.94096, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodopad%20na%20ulazu%20Cerjansku%20pe%C4%87inu%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodopad%20na%20ulazu%20Cerjansku%20pe%C4%87inu%20-%20panoramio.jpg"}'::text[], 3, '{"en": {"name": "Cerje cave", "description": "Cave in Serbia. A natural sight in Serbia — a spot to stretch your legs amid nature."}, "de": {"name": "Cerje-Höhle", "description": "Höhle im Südwesten Serbiens. Eine Natursehenswürdigkeit in Serbien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Cerje cave", "description": "Jaskinia turystyczna (Gmina miejska Pantelej, Serbia). Atrakcja przyrodnicza w Serbii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Cerje cave", "description": "Een natuurbezienswaardigheid in Servië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cerje cave", "description": "Cueva de Serbia. Un paraje natural en Serbia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Cerje cave", "description": "Un site naturel en Serbie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Цер''янська печера", "description": "Природна пам''ятка в Сербії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Nišská pevnost', 'Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 43.3259, 21.8954, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%A1%20Fortress%2C%20Ni%C5%A1%2C%20Serbia.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%A1%20Fortress%2C%20Ni%C5%A1%2C%20Serbia.jpg"}'::text[], 4, '{"en": {"name": "Niš Fortress", "description": "Fortress in Nis, Serbia. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Festung Nis", "description": "Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza w Niszu", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Niška Tvrdjava", "description": "Bouwwerk in Servië. Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Fortaleza de Niš", "description": "Fortaleza en Nis, Serbia. Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Niš", "description": "Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Nišská pevnost", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrální chrám svaté Trojice', 'Památka v Srbsku — kus historie přímo u trasy.', 43.31512, 21.89637, 'http://commons.wikimedia.org/wiki/Special:FilePath/Saborna%20crkva%20april%202012a.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Saborna%20crkva%20april%202012a.jpg"}'::text[], 5, '{"en": {"name": "Saborna crkva", "description": "Cathedral in Niš, Serbia. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Katedrální chrám svaté Trojice", "description": "Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sobór Zstąpienia Ducha Świętego w Niszu", "description": "Świątynia prawosławna. Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Katedrální chrám svaté Trojice", "description": "Kathedraal in Niš, Servië. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Katedrální chrám svaté Trojice", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de la Sainte-Trinité de Niš", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrální chrám svaté Trojice", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Grad cara Lazara', 'Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 43.58444, 21.32194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Don%20Zon%20kula.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Don%20Zon%20kula.jpg"}'::text[], 6, '{"en": {"name": "Kruševac Fortress", "description": "Forts in Serbia. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Grad cara Lazara", "description": "Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Grad cara Lazara", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Grad cara Lazara", "description": "Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "fortaleza de Kruševac", "description": "Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Kruševac", "description": "Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Grad cara Lazara", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb);
