    (v_route, 'Georgios Averof', 'Pancéřový křižník řeckého námořnictva třídy Pisa. Technická památka v Řecku — doly, železnice a stroje, na kterých stojí historie kraje.', 37.93373, 23.68385, 'http://commons.wikimedia.org/wiki/Special:FilePath/Averof%20Today2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Averof%20Today2.jpg"}'::text[], 0, '{"en": {"name": "Greek cruiser Georgios Averof", "description": "1910 Pisa-class cruiser. A technical monument in Greece — mines, railways and machines behind the region''s history."}, "de": {"name": "Georgios Averoff", "description": "Ein technisches Denkmal in Griechenland — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Jeorjos Awerof", "description": "Okręt marynarki wojennej Grecji. Zabytek techniki w Grecji — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Greek cruiser Georgios Averof", "description": "Museum in Griekenland. Een technisch monument in Griekenland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Georgios Averof", "description": "Un monumento técnico en Grecia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Georgios Averoff", "description": "Navire de guerre. Un monument technique en Grèce — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Георгіос Авероф", "description": "Технічна пам''ятка у Греції — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Akropolis', 'Náboženské centrum a dominanta Athén. Hrad či zámek v Řecku — historická zastávka, která stojí za odbočku.', 37.97167, 23.72611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Attica%2006-13%20Athens%2050%20View%20from%20Philopappos%20-%20Acropolis%20Hill.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Attica%2006-13%20Athens%2050%20View%20from%20Philopappos%20-%20Acropolis%20Hill.jpg"}'::text[], 1, '{"en": {"name": "Acropolis of Athens", "description": "Ancient citadel above the city of Athens. A castle in Greece — a historic stop worth the detour."}, "de": {"name": "Akropolis", "description": "Antike Stadtfestung in Athen. Eine Burg bzw. ein Schloss in Griechenland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Akropol ateński", "description": "Zamek w Grecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Akropolis van Athene", "description": "Bouwwerk in Athene. Een kasteel in Griekenland — een historische stop die de omweg waard is."}, "es": {"name": "Acrópolis de Atenas", "description": "Antigua ciudadela de Atenas. Un castillo en Grecia: una parada histórica que merece el desvío."}, "fr": {"name": "Acropole d''Athènes", "description": "Ancienne forteresse et sanctuaire à Athènes, en Grèce. Un château en Grèce — une halte historique qui vaut le détour."}, "uk": {"name": "Афінський акрополь", "description": "Антична цитадель. Замок у Греції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Metropolitan Cathedral of Athens', 'Památka v Řecku — kus historie přímo u trasy.', 37.97528, 23.73, 'http://commons.wikimedia.org/wiki/Special:FilePath/%CE%9C%CE%B7%CF%84%CF%81%CF%8C%CF%80%CE%BF%CE%BB%CE%B7%20%CE%91%CE%B8%CE%B7%CE%BD%CF%8E%CE%BD%203321.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%CE%9C%CE%B7%CF%84%CF%81%CF%8C%CF%80%CE%BF%CE%BB%CE%B7%20%CE%91%CE%B8%CE%B7%CE%BD%CF%8E%CE%BD%203321.jpg"}'::text[], 2, '{"en": {"name": "Metropolitan Cathedral of Athens", "description": "Church building in Athens, Attica Region, Greece. A heritage sight in Greece — a piece of history right on your route."}, "de": {"name": "Kathedrale Mariä Verkündigung", "description": "Kirchengebäude in Athen. Ein Denkmal in Griechenland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Zwiastowania Matki Bożej w Atenach", "description": "Świątynia prawosławna. Zabytek w Grecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Grote Metropolitaan", "description": "Bouwwerk in Athene. Een monument in Griekenland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Anunciación de Santa María", "description": "Catedral ortodoxa griega en Atenas. Un monumento en Grecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l’Annonciation", "description": "Église d''Athènes, Attique, en Grèce. Un monument en Grèce — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор в Афінах", "description": "Пам''ятка у Греції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Dinonýsia v Aténách', 'Katedrála v Řecku. Památka v Řecku — kus historie přímo u trasy.', 37.9791, 23.73461, 'http://commons.wikimedia.org/wiki/Special:FilePath/%CE%86%CE%B3%CE%B9%CE%BF%CF%82%20%CE%94%CE%B9%CE%BF%CE%BD%CF%8D%CF%83%CE%B9%CE%BF%CF%82%20%CE%91%CE%B5%CF%81%CE%BF%CF%80%CE%B1%CE%B3%CE%AF%CF%84%CE%B7%CF%82%206648.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%CE%86%CE%B3%CE%B9%CE%BF%CF%82%20%CE%94%CE%B9%CE%BF%CE%BD%CF%8D%CF%83%CE%B9%CE%BF%CF%82%20%CE%91%CE%B5%CF%81%CE%BF%CF%80%CE%B1%CE%B3%CE%AF%CF%84%CE%B7%CF%82%206648.jpg"}'::text[], 3, '{"en": {"name": "Cathedral Basilica of St. Dionysius the Areopagite", "description": "Cathedral in Athens, Greece. A heritage sight in Greece — a piece of history right on your route."}, "de": {"name": "Kathedrale St. Dionysius Areopagita", "description": "Kirchengebäude in Athen. Ein Denkmal in Griechenland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Dionizego Areopagity w Atenach", "description": "Świątynia katolicka. Zabytek w Grecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Sint Dionysius de Areopagiet", "description": "Kathedraal in Griekenland. Een monument in Griekenland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral-basílica de San Dionisio Areopagita", "description": "Un monumento en Grecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Denys-l''Aréopagite d''Athènes", "description": "Église d''Athènes, Attique, en Grèce. Un monument en Grèce — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Dinonýsia v Aténách", "description": "Пам''ятка у Греції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Dafnion', 'Památka v Řecku — kus historie přímo u trasy.', 38.01306, 23.63583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dafni%20monastery.jpeg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dafni%20monastery.jpeg"}'::text[], 4, '{"en": {"name": "Daphni Monastery", "description": "11th-century Byzantine monastery in Greece. A heritage sight in Greece — a piece of history right on your route."}, "de": {"name": "Kloster Daphni", "description": "Kloster in Griechenland. Ein Denkmal in Griechenland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Dafni", "description": "Kompleks zabudowań XI-wiecznego klasztoru bizantyjskiego na przedmieściu Aten. Zabytek w Grecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster van Dafni", "description": "Klooster in Griekenland. Een monument in Griekenland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Dafni", "description": "Un monumento en Grecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Daphni", "description": "Bâtiment d''Attique, en Grèce. Un monument en Grèce — un morceau d''histoire au bord de la route."}, "uk": {"name": "Монастир Дафні", "description": "Пам''ятка у Греції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Eurípidova jeskyně', 'Přírodní zajímavost v Řecku — místo na protažení nohou uprostřed přírody.', 37.88218, 23.4522, 'http://commons.wikimedia.org/wiki/Special:FilePath/The%20famous%20Cave%20of%20Euripides%20on%20Salamis%20island%2C%20Greece.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/The%20famous%20Cave%20of%20Euripides%20on%20Salamis%20island%2C%20Greece.jpg"}'::text[], 5, '{"en": {"name": "Cave of Euripides", "description": "Cave in Greece. A natural sight in Greece — a spot to stretch your legs amid nature."}, "de": {"name": "Höhle des Euripides", "description": "Höhle beim Ort Peristeria im Süden der Insel Salamis. Eine Natursehenswürdigkeit in Griechenland — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Jaskinia Eurypidesa", "description": "Historyczna jaskinia na greckiej Salaminie. Atrakcja przyrodnicza w Grecji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Eurípidova jeskyně", "description": "Een natuurbezienswaardigheid in Griekenland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Eurípides", "description": "Cueva en Salamina, Grecia. Un paraje natural en Grecia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Eurípidova jeskyně", "description": "Un site naturel en Grèce — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Печера Евріпіда", "description": "Печера у Греції. Природна пам''ятка у Греції — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Lake Vouliagmeni', 'Vodní plocha v Řecku — příjemný cíl vyjížďky s výhledy na hladinu.', 37.8075, 23.78556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vouliagmenis%20lake%202.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vouliagmenis%20lake%202.JPG"}'::text[], 6, '{"en": {"name": "Lake Vouliagmeni", "description": "Lake in Athens, Greece. A body of water in Greece — a pleasant ride destination with waterside views."}, "de": {"name": "Limni tis Vouliagmenis", "description": "See in Attika, Griechenland. Ein Gewässer in Griechenland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lake Vouliagmeni", "description": "Jezioro w Grecji. Akwen w Grecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lake Vouliagmeni", "description": "Meer in Griekenland. Een waterpartij in Griekenland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lake Vouliagmeni", "description": "Una masa de agua en Grecia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Vouliagméni", "description": "Lac grec. Un plan d''eau en Grèce — une belle destination avec vue sur l''eau."}, "uk": {"name": "Вуліагмені", "description": "Водойма у Греції — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
