    (v_route, 'Hungarian Railway Museum', 'Technická památka v Maďarsku — doly, železnice a stroje, na kterých stojí historie kraje.', 47.54194, 19.09778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vasuttorteneti%20park%20009.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vasuttorteneti%20park%20009.jpg"}'::text[], 0, '{"en": {"name": "Hungarian Railway Museum", "description": "Railway museum in Budapest, Hungary. A technical monument in Hungary — mines, railways and machines behind the region''s history."}, "de": {"name": "Bahnhistorischer Park Budapest", "description": "Eisenbahnmuseum in Budapest, Ungarn. Ein technisches Denkmal in Ungarn — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Hungarian Railway Museum", "description": "Zabytek techniki na Węgrzech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Vasúttörténeti Park", "description": "Museum in Boedapest. Een technisch monument in Hongarije — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Hungarian Railway Museum", "description": "Un monumento técnico en Hungría: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "parc de l''histoire ferroviaire hongroise", "description": "Un monument technique en Hongrie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Угорський парк залізничної історії", "description": "Технічна пам''ятка в Угорщині — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Aquincum', 'Římské město a vojenský tábor v Pannonii Inferior; dnes na území Budapešti. Hrad či zámek v Maďarsku — historická zastávka, která stojí za odbočku.', 47.56414, 19.04947, 'http://commons.wikimedia.org/wiki/Special:FilePath/Polg%C3%A1rv%C3%A1ros1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Polg%C3%A1rv%C3%A1ros1.jpg"}'::text[], 1, '{"en": {"name": "Aquincum", "description": "Historical settlement in the Roman Empire. A castle in Hungary — a historic stop worth the detour."}, "de": {"name": "Aquincum", "description": "Römische Vorgängerstadt von Budapest. Eine Burg bzw. ein Schloss in Ungarn — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Aquincum", "description": "Starożytne miasto rzymskie i obóz legionów nad Dunajem. Zamek na Węgrzech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Aquincum", "description": "Museum in Hongarije. Een kasteel in Hongarije — een historische stop die de omweg waard is."}, "es": {"name": "Aquincum", "description": "Asentamiento romano que dio origen a la ciudad de Budapest. Un castillo en Hungría: una parada histórica que merece el desvío."}, "fr": {"name": "Aquincum", "description": "Antique cité romaine sur le site de Budapest, Hongrie. Un château en Hongrie — une halte historique qui vaut le détour."}, "uk": {"name": "Аквінк", "description": "Замок в Угорщині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Matyášův chrám', 'Kostel v Budapešti. Památka v Maďarsku — kus historie přímo u trasy.', 47.50194, 19.03417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Matthias%20Church%2C%20Budapest%2C%202017.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Matthias%20Church%2C%20Budapest%2C%202017.jpg"}'::text[], 2, '{"en": {"name": "Matthias Church", "description": "Roman Catholic church in Budapest, Hungary. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "Matthiaskirche", "description": "Kirche in Budapest. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół Macieja w Budapeszcie", "description": "Świątynia katolicka. Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Matthiaskerk", "description": "Boedapest. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia de Matías", "description": "Iglesia católica ubicada en Budapest. Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Notre-Dame-de-l''Assomption de Budavár", "description": "Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Церква Матяша", "description": "Церква в Будапешті (Угорщина). Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Budínský hrad', 'Hrad v Budapešti. Hrad či zámek v Maďarsku — historická zastávka, která stojí za odbočku.', 47.49611, 19.03972, 'http://commons.wikimedia.org/wiki/Special:FilePath/20190502%20Zamek%20w%20Budapeszcie%200647%201862%20DxO.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20190502%20Zamek%20w%20Budapeszcie%200647%201862%20DxO.jpg"}'::text[], 3, '{"en": {"name": "Buda Castle", "description": "Castle and palace complex of the Hungarian kings in Budapest. A castle in Hungary — a historic stop worth the detour."}, "de": {"name": "Budaer Burg", "description": "Größtes Gebäude in Ungarn, Sehenswürdigkeit der Hauptstadt Budapest. Eine Burg bzw. ein Schloss in Ungarn — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Królewski w Budapeszcie", "description": "Zabytkowy zespół pałacowy w Budapeszcie, Węgy. Zamek na Węgrzech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burcht van Boeda", "description": "Bouwwerk in Boedapest. Een kasteel in Hongarije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Buda", "description": "Monumento más grande de Hungría, atracción turística de su capital Budapest. Un castillo en Hungría: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Budavár", "description": "Un château en Hongrie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Буда", "description": "Замково-палацовий комплекс угорських королів у Будапешті. Замок в Угорщині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bazilika svatého Štěpána', 'Římskokatolická bazilika v Budapešti. Památka v Maďarsku — kus historie přímo u trasy.', 47.50083, 19.05389, 'http://commons.wikimedia.org/wiki/Special:FilePath/HUN-2015-Budapest-St.%20Stephen%27s%20Basilica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/HUN-2015-Budapest-St.%20Stephen%27s%20Basilica.jpg"}'::text[], 4, '{"en": {"name": "St. Stephen''s Basilica", "description": "Roman Catholic basilica in Budapest, Hungary. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "St.-Stephans-Basilika", "description": "Kirchengebäude in Budapest, Ungarn. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Stefana w Budapeszcie", "description": "Świątynia katolicka. Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Stefanusbasiliek", "description": "Bouwwerk in Boedapest. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Esteban", "description": "Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Étienne de Pest", "description": "Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Іштвана", "description": "Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Velká synagoga', 'Maďarská synagoga se sídlem v Budapešti, postavená v letech 1854-1859. Největší synagoga v Evropě a jedna z největších synagog na světě. Památka v Maďarsku — kus historie přímo u trasy.', 47.4959, 19.0607, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue-Budapest.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue-Budapest.jpg"}'::text[], 5, '{"en": {"name": "Dohány Street Synagogue", "description": "Synagogue in Budapest, Hungary. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "Große Synagoge", "description": "Synagoge in Budapest. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Wielka Synagoga w Budapeszcie", "description": "Synagoga (Budapeszt, Węgry). Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Grote Synagoge van Boedapest", "description": "Bouwwerk in Boedapest. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Gran Sinagoga de Budapest", "description": "Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "Grande synagogue de Budapest", "description": "Synagogue en Hongrie. Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Велика синагога (Будапешт)", "description": "Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika Nanebevzetí Panny Marie a svatého Vojtěcha v Ostřihomi', 'Katedrála v Maďarsku. Památka v Maďarsku — kus historie přímo u trasy.', 47.79889, 18.73639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20in%20Esztergom%2C%20Hungary%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20in%20Esztergom%2C%20Hungary%2001.jpg"}'::text[], 6, '{"en": {"name": "Esztergom Basilica", "description": "Minor basilica. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "Kathedrale Unserer Lieben Frau und des heiligen Adalbert", "description": "Kirchengebäude in Esztergom, Ungarn. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "bazylika Ostrzyhomska", "description": "Świątynia katolicka, katedra w Ostrzyhomiu na Węgrzech. Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Esztergom Basilica", "description": "Kathedraal in Esztergom, Hongarije. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Adalberto", "description": "Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Adalbert d''Esztergom", "description": "Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка святого Адальберта", "description": "Найголовніший та найбільший католицький храм Угорщини. Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb);
