    (v_route, 'Wilhelm Bauer', 'Cvičná a experimentální diesel-elektrická ponorka německého námořnictva typu XXI. Technická památka v Německu — doly, železnice a stroje, na kterých stojí historie kraje.', 53.54139, 8.57778, 'http://commons.wikimedia.org/wiki/Special:FilePath/U%20boat%20wilhelm%20bauer.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/U%20boat%20wilhelm%20bauer.JPG"}'::text[], 0, '{"en": {"name": "Wilhelm Bauer", "description": "1945 Type XXI submarine. A technical monument in Germany — mines, railways and machines behind the region''s history."}, "de": {"name": "U-Boot Wilhelm Bauer", "description": "Deutsches Museums U-Boot vom Typ XXI im Alten Hafen Bremerhaven. Ein technisches Denkmal in Deutschland — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Wilhelm Bauer", "description": "Niemiecki okręt podwodny. Zabytek techniki w Niemczech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Wilhelm Bauer", "description": "Museum in Duitsland. Een technisch monument in Duitsland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Wilhelm Bauer", "description": "Un monumento técnico en Alemania: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "U-2540", "description": "Musée en Allemagne. Un monument technique en Allemagne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Wilhelm Bauer", "description": "Технічна пам''ятка в Німеччині — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Dahlemer See', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 53.68355, 8.75664, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cuxhaven%20Fotoflugkurs%202965.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cuxhaven%20Fotoflugkurs%202965.jpg"}'::text[], 1, '{"en": {"name": "Dahlemer See", "description": "Lake in Lower Saxony, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Dahlemer See", "description": "Niedermoorsee mit einer Größe von etwa 110 Hektar. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Dahlemer See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Dahlemer See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Dahlemer See", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Dahlemer See", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Dahlemer See", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Bederkesaer See', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 53.6267, 8.86111, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bederkesa%20See%20und%20Hadelner%20Kanal%202005%20by-RaBoe.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bederkesa%20See%20und%20Hadelner%20Kanal%202005%20by-RaBoe.jpg"}'::text[], 2, '{"en": {"name": "Bederkesaer See", "description": "Lake in Geestland, Lower Saxony, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Bederkesaer See", "description": "Moorsee in Niedersachsen. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Bederkesaer See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Bederkesaer See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Bederkesaer See", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Bederkesaer See", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Bederkesaer See", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Vörder See', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 53.4927, 9.15713, 'http://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B6rder%20See%20Steg%20Norden.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B6rder%20See%20Steg%20Norden.jpg"}'::text[], 3, '{"en": {"name": "Vörder See", "description": "Lake in Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Vörder See", "description": "See im Norden der Stadt Bremervörde in Niedersachsen. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vörder See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vörder See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vörder See", "description": "Lago de Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Vörder See", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vörder See", "description": "Озеро в Німеччині. Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Huvenhoops-See', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 53.3742, 9.10361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Huvenhoops%20Moor%26See.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Huvenhoops%20Moor%26See.jpg"}'::text[], 4, '{"en": {"name": "Huvenhoops-See", "description": "Lake in Gnarrenburg, Lower Saxony, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Huvenhoopssee", "description": "See bei Gnarrenburg in Niedersachsen. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Huvenhoops-See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Huvenhoops-See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Huvenhoops-See", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Huvenhoopssee", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Huvenhoops-See", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Ponorkový bunkr Valentin', 'Nedokončená nacistická továrna na ponorky. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 53.21699, 8.50628, 'http://commons.wikimedia.org/wiki/Special:FilePath/Luftbild%20Bunker%20Valentin.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Luftbild%20Bunker%20Valentin.jpg"}'::text[], 5, '{"en": {"name": "Valentin submarine pens", "description": "Architectural structure. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "U-Boot-Bunker Valentin", "description": "Verbunkerte U-Boot-Werft aus dem Zweiten Weltkrieg. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Bunkier okrętów podwodnych Valentin", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Ponorkový bunkr Valentin", "description": "Bouwwerk in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Refugio para submarinos de Valentin", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "U-Boot-Bunker Valentin", "description": "Musée en Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Ponorkový bunkr Valentin", "description": "Споруда. Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Lake Bant', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 53.507, 8.0979, 'http://commons.wikimedia.org/wiki/Special:FilePath/Luftaufnahmen%20Nordseekueste%202012%2005%20D90%20by-RaBoe%20133.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Luftaufnahmen%20Nordseekueste%202012%2005%20D90%20by-RaBoe%20133.jpg"}'::text[], 6, '{"en": {"name": "Lake Bant", "description": "Lake in Wilhelmshaven, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Banter See", "description": "See in Wilhelmshaven. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lake Bant", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lake Bant", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Bant", "description": "Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Banter See", "description": "Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Lake Bant", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
