    (v_route, 'Veliki Crljeni', 'Technická památka v Srbsku — doly, železnice a stroje, na kterých stojí historie kraje.', 44.46722, 20.28389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Veliki%20Crljeni%20termoelektrana%20Kolubara2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Veliki%20Crljeni%20termoelektrana%20Kolubara2.jpg"}'::text[], 0, '{"en": {"name": "Veliki Crljeni", "description": "Town in Belgrade District, Serbia. A technical monument in Serbia — mines, railways and machines behind the region''s history."}, "de": {"name": "Veliki Crljeni", "description": "Ein technisches Denkmal in Serbien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Veliki Crljeni", "description": "Wieś w Serbii. Zabytek techniki w Serbii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Veliki Crljeni", "description": "Buitenwijk in Belgrado, Servië. Een technisch monument in Servië — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Veliki Crljeni", "description": "Un monumento técnico en Serbia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Veliki Crljeni", "description": "Ville de Serbie. Un monument technique en Serbie — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Veliki Crljeni", "description": "Технічна пам''ятка в Сербії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Risovača Cave', 'Přírodní zajímavost v Srbsku — místo na protažení nohou uprostřed přírody.', 44.3, 20.56667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ulaz%20u%20pecinu%20risovaca.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ulaz%20u%20pecinu%20risovaca.jpg"}'::text[], 1, '{"en": {"name": "Risovača Cave", "description": "Cave in Serbia. A natural sight in Serbia — a spot to stretch your legs amid nature."}, "de": {"name": "Risovača Cave", "description": "Eine Natursehenswürdigkeit in Serbien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Risovača Cave", "description": "Atrakcja przyrodnicza w Serbii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Risovača", "description": "Een natuurbezienswaardigheid in Servië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Risovača", "description": "Cueva de Serbia. Un paraje natural en Serbia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Risovača Cave", "description": "Un site naturel en Serbie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Risovača Cave", "description": "Природна пам''ятка в Сербії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Žrnov', 'Hrad v Srbsku. Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 44.6887, 20.5158, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zrnov1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zrnov1.jpg"}'::text[], 2, '{"en": {"name": "Žrnov", "description": "Demolished medieval fort in Belgrade, Serbia. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Žrnov", "description": "Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Žrnov", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Zjrnov", "description": "Vesting in Servië. Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Žrnov", "description": "Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Žrnov", "description": "Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Žrnov", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Rakovica monastery', 'Památka v Srbsku — kus historie přímo u trasy.', 44.7304, 20.447, 'http://commons.wikimedia.org/wiki/Special:FilePath/%D0%9C%D0%B0%D0%BD%D0%B0%D1%81%D1%82%D0%B8%D1%80%20%D0%A0%D0%B0%D0%BA%D0%BE%D0%B2%D0%B8%D1%86%D0%B0.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%D0%9C%D0%B0%D0%BD%D0%B0%D1%81%D1%82%D0%B8%D1%80%20%D0%A0%D0%B0%D0%BA%D0%BE%D0%B2%D0%B8%D1%86%D0%B0.jpg"}'::text[], 3, '{"en": {"name": "Rakovica monastery", "description": "Serbian monastery. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Rakovica monastery", "description": "Kloster in Serbien. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Monaster Rakovica", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Manastir Rakovica", "description": "Klooster in Belgrado, Servië. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Rakovica monastery", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Rakovica", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Rakovica monastery", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála Nanebevzetí Panny Marie v Bělehradě', 'Římskokatolická katedrála v Srbsku. Památka v Srbsku — kus historie přímo u trasy.', 44.7944, 20.476, 'http://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B2%D1%98%D0%B5%D1%82%D0%BB%D0%BE%D0%BF%D0%B8%D1%81%20%D0%BA%D0%B0%D1%82%D0%BE%D0%BB%D0%B8%D1%87%D0%BA%D0%B5%20%D0%BA%D0%B0%D1%82%D0%B5%D0%B4%D1%80%D0%B0%D0%BB%D0%B5%20%D0%A3%D0%B7%D0%BD%D0%B5%D1%81%D0%B5%D1%9A%D0%B0%20%D0%91%D0%BE%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%86%D0%B5%2C%20%D0%92%D1%80%D0%B0%D1%87%D0%B0%D1%80%2C%20%D0%91%D0%B8%D0%BE%D0%B3%D1%80%D0%B0%D0%B4%2C%20%D0%A1%D1%80%D0%B1%D0%B8%D1%98%D0%B0.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B2%D1%98%D0%B5%D1%82%D0%BB%D0%BE%D0%BF%D0%B8%D1%81%20%D0%BA%D0%B0%D1%82%D0%BE%D0%BB%D0%B8%D1%87%D0%BA%D0%B5%20%D0%BA%D0%B0%D1%82%D0%B5%D0%B4%D1%80%D0%B0%D0%BB%D0%B5%20%D0%A3%D0%B7%D0%BD%D0%B5%D1%81%D0%B5%D1%9A%D0%B0%20%D0%91%D0%BE%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%86%D0%B5%2C%20%D0%92%D1%80%D0%B0%D1%87%D0%B0%D1%80%2C%20%D0%91%D0%B8%D0%BE%D0%B3%D1%80%D0%B0%D0%B4%2C%20%D0%A1%D1%80%D0%B1%D0%B8%D1%98%D0%B0.jpg"}'::text[], 4, '{"en": {"name": "Cathedral of the Blessed Virgin Mary, Belgrade", "description": "Church in Belgrade, Serbia. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Katedrála Nanebevzetí Panny Marie v Bělehradě", "description": "Kathedrale in Serbien. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Maryi Panny w Belgradzie", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Katedrála Nanebevzetí Panny Marie v Bělehradě", "description": "Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Santísima Virgen María", "description": "Templo religioso en Serbia. Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Katedrála Nanebevzetí Panny Marie v Bě