    (v_route, 'Chrám svatého Sávy', 'Kostel v Bělehradě. Památka v Srbsku — kus historie přímo u trasy.', 44.79808, 20.46855, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hram%20Beograd.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hram%20Beograd.JPG"}'::text[], 5, '{"en": {"name": "Church of Saint Sava", "description": "Church in Belgrade, Serbia. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Dom des Heiligen Sava", "description": "Kirchengebäude in Belgrad. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Cerkiew świętego Sawy w Belgradzie", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van de Heilige Sava", "description": "Bouwwerk in Belgrado. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Templo de San Sava", "description": "Santuario e iglesia ortodoxa monumental en Belgrado. Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Sava de Belgrade", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Храм Святого Сави", "description": "Церква у Белграді (Софія). Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
