    (v_route, 'Maritime Museum', 'Technická památka ve Švédsku — doly, železnice a stroje, na kterých stojí historie kraje.', 59.3325, 18.11583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sj%C3%B6historiska%20museet%202008.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sj%C3%B6historiska%20museet%202008.jpg"}'::text[], 0, '{"en": {"name": "Maritime Museum", "description": "Museum in Stockholm, Sweden. A technical monument in Sweden — mines, railways and machines behind the region''s history."}, "de": {"name": "Maritimes Museum", "description": "Museum zur Seefahrtsgeschichte in Stockholm, Schweden. Ein technisches Denkmal in Schweden — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Maritime Museum", "description": "Zabytek techniki w Szwecji — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Zeehistorisch Museum", "description": "Museum in Zweden. Een technisch monument in Zweden — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo de Historia Marina", "description": "Museo en Estocolmo, Suecia. Un monumento técnico en Suecia: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "musée d’histoire de la marine", "description": "Musée à Stockholm, Suède. Un monument technique en Suède — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Maritime Museum", "description": "Технічна пам''ятка у Швеції — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Saint Sava Serbian Orthodox Church', 'Památka ve Švédsku — kus historie přímo u trasy.', 59.28944, 18.06167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Sava%202013a.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Sava%202013a.JPG"}'::text[], 1, '{"en": {"name": "Saint Sava Serbian Orthodox Church", "description": "Serbian Orthodox Church building in Enskede, southern Stockholm, Sweden. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Saint Sava Serbian Orthodox Church", "description": "Kirchengebäude in Schweden. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Cerkiew św. Sawy w Sztokholmie", "description": "Cerkiew w Szwecji. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Saint Sava Serbian Orthodox Church", "description": "Kerkgebouw in Stockholm, Zweden. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Saint Sava Serbian Orthodox Church", "description": "Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église orthodoxe serbe Saint-Sava", "description": "Bâtiment de la commune de Stockholm, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Saint Sava Serbian Orthodox Church", "description": "Церква у Швеції. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Brunnsviken', 'Vodní plocha ve Švédsku — příjemný cíl vyjížďky s výhledy na hladinu.', 59.36806, 18.04, 'http://commons.wikimedia.org/wiki/Special:FilePath/Brunnsviken%20sommar.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Brunnsviken%20sommar.jpg"}'::text[], 2, '{"en": {"name": "Brunnsviken", "description": "Bay in Stockholm, Sweden. A body of water in Sweden — a pleasant ride destination with waterside views."}, "de": {"name": "Brunnsviken", "description": "See in Schweden. Ein Gewässer in Schweden — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Brunnsviken", "description": "Akwen w Szwecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Brunnsviken", "description": "Meer in Zweden. Een waterpartij in Zweden — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Brunnsviken", "description": "Una masa de agua en Suecia: un destino agradable con vistas al agua."}, "fr": {"name": "Brunnsviken", "description": "Lac suédois. Un plan d''eau en Suède — une belle destination avec vue sur l''eau."}, "uk": {"name": "Brunnsviken", "description": "Водойма у Швеції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Åkeshov Castle', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.34083, 17.92472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Akeshov%20slott%202008%20%286%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Akeshov%20slott%202008%20%286%29.JPG"}'::text[], 3, '{"en": {"name": "Åkeshov Castle", "description": "Castle in Sweden. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Schloss Åkeshov", "description": "Schloss in Schweden. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Åkeshov Castle", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Åkeshov Castle", "description": "Kasteel in Zweden. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Åkeshov", "description": "Castillo en Suecia. Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "château Åkeshov", "description": "Bâtiment de la commune de Stockholm, Suède. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Åkeshov Castle", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bogesund Castle', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.39333, 18.28444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bogesunds%20Slott.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bogesunds%20Slott.JPG"}'::text[], 4, '{"en": {"name": "Bogesund Castle", "description": "Building in Vaxholm Municipality, Stockholm County, Sweden. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Schloss Bogesund", "description": "Schloss in Schweden. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Bogesund Castle", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Bogesund Castle", "description": "Kasteel in Zweden. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Bogesund", "description": "Castillo en Suecia. Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bogesund", "description": "Château à Vaxholm en Suède. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Боґесунд (Швеція)", "description": "Будівля у Швеції. Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Tyresö Palace', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.23528, 18.30472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tyreso%20slott%20view1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tyreso%20slott%20view1.jpg"}'::text[], 5, '{"en": {"name": "Tyresö Palace", "description": "Palace started in the 1620s and completed in 1636 by the Lord High Steward Gabriel Oxenstierna. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Schloss Tyresö", "description": "Der Bau des Palastes begann in den 1620er Jahren und wurde 1636 von Drossart Gabriel Oxenstierna abgeschlossen. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Tyresö Palace", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Tyresö", "description": "De bouw van het paleis begon in de jaren 1620 en werd voltooid in 1636 door landdrost Gabriel Oxenstierna. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Tyresö", "description": "Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Tyresö", "description": "Bâtiment de la commune de Tyresö, en Suède. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Tyresö Palace", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Alsnö hus', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.3608, 17.53576, 'http://commons.wikimedia.org/wiki/Special:FilePath/The%20castle%20Alsnohus%20in%20Sweden.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/The%20castle%20Alsnohus%20in%20Sweden.jpg"}'::text[], 6, '{"en": {"name": "Alsnö hus", "description": "Building in Ekerö Municipality, Stockholm County, Sweden. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Alsnö hus", "description": "Burg in Schweden. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Alsnö hus", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Alsnö hus", "description": "Kasteel in Zweden. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Alsnö hus", "description": "Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "Alsnö hus", "description": "Bâtiment de la commune d''Ekerö, en Suède. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Alsnö hus", "description": "Будівля у Швеції. Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb);
