    (v_route, 'Saalfeld Fairy Grottoes', 'Technická památka v Německu — doly, železnice a stroje, na kterých stojí historie kraje.', 50.63549, 11.34331, 'http://commons.wikimedia.org/wiki/Special:FilePath/140823%20M%C3%A4rchendom%20Saalfelder%20Feengrotten.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/140823%20M%C3%A4rchendom%20Saalfelder%20Feengrotten.jpg"}'::text[], 0, '{"en": {"name": "Saalfeld Fairy Grottoes", "description": "Mine in Germany. A technical monument in Germany — mines, railways and machines behind the region''s history."}, "de": {"name": "Feengrotten", "description": "Schaubergwerk in Deutschland, außerdem gibt es daneben das Feenwäldchen. Ein technisches Denkmal in Deutschland — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Saalfeld Fairy Grottoes", "description": "Zabytek techniki w Niemczech — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Saalfeld Fairy Grottoes", "description": "Duits nationaal monument in Saalfeld/Saale. Een technisch monument in Duitsland — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Saalfeld Fairy Grottoes", "description": "Mina de Alemania. Un monumento técnico en Alemania: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "grotte des Fées de Saalfeld", "description": "Mine en Allemagne. Un monument technique en Allemagne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Saalfeld Fairy Grottoes", "description": "Технічна пам''ятка в Німеччині — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Saalfeld Abbey', 'Památka v Německu — kus historie přímo u trasy.', 50.6524, 11.3585, 'http://commons.wikimedia.org/wiki/Special:FilePath/Salfeld%20%28Merian%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Salfeld%20%28Merian%29.jpg"}'::text[], 1, '{"en": {"name": "Saalfeld Abbey", "description": "Monastery. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Benediktinerkloster Saalfeld", "description": "Kloster der Benediktiner in Saalfeld/Saale in Thüringen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Saalfeld Abbey", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij Saalfeld", "description": "Klooster in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Saalfeld", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye bénédictine de Saalfeld", "description": "Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Saalfeld Abbey", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Heidecksburg', 'Barokní zámek středověkého původu, sloužící dříve jako rezidence durynského knížecího rodu Schwarzburg-Rudolstadt. Nyní v objektu sídlí zemské muzeum a archiv. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.723, 11.339, 'http://commons.wikimedia.org/wiki/Special:FilePath/Residenzschloss%20Heidecksburg%20Rudolstadt.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Residenzschloss%20Heidecksburg%20Rudolstadt.jpg"}'::text[], 2, '{"en": {"name": "Heidecksburg", "description": "Castle. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Heidecksburg", "description": "Schloss in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Heidecksburg", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Heidecksburg", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Heidecksburg", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Heidecksburg", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Гайдексбург", "description": "Замок (споруда). Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
