    (v_route, 'Námořní muzeum v Barceloně', 'Muzeum. Technická památka ve Španělsku — doly, železnice a stroje, na kterých stojí historie kraje.', 41.37503, 2.17637, 'http://commons.wikimedia.org/wiki/Special:FilePath/Drassanes%20barcelona.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Drassanes%20barcelona.jpg"}'::text[], 0, '{"en": {"name": "Maritime Museum of Barcelona", "description": "Museum. A technical monument in Spain — mines, railways and machines behind the region''s history."}, "de": {"name": "Museu Marítim de Barcelona", "description": "Schifffahrtsmuseum am Hafen von Barcelona. Ein technisches Denkmal in Spanien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Námořní muzeum v Barceloně", "description": "Zabytek techniki w Hiszpanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Maritime Museum of Barcelona", "description": "Museum in Barcelona, Spanje. Een technisch monument in Spanje — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Museo Marítimo de Barcelona", "description": "Museo de la ciudad de Barcelona, (España). Un monumento técnico en España: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "musée maritime de Barcelone", "description": "Musée espagnol. Un monument technique en Espagne — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Морський музей Барселони", "description": "Технічна пам''ятка в Іспанії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Katedrála v Barceloně', 'Katedrála ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 41.38389, 2.17639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20Cathedral%20Saint%20Eulalia.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20Cathedral%20Saint%20Eulalia.jpg"}'::text[], 1, '{"en": {"name": "Cathedral of the Holy Cross and Saint Eulalia", "description": "Gothic cathedral and seat of the Archbishop of Barcelona, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kathedrale von Barcelona", "description": "Kirchengebäude in Barcelona. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Eulalii w Barcelonie", "description": "Świątynia katolicka. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Barcelona", "description": "Kathedraal in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santa Eulalia de Barcelona", "description": "Catedral de Barcelona, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Eulalie de Barcelone", "description": "Édifice religieux espagnol. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Барселонський собор", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
