    (v_route, 'U 534', 'Německá ponorka typu IX C/40. Technická památka ve Velké Británii — doly, železnice a stroje, na kterých stojí historie kraje.', 53.3951, -3.00933, 'http://commons.wikimedia.org/wiki/Special:FilePath/U534.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/U534.jpg"}'::text[], 0, '{"en": {"name": "U-534", "description": "1942 Type IXC/40 submarine. A technical monument in the United Kingdom — mines, railways and machines behind the region''s history."}, "de": {"name": "U 534", "description": "Deutsches Museums U-Boot des Typs IX C/40 in Birkenhead, England. Ein technisches Denkmal in Großbritannien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "U-534", "description": "Niemiecki U-Boot wodowany w 1942 roku. Zabytek techniki w Wielkiej Brytanii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "German submarine U-534", "description": "Museum in het Verenigd Koninkrijk. Een technisch monument in het Verenigd Koninkrijk — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "U 534", "description": "Un monumento técnico en el Reino Unido: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "Unterseeboot 534", "description": "Navire de guerre. Un monument technique au Royaume-Uni — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "U 534", "description": "Технічна пам''ятка у Великій Британії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Liverpoolská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.39751, -2.97305, 'http://commons.wikimedia.org/wiki/Special:FilePath/LIVERPOOL%20ANGLICAN%20CATHEDRAL%20SEP2012%20%287916053494%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/LIVERPOOL%20ANGLICAN%20CATHEDRAL%20SEP2012%20%287916053494%29.jpg"}'::text[], 1, '{"en": {"name": "Liverpool Cathedral", "description": "Cathedral of the Diocese of Liverpool, Merseyside, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Liverpool Cathedral", "description": "Neogotische Kathedrale in der englischen Stadt Liverpool. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Liverpoolu", "description": "Neogotycka anglikańska katedra w Liverpoolu. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Liverpool", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Liverpool", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Liverpool", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Liverpoolská katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Liverpoolská metropolitní katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.40472, -2.96889, 'http://commons.wikimedia.org/wiki/Special:FilePath/Liverpool%20Metropolitan%20Cathedral%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Liverpool%20Metropolitan%20Cathedral%2002.jpg"}'::text[], 2, '{"en": {"name": "Liverpool Metropolitan Cathedral", "description": "Catholic cathedral. seat of the Archbishop of Liverpool in England. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Liverpool Metropolitan Cathedral", "description": "Kirche in Liverpool, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Metropolitarna w Liverpoolu", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Liverpool Metropolitan Cathedral", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Metropolitana de Liverpool", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale métropolitaine du Christ-Roi de Liverpool", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Liverpoolská metropolitní katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Chesterská katedrála', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.19194, -2.89056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Chester%20Cathedral%20ext%20Hamilton%20005.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Chester%20Cathedral%20ext%20Hamilton%20005.JPG"}'::text[], 3, '{"en": {"name": "Chester Cathedral", "description": "Grade I listed cathedral in Chester, United Kingdom. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Chester Cathedral", "description": "Kirchengebäude in Cheshire West and Chester, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Chester", "description": "Katedra katedralna kościoła anglikańskiego. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Chester", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Chester", "description": "Catedral de culto anglicano. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Chester", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Chesterská katedrála", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Holt Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 53.0779, -2.88023, 'http://commons.wikimedia.org/wiki/Special:FilePath/Remains%20of%20Holt%20Castle%20-%20geograph.org.uk%20-%20352189.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Remains%20of%20Holt%20Castle%20-%20geograph.org.uk%20-%20352189.jpg"}'::text[], 4, '{"en": {"name": "Holt Castle", "description": "Grade II* listed building in Wrexham. Castle in Holt, north Wales. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Holt Castle", "description": "Archäologische Stätte im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Holt Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Holt Castle", "description": "Archeologische vindplaats in Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Holt", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Holt", "description": "Château britannique, pays de Galles. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Holt Castle", "description": "Археологічна пам''ятка у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Beeston Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 53.12865, -2.69354, 'http://commons.wikimedia.org/wiki/Special:FilePath/Beeston%20Castle%20%285369%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Beeston%20Castle%20%285369%29.jpg"}'::text[], 5, '{"en": {"name": "Beeston Castle", "description": "Former Royal castle and museum in Beeston, Cheshire, England, United Kingdom. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Beeston Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Beeston Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Beeston Castle", "description": "Ruïne in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Beeston", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Beeston", "description": "Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Beeston Castle", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
