    (v_route, 'Bois du Cazier', 'Technická památka v Belgii — doly, železnice a stroje, na kterých stojí historie kraje.', 50.38056, 4.44278, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bois%20du%20Cazier%203.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bois%20du%20Cazier%203.jpg"}'::text[], 0, '{"en": {"name": "Bois du Cazier", "description": "Coal mine at Charleroi. A technical monument in Belgium — mines, railways and machines behind the region''s history."}, "de": {"name": "Bois du Cazier", "description": "Belgische Kohlebergwerk. Ein technisches Denkmal in Belgien — Bergwerke, Bahnen und Maschinen der Regionalgeschichte."}, "pl": {"name": "Bois du Cazier", "description": "Zabytek techniki w Belgii — kopalnie, koleje i maszyny, na których stoi historia regionu."}, "nl": {"name": "Bois du Cazier", "description": "Kolenmijn in Marcinelle, België. Een technisch monument in België — mijnen, spoorwegen en machines achter de streekgeschiedenis."}, "es": {"name": "Bois du Cazier", "description": "Un monumento técnico en Bélgica: minas, ferrocarriles y máquinas de la historia local."}, "fr": {"name": "bois du Cazier", "description": "Site minier de Marcinelle. Un monument technique en Belgique — mines, chemins de fer et machines qui ont fait l''histoire locale."}, "uk": {"name": "Буа-дю-Казьє", "description": "Колишня вугільна шахта в Бельгії, нині - музей гірничої справи. Технічна пам''ятка у Бельгії — шахти, залізниці й машини, на яких стоїть історія краю."}}'::jsonb),
    (v_route, 'Grotte de Spy', 'Přírodní zajímavost v Belgii — místo na protažení nohou uprostřed přírody.', 50.48019, 4.6745, 'http://commons.wikimedia.org/wiki/Special:FilePath/Spygrot.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Spygrot.jpg"}'::text[], 1, '{"en": {"name": "Grotte de Spy", "description": "Cave in Belgium. A natural sight in Belgium — a spot to stretch your legs amid nature."}, "de": {"name": "Grotte de Spy", "description": "Höhle in Belgien. Eine Natursehenswürdigkeit in Belgien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Spy", "description": "Atrakcja przyrodnicza w Belgii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Grotte de Spy", "description": "Grot in België. Een natuurbezienswaardigheid in België — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Spy", "description": "Cueva del municipio de Jemeppe-sur-Sambre, Bélgica. Un paraje natural en Bélgica: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "grotte de Spy", "description": "Grotte et site paléolithique en Belgique. Un site naturel en Belgique — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Grotte de Spy", "description": "Природна пам''ятка у Бельгії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'St Aubin''s Cathedral', 'Památka v Belgii — kus historie přímo u trasy.', 50.46457, 4.86001, 'http://commons.wikimedia.org/wiki/Special:FilePath/Namur%202007%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Namur%202007%2001.JPG"}'::text[], 2, '{"en": {"name": "St Aubin''s Cathedral", "description": "Cathedral in Namur, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Kathedrale von Namur", "description": "Kathedrale in Belgien. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Albana w Namurze", "description": "Świątynia katolicka. Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Aubankathedraal", "description": "Kathedraal in Namen. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Albano", "description": "Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Aubain de Namur", "description": "Édifice religieux de style néo-classique situé à Namur en Belgique. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Сент-Обен", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Citadel of Namur', 'Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.46056, 4.86528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Namur%20JPG07.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Namur%20JPG07.jpg"}'::text[], 3, '{"en": {"name": "Citadel of Namur", "description": "Fortress in Namur, Belgium. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Zitadelle von Namur", "description": "Festung in Namur, Belgien. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Cytadela w Namur", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Citadel van Namen", "description": "Bouwwerk in Namen (stad), België. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Citadel of Namur", "description": "Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "citadelle de Namur", "description": "Citadelle de Belgique. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Намюр (фортеця)", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Maredsous Abbey', 'Památka v Belgii — kus historie přímo u trasy.', 50.30235, 4.76665, 'http://commons.wikimedia.org/wiki/Special:FilePath/Church%20Maredsous%20Abbey%2003.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Church%20Maredsous%20Abbey%2003.JPG"}'::text[], 4, '{"en": {"name": "Maredsous Abbey", "description": "Belgian Benedictine monastery. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Abtei Maredsous", "description": "Benediktinerkloster in der belgischen Gemeinde Anhée-Denée. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Maredsous Abbey", "description": "Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Maredsous", "description": "Abdij in Denée, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Maredsous", "description": "Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Maredsous", "description": "Édifice religieux belge. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Maredsous Abbey", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter Villers', 'Památka v Belgii — kus historie přímo u trasy.', 50.59056, 4.52972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Villers%20Abbey%20R08.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Villers%20Abbey%20R08.jpg"}'::text[], 5, '{"en": {"name": "Villers Abbey", "description": "Former abbey in Villers-la-Ville, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Kloster Villers-la-Ville", "description": "Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo w Villers-la-Ville", "description": "Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "abdij van Villers", "description": "Abdij in Villers-la-Ville, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Villers", "description": "Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Villers", "description": "Édifice religieux belge. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Villers", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Lake Genval', 'Vodní plocha v Belgii — příjemný cíl vyjížďky s výhledy na hladinu.', 50.72889, 4.51944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Genval%20Lac1a.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Genval%20Lac1a.JPG"}'::text[], 6, '{"en": {"name": "Lake Genval", "description": "Lake. A body of water in Belgium — a pleasant ride destination with waterside views."}, "de": {"name": "Lake Genval", "description": "See in Belgien. Ein Gewässer in Belgien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Genval", "description": "Akwen w Belgii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Genval", "description": "Meer in België. Een waterpartij in België — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Genval", "description": "Lago en Bélgica. Una masa de agua en Bélgica: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Genval", "description": "Un plan d''eau en Belgique — une belle destination avec vue sur l''eau."}, "uk": {"name": "Lake Genval", "description": "Озеро. Водойма у Бельгії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
